window.__D("text/likkutei-sichot/c021",{"p":[[1301670120,"שלמעלה מציוויי התורה, שמצד זה ישנו בכל יהודי הטבע למסור נפשו על יחוד שמו ית', גם כשאינו מחוייב בזה ע\"פ תורה [וזה שייך גם לענין המילה כ­פשוטה, כדאיתא בספרים<sup data-n=\"540\">51</sup> דענין המילה הוא \"לצרף. . את ישראל. . וצירוף זה היינו בחינה ונסיון אם ימסור נפשו על קדושת שמו ית' וכשירגיל עצמו מנעוריו באחד מאבריו יהי' נקל בעיניו גם כי יזקין למסור כל נפשו לשמים\"]<sup data-n=\"541\">52</sup>.\nד. והנה מכיון שגדר זה שבמילה, גדר המס\"נ שלמעלה מהתורה, נלמד מזה שמילה דוחה שבת, צריך לומר, שיש לזה ביטוי גם בגוף מעשה מצות המילה ביום השבת.\nויש לומר, שדבר זה נראה בזה גופא שאיש ישראל מל קטן מישראל ביום השבת:\nאף שמדובר במוהל אומן וה\"ז חשש רחוק שיקלקל במילה, הרי אפשר שלא יגמור המילה כדבעי, ונמצא מחלל שבת, כדמשמע בגמ'<sup data-n=\"542\">53</sup> שזה יתכן גם באומן<sup data-n=\"543\">54</sup>. זאת ועוד, דגם כשמל כדבעי, למה צריך הוא להכניס את עצמו בזה ולעשות פעולה דחילול שבת<sup data-n=\"543\">54</sup>. בשלמא האב ה\"ז מצוה דידי' למול את בנו<sup data-n=\"545\">55</sup> ביום השמיני, אבל אחר שאי\"ז מצותי'<sup data-n=\"546\">56</sup>, ומל במקום האב<sup data-n=\"547\">57</sup>, למה לו לעשות פעולה היפך משמירה שלו דשבת<sup data-n=\"548\">58</sup>?\nאלא, לפי שגדר ענין המילה בשבת ענינה גילוי העצם דישראל שלמעלה מהתורה, ולכן ה\"ז מודגש גם בפעולת המילה, שהמוהל מוכן למסור נפשו ברוחניות, לעשות מעשה דחילול שבת למול את התינוק.\nומוהל שאינו מוכן למסור נפשו ו­למול בשבת, אינו יכול למול גם בחול, כי הרי ע\"י המילה נעשית תחילת כניסת נפש זו הקדושה<sup data-n=\"549\">59</sup>, והיינו התקשרות עצמית זו דישראל בקוב\"ה שלמעלה מהתורה, ודבר זה אפשרי אם תכונה זו נראית במוהל הבא למול את התינוק להכניסו בבריתו של אברהם אבינו ע\"ה.",[["540","51","עוללות אפרים ח\"ג ע' יט מאמר תסט."],["541","52","ראה אוה\"ת שבועות (ע' קיח ואילך) ב­כריתות ברית דאברהם. וראה שם ע' קיט: \"וזהו ענין גילוי העטרה שהוא בחי' יו\"ד דחכמה עילאה כו' ובכל נפש מישראל מתגלה בפנימי' חכמה שבנפשו גילוי אא\"ס שבפנימי' חכמה עילאה ממש, ועי\"ז יכול למסור נפשו על קדושת השם כידוע\"."],["542","53","שבת קלג, ב: ואם לא הילקט ענוש כרת. מני א\"ר כהנא אומן כו'."],["543","54","ראה שו\"ע יו\"ד סו\"ס רסו ובנ\"כ שם ה­שקו\"ט כאשר לא גמר המילה ולענין ב' מוהלין."],["543","54","ראה שו\"ע יו\"ד סו\"ס רסו ובנ\"כ שם ה­שקו\"ט כאשר לא גמר המילה ולענין ב' מוהלין."],["545","55","ראה לשון אדה\"ז בשו\"ע או\"ח סשל\"א סי\"ג."],["546","56","ראה רש\"י יבמות עא, ב ד\"ה חבושין. ו­להעיר משו\"ע אדה\"ז או\"ח סתל\"ב קו\"א סק\"ב."],["547","57","להעיר מש\"ך חו\"מ סי' שפב סק\"ד דלדעת הרא\"ש (חולין פ' כיסוי הדם ס\"ח) לא מהני שליחות במילה — ראה קצוה\"ח חו\"מ שם סק\"ב."],["548","58","בטור יו\"ד סרס\"ו מביא מר\"א הלוי, ד\"אם האב יודע למול אין לו למול בשבת אם יש אחר שיודע למול דהא מילה הוא פסיק רישא גבי דידי' דהוא מכוין לתקן את בנו אבל לגבי אחר לא מקרי תיקון ושרי\". אבל ראה תרומת הדשן סרס\"ה (הובא בב\"י ובב\"ח שם) דאין חילוק בזה<sup data-n=\"e12\">*</sup>. וראה שאגת ארי' סנ\"ט, ושם דגם לר\"א הלוי גם ע\"י אחר איכא חילול."],["549","59","שו\"ע אדה\"ז או\"ח מהד\"ת סוס\"ד."],["e12","*","ולכאורה כ\"ה לפי פסק השו\"ע (וראה רמ\"א) שם ס\"ז. שו\"ע אדה\"ז שבהערה 55."]]],[1301670121,"ה. ויש לומר, דענין זה, שממילת אברהם בא ונמשך לישראל ענין זה שבמילה שהיא למעלה מגדרי התורה, נראה גם בעצם מילת אברהם:\nאיתא בפרקי דר\"א<sup data-n=\"550\">60</sup> דמילת אברהם היתה ביום הכפורים<sup data-n=\"551\">61</sup>. ולכאורה צ\"ב, דכיון שקיים אברהם אבינו כל התורה כולה עד שלא ניתנה<sup data-n=\"552\">62</sup> איך מל א\"ע ביוהכ\"פ, והרי מילה שלא בזמנה אינה דוחה את השבת ולא את היו\"ט<sup data-n=\"553\">63</sup>?\nוהנה ע\"פ פשט לא קשה, דכיון שאז נצטווה על המילה, ד\"בו ביום שציוהו מל\"<sup data-n=\"554\">64</sup>, ה\"ז מילה בזמנה שדוחה שבת ויו\"ט. אבל ע\"פ פנימיות הענינים יש לומר, דלהיות שמילת אברהם היתה בבחינה זו שלמעלה מגדרי התורה, לכן גם מילתו בפועל היתה באופן שקיום המצוה דחה שבת וגם שבת שבתון דיום הכפורים.\nוע\"פ הנ\"ל — דהא דלמדים מפרשת מילה דאברהם דמילה דוחה שבת, שייך להתקשרות עצמית דישראל בקוב\"ה ו­ענין המסירת נפש שלמעלה מהתורה — יומתק ביותר הא דמילת אברהם היתה ביום הכפורים דוקא<sup data-n=\"555\">65</sup>, כי זה שייך לה­כפרה דיוהכ\"פ, וכדאיתא בפרקי דר\"א שם (בהמשך להלימוד דביום הכפורים נמול אברהם, \"אתיא עצם עצם מיום הכפורים\") \"וכל שנה ושנה הקב\"ה רואה דם הברית של מילה של אברהם אבינו ומכפר על כל עונותינו שנאמר<sup data-n=\"556\">66</sup> כי ב­יום הזה יכפר עליכם לטהר אתכם וגו'\", כי אמיתית כפרת יום הכפורים היא מה שעיצומו של יום מכפר<sup data-n=\"557\">67</sup>, וענינה הוא גילוי ההתקשרות העצמית של ישראל בקוב\"ה שלמעלה מכל גדר פגם (ול­מעלה מהתורה), ובבחינה זו לא מגיע מעיקרא כל ענין החטאים ועוונות, ולכן כאשר מתגלית בחינה זו בישראל מתכפרים ממילא כל הפגמים, כמבואר במ\"א בארוכה<sup data-n=\"558\">68</sup>.\nו. וזהו שהג' לימודים הנ\"ל מבטאים ג' ענינים שישנם במילה:\nא) מה שהיא א' מתרי\"ג מצות התורה, אלא שבזה גופא ה\"ה גדולה<sup data-n=\"559\">69</sup> מהם ולכן היא דוחה את המצות דשבת.\nב) מה שהיא מצוה כללית, שהיא שקולה כנגד כל המצות<sup data-n=\"560\">70</sup>, ולכן קיומה הוא גם בשבת, כי זה פועל שלימות בהאות של הקב\"ה בישראל, ביני ובין",[["550","60","פכ\"ט, הובא בתוד\"ה אלא (ר\"ה יא, א)."],["551","61","ובתוס' שם עוד דיעה, שהי' בט\"ו ניסן יו\"ט דפסח."],["552","62","ראה יומא כח, ב. משנה סוף קידושין. פרש\"י תולדות כו, ה (מב\"ר פס\"ד, ד. וש\"נ)."],["553","63","שבת קלב, ב. קלג, א. רמב\"ם הל' מילה פ\"א ה\"ט. טושו\"ע יו\"ד ר\"ס רסו."],["554","64","ל' התוס' ר\"ה שם בסופו. פרש\"י פרשתנו יז, כג."],["555","65","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610102\" data-slug=\"or-hatorah-hb\" data-id=\"8316610102\">אוה\"ת</a> פרשתנו (כרך ד) תשל, ב."],["556","66","אחרי טז, ל."],["557","67","ראה שבועות יג, א ואילך — דעת רבי. וראה רמב\"ם הל' תשובה פ\"א ה\"ג (דאף שפסק כרבנן דיוהכ\"פ מכפר רק על השבים, כ' הלשון) \"ועצמו של יוהכ\"פ מכפר לשבים (שנאמר כי ביום הזה יכפר עליכם)\". וראה בהנסמן בהערה הבאה, שלכו\"ע עיקר הכפרה דיוהכ\"פ הוא מה שעיצומו של יום מכפר, אלא שלדעת רבנן, בכדי להגיע לכפרה זו צריך לתשובה. ואכ\"מ."],["558","68","ראה לקו\"ש ח\"ד ע' 1150 ואילך. ועוד."],["559","69","כבמשנה נדרים לא, ב: גדולה מילה ש­דוחה את השבת החמורה."],["560","70","גי' הע\"י בש\"ס בסיום המשנה נדרים שם. וכ\"ה גי' הר\"ן והתוס' (והובא עה\"ג בש\"ס שם). ובשל\"ה חלק תושב\"כ פרשתנו (רעט, ב) בהגהה: מילה שקולה נגד כל התורה וכן ברית מילה עולה תרי\"ג כי ברית תרי\"ב ובתוספת מצות מילה תרי\"ג."]]],[1301670122,"בני ישראל אות היא לעולם, בריתי בבשרכם לברית עולם<sup data-n=\"561\">71</sup>.\nג) זה שהיא למעלה מהמדידה והג­בלה דתורה ומצות, השייכת לברית והת­קשרות עצמית דבנ\"י בקוב\"ה, וקשר זה מתבטא במילת אברהם עצמו, \"בעצם היום הזה נימול אברהם\"<sup data-n=\"562\">72</sup>, שנמול ביום הכפורים, שבת שבתון.\n<span data-k=\"q\">(משיחות ליל שמח\"ת תיש\"א; ש\"פ נשא תשמ\"א)</span>",[["561","71","בסגנון אחר — שהוא שייך לקדושת ישראל שהם העושים את השבת, \"לעשות את השבת\" (ראה ד\"ה את שבתותי תשמרו ה'ש\"ת)."],["562","72","פרשתנו יז, כו. וראה תו\"א סוף פרשתנו."]]],[1301670123,"<h3>שיחה א</h3>\nא. בחיוב דחינוך הקטנים, איתא בכ\"מ ד\"חינוך מדרבנן\"<sup data-n=\"563\">1</sup>, אבל מן התורה ליכא חיוב חינוך — ודרוש ביאור:\nכיון שמן התורה ברגע שהקטן נעשה גדול חייב מיד בקיום כל מצוות התורה, א\"כ באם אין חיוב מן התורה להכינו לזמן גדלותו, יעבור על מצות התורה מחמת חסרון ידיעה וחוסר הכנה?\nבפשטות יש לומר, שזה נכלל במצוה הכללית דתלמוד תורה, \"מצות עשה מן התורה על האב ללמד את בנו הקטן תורה. . שנאמר<sup data-n=\"564\">2</sup> ולמדתם אותם את בניכם לדבר בם\"<sup data-n=\"565\">3</sup>, וכמו שפי' הרמב\"ן בפסוק<sup data-n=\"566\">4</sup> \"ושננתם לבניך\", \"מאחר שציוה במצות חוקת עולם לדורותיכם<sup data-n=\"567\">5</sup>. . הנה אנחנו מצווים שידעו בנינו המצוות<sup data-n=\"568\">6</sup>, ואיך ידעו אותם אם לא נלמדם\"<sup data-n=\"569\">7</sup>. ולפ\"ז ישנו מן התורה חיוב של חינוך בתור הכנה לקיום המצות בגדלותו, ואדרבה, זהו יסוד ה­מצוה הכללית דת\"ת לבנים, כנ\"ל.\nאלא שמן התורה המצוה היא \"שידעו בנינו המצות\", ואתו רבנן ותיקנו שגם מצוה לחנך את הבן בקיום המצות, וכמ\"ש ראשונים, שהוא כדי \"להרגיל את הקטן למצוה. . כדי שיהא מחונך ורגיל ל­מצוות\"<sup data-n=\"570\">8</sup>, \"להנהיגו שיהא סרוך אחר מנהגו לכשיגדיל\"<sup data-n=\"571\">9</sup>, כענין שנאמר<sup data-n=\"572\">10</sup> \"חנוך לנער על פי דרכו גם כי יזקין לא יסור ממנה\"<sup data-n=\"573\">11</sup>.\nאבל לכאורה אין זה מספיק<sup data-n=\"574\">12</sup>: כיון",[["563","1","נזיר כט, א. חגיגה ד, א. וש\"נ. ובכ\"מ. וראה ברמב\"ם בכ\"מ לענין מצות פרטיות: הל' ציצית פ\"ג ה\"ט. הל' ברכות פ\"ה ה\"א. הל' שביתת עשור פ\"ב ה\"י. הל' סוכה פ\"ו ה\"א. ועוד. וראה אנציקלופדי' תלמודית ערך חנוך בתחלתו. וש\"נ."],["564","2","עקב יא, יט."],["565","3","הל' ת\"ת (להרמב\"ם ו)לאדה\"ז בתחלתן."],["566","4","ואתחנן ו, ז."],["567","5","ויקרא ג, יז. וראה גם תשא (לא, יז), לך (יז, י) — הובא ברמב\"ן שם."],["568","6","וראה בה\"ג בהקדמתו — מנין המצוות (קום עשה עא) \"למד בנך תורה ומצות\", וכ\"ה בסמ\"ג (מ\"ע יב וברמזי המצות בראש הספר) וביראים (הש­לם סי' רכה)."],["569","7","ובפי' רבינו מיוחס עה\"ת (ירושלים תשכ\"ח) עקב יא, יט: ולמדתם אותם. תרגילו את בניכם להיות עסוקים תמיד בתורה. . כדי שירגיל בכך ואף בכל המצוות, וכן שלמה אומר חנוך לנער כו'<sup data-n=\"e13\">*</sup> [וברמב\"ן עקב שם, יח: הוסיף בכאן ולמדתם אותם כי ושננתם שיספר להם המצות וכאן עד שילמדו אותם וידעום ויבינו אותם וטעמיהם]. ובמאירי (קידושין ל, א) \"האב חייב בלימוד תורת הבן. . עד שידע ענין המצוות ויקיים אותם כראוי\". ובבמדב\"ר פי\"ז, א (וראה תנחומא שלח יד ובעץ יוסף שם) \"שנו רבותינו ה' דברים האב חייב לעשות לבן כו' ללמדו תורה כו' ללמדו מצות כו'\" (וראה מפרשים שם)."],["570","8","רש\"י סוכה ב, סע\"ב ד\"ה מדרבנן."],["571","9","רש\"י חגיגה ו, א ד\"ה קטן."],["572","10","משלי כב, ו."],["573","11","וכן ברשב\"א (מגילה יט, ב) ובריטב\"א (סוכה שם) הזכירו הכתוב ד\"חנוך לנער\" לענין חובת חינוך דרבנן. אבל בגמ' קידושין ל, רע\"א מבואר דקאי בבן גדול, וכמ\"ש אדמו\"ר הזקן בהל' ת\"ת פ\"א ס\"ו. ובפשטות זהו הטעם שלא הביאו אדה\"ז בשו\"ע הל' שבת סשמ\"ג לענין חובת חינוך. וצע\"ק בלשונו בשו\"ת (סי' מא — נדפס בסוף השו\"ע, וכן בספר בפ\"ע) \"דהתם (בחגיגה) מיירי במ\"ע המוטלת על האב לחנך בה בנו כדי שיקיים מעצמו כשיגדיל שזו היא מצות חינוך כדכתיב חנוך לנער כו'\"."],["574","12","נוסף ע\"ז שלא מצינו כן דעת רוב ה­ראשונים והפוסקים שמצות ת\"ת היא כעין חינוך שידע המצות וכו', כ\"א שמצות ת\"ת היא א' ממצות הבן המוטלת על האב לעשות לבנו, שבנו ילמד\nתורה, וע\"ד מצות מילה ופדיון הבן, כפשטות הסוגיא בקידושין (כט, א)."],["e13","*","להעיר גם מלשון אדה\"ז בקו\"א בהל' ת\"ת (פ\"א סק\"א [תתכח, א]) \"חינוך לתורה דאורייתא על האב\"."]]],[1301670124,"שידיעת המצות עצמה אינה די' שיקיימן בפועל כשיגדיל, וכדמוכח מזה גופא שחכמים חייבו לחנכו בקיום המצות ב­פועל שיתרגל בהן, הרי, שמן התורה, כשיגדל הקטן ויגיע לגיל י\"ג שנה ויום אחד, חסר בהכנתו והכשרתו השלימה כדי שיוכל לקיים בפועל כל המצוות כדבעי כשיגדל. דאם נתרגל הקטן להתנהג ללא שמירת התורה והמצוות, הרי גם אם יודע (בשכלו ומחשבתו) הלכות כל המצוות, אי אפשר שבן רגע יתחיל לקיימן כולן בפו­על כדבעי (היפך טבעו ומנהגו הקודם).\nב. לכאורה יש לומר, שאכן ישנה חובת חינוך<sup data-n=\"575\">13</sup> מדאורייתא<sup data-n=\"576\">14</sup> [ולא רק ב­ידיעת המצות] — ובהקדם:\nכשהתורה מחייבת לקיים איזו מצוה, ולדוגמא הנחת תפלין, פשוט שאין החיוב רק למי שיש לפניו זוג תפלין שמחוייב להניחן, אלא המצוה מחייבתו לעשות כל הדרוש כדי להשיג תפלין, ואם לא הש­תדל ומשו\"ז לא הניחן ביטל מ\"ע. ועד\"ז בכמה מצוות, שמחוייב מה\"ת לעשות כל הדרוש כדי שיוכל לקיים המצוה, ובל' הרמב\"ם<sup data-n=\"577\">15</sup> \"יש מצות עשה שאדם חייב להשתדל ולרדוף עד שיעשה אותה כגון תפלין וסוכה ולולב ושופר\". ואף שגוף החיוב אינו אלא פעולה מסויימת כהנחת תפלין ונטילת לולב מ\"מ חיוב זה עצמו מחייבו בכל ההכנות הדרושות כדי שיוכל לקיים (פעולת) המצוה. ועוד זאת, שאם לא השתדל ללמוד ולידע איך לקיים המצוה, ולכן לא קיימה כהלכתה, הרי גם זה חשוב מבטל מ\"ע.\nוא\"כ, בקטן שנעשה גדול, שאז מתחייב מיד מדאורייתא בקיום כל התורה כולה, הרי כיון שא\"א שיקיים כל המוטל עליו בלי הכנה קודמת, הן לימוד וידיעת ה­מצות, והן הכנתו והכשרתו שיתרגל לקיי­מם בפועל (שזהו ע\"ד ההשתדלות להשיג תפילין או לולב וכיו\"ב), א\"כ הכנה זו היא ג\"כ, לכאורה, חובה מה\"ת<sup data-n=\"578\">16</sup>. ומאחר שישנו חיוב על הקטן להכין עצמו לגדלותו אלא שקטן אינו בר­חיובא, לכן יש מקום לומר שחיוב זה עובר אל האב [וע\"ד מ\"ש הריב\"ש<sup data-n=\"579\">17</sup> לגבי פדיון הבן, ש\"עיקר ה­מצוה בעצמו אלא שבקטנותו אי אפשר\"<sup data-n=\"580\">18</sup>, ולכן הוטל על האב].\nאלא שאעפ\"כ אין חובה זו בגדר מצוה, כי אם רק הכשר והכנה בלבד, ע\"ד וב­דוגמת כריתת עצים לעשות פחמים לע­שות ברזל (איזמל למילה)<sup data-n=\"581\">19</sup>. וזהו שנתוסף במצות חינוך שמד\"ס, שיש בזה גדר חיוב",[["575","13","להעיר שיש אחרונים (נסמן באנציקלופדי' תלמודית שם ע' קסב) דס\"ל שמהפסוק \"חנוך לנער גו'\" יש להוכיח שחיוב החינוך הוא מצות עשה מדברי קבלה. וי\"א (נסמן שם) שמקורו בתורה — כמ\"ש (פרשתנו יח, יט) \"כי ידעתיו למען אשר יצוה את בניו גו' ושמרו דרך ה' גו'\"."],["576","14","ולהעיר ממ\"ש הרמב\"ן גבי מצות הקהל (וילך לא, יג) \"ובניהם אשר לא ידעו ישמעו ולמדו. הם הטף כי ישמעו וישאלו והאבות ירגילום ויחנכו אותם, כי אין הטף הזה יונקי שדים אבל הם קטני השנים הקרובים להתחנך כו'\", אלא שסיים \"אבל רבותינו אמרו (חגיגה ג, א) האנשים ללמוד. . והטף למה בא ליתן שכר למביאיהם\", והיינו דמזה מוכח דאינו משום חינוך. וראה מהרש\"א חגיגה שם ד\"ה נשים. ובארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191377\" data-slug=\"likkutei-sichot\" data-id=\"1300191377\">לקו\"ש חי\"ט ע' 364</a> ואילך."],["577","15","הל' ברכות פי\"א ה\"ב."],["578","16","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171070\" data-slug=\"likkutei-sichot\" data-id=\"1300171070\">לקו\"ש חי\"ז ע' 70</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261075\" data-slug=\"likkutei-sichot\" data-id=\"1300261075\">חכ\"ו ע' 75</a> ואילך. וש\"נ."],["579","17","בתשובותיו סקל\"א."],["580","18","ובאו\"ז ח\"ב סי' קד משמע דכן הוא נמי לענין מילה. אבל ראה שו\"ת הר\"ן סי' נב. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111052\" data-slug=\"likkutei-sichot\" data-id=\"1300111052\">לקו\"ש חי\"א ע' 44</a> ואילך ובהערות שם. וש\"נ."],["581","19","שבת קל, א (ובפרש\"י ד\"ה לעשות) וש\"נ — שלדעת ר\"א כ\"ז בגדר מכשירי מצוה שדוחין את השבת."]]],[1301670125,"המצוה. ויש לומר, שמצד החיוב מן התורה אין עשיית הקטן עצמה בגדר קיום מצוה, כ\"א עשי' כדי שיתרגל, ואילו מדרבנן עשיית הקטן היא בגדר מצוה, ולכן מן התורה קיום המצוה שעושה הקטן אינו צריך להיות בכל הפרטים, בהכשר גמור, כי מצד ההכנה אין נפק\"מ כ\"כ אופן עשייתו, משא\"כ מצד מצות חינוך דרבנן צריך שהקטן יקיים המצות בכל הפרטים כגדול<sup data-n=\"582\">20</sup>.\nג. ואת\"ל מצינו כעין זה בפירוש רבי­נו מנוח במ\"ש הרמב\"ם בהל' שביתת עשור<sup data-n=\"583\">21</sup>, \"קטן בן תשע שנים ובן עשר שנים מחנכין אותן לשעות כיצד הי' רגיל לאכול בשתי שעות ביום מאכילין אותו בשלש הי' רגיל בשלש מאכילין אותו בארבע לפי כח הבן מוסיפין לענות אותו בשעות בן אחת עשרה שנה בין זכר בין נקבה מתענה ומשלים מדברי סופרים כדי לחנכו במצות\".\nוכתב ע\"ז רבינו מנוח: \"ומה שכתב הרב כאן כדי לחנכו במצות ולעיל נמי כתוב מחנכין אותו לשעות בא להודיענו דתרי חנוכי הוו כדאמרינן בגמרא<sup data-n=\"584\">22</sup> אמר רבה תרי חנוכי הוו חד לעינוי וחד להשלמה, וחנוך השעות אינו חובה מדרבנן אלא חובה המוטלת על כל אדם מעצמו ללמד ולהרגיל בניו ללכת בדרכי יושר כדכתיב חנוך לנער על פי דרכו וגומר וכדי להכניסם תחת כנפי השכינה. . אבל בחינוך שני דהיינו כשהם בני י\"א שנה שחייבין להשלים מדרבנן שוין בו תינוק ותינוקת. . וז\"ש הרב כאן מתענה ומשלים מדברי סופרים ולמעלה כתב מחנכין אותו ולא כתב מחנכין אותו לשעות מד\"ס לפי שאין חנוך שעות מדרבנן כלל שאין מדרבנן חיוב חנוך בלא השלמה כלומר שיעשה המצוה כתקנה וכמשפטה בשל­מות\", עכ\"ל.\nומדבריו נראה דישנו חיוב כללי (ד­ילפינן מקרא ד\"חנוך לנער\") לחנך בניו שילכו בדרך התורה והמצוות<sup data-n=\"585\">23</sup>, וחיוב זה מאחר שאינו אלא להרגילם במצוות אינו מחייב שיתקיימו המצוות כתקונן וכהל­כתן. ונוסף על זה חייבו חכמים שהקטן יעשה כל מצוה ומצוה כמשפטה ובכל פרטי' כעשיית הגדול.",[["582","20","כמו שהוכיח הריטב\"א (סוכה ב, ב) מהא דמבואר שם בגמ' דאין לחנך קטן בסוכה פסולה (למעלה מעשרים). וכ\"כ הר\"ן ליומא פב, א. וראה לקמן בפנים מרבינו מנוח."],["583","21","פ\"ב ה\"י."],["584","22","יומא פב, א."],["585","23","ע\"פ דבריו יש לבאר לכאו' דברי הרמב\"ם בהל' מאכא\"ס פי\"ז הכ\"ז: קטן שאכל אחד ממאכלות אסורות או שעשה מלאכה בשבת אין בית דין מצווין עליו להפרישו לפי שאינו בן דעת כו'. ובהל' כח: אע\"פ שאין בית דין מצווין להפריש את הקטן, מצוה על אביו לגעור בו ולהפרישו כדי לחנכו בקדושה שנא' חנוך לנער על פי דרכו וגו'. [ועד\"ז כתב בהל' אבל פ\"ג הי\"ב: כהן קטן הרי הגדולים מוזהרים שלא יטמאוהו. ואם בא להטמא מעצמו אין בית דין מצווין עליו להפרישו, אבל אביו צריך לחנכו בקדושה] —\nדלכאורה: דין חובת חינוך במצוות מובא ב­רמב\"ם כמה פעמים לפנ\"ז לענין כו\"כ מצות (כנ\"ל הערה 1), ואינו מביא שם הכתוב ד\"חנוך לנער\", ואמאי הביאו דוקא כאן. גם מהו הל' \"לחנכו בקדושה\", ולא כמ\"ש לפנ\"ז כמה פעמים \"לחנכן במצות\".\nוי\"ל דס\"ל להרמב\"ם דהחובה להפרישו מ­איסורא באה מהחיוב הכללי לחנכו בדרך התורה מקרא ד\"חנוך לנער\"<sup data-n=\"e14\">*</sup> ואין זה חינוך פרטי בכל האיסורים (כדרך שתיקנו חכמים חיוב פרטי בכל מ\"ע) כ\"א חיוב כללי לחנכו בקדושה. וראה בהערה שלאחרי הערה הבאה הדיעה דחינוך במל\"ת הוא דאורייתא."],["e14","*","שהוא מדברי קבלה (ראה לעיל הערה 13), ויותר מחיוב חינוך סתם שהוא מד\"ס. או יתרה מזה, דהוי מדאורייתא והכתוב גילוי מילתא בעלמא, כדלקמן בפנים."]]],[1301670126,"ויש לומר, שמ\"ש רבינו מנוח שם ד\"חינוך השעות אינו חובה מדרבנן אלא חובה המוטלת על כל אדם מעצמו כו'\", ר\"ל דהאחריות של האב לחנך בנו (באופן כללי) מוכחת מסברא, והאדם מחוייב בה מעצמו מבלי שיהי' ע\"ז ציווי וחיוב מפורש.\nכלומר: מכיון שמן התורה מחוייב כל אחד מעת שהגיע לגיל י\"ג שנה ויום א' לקיים כל התורה והמצות, הרי מובן ופשוט שכל איש ישראל יחנך וירגיל את בניו \"ללכת בדרכי יושר\", דרך התורה והמצוה, כשם שפשוט שכל אדם ישר הולך מדריך ומחנך את בניו בדרך הטוב והישר מבלי שיהי' לו ציווי ע\"ז, כי זהו טבעו של אב, ובלשון הכתוב<sup data-n=\"586\">24</sup> גבי אבר­הם \"יצוה את בניו ואת ביתו אחריו לעשות צדקה ומשפט\".\nועפ\"ז י\"ל שיש בזה גדר דאורייתא<sup data-n=\"587\">25</sup>, וכמבואר בכ\"מ בש\"ס דדבר המוכח מס­ברא הוא מה\"ת<sup data-n=\"588\">26</sup> [והכתוב בדברי קבלה \"חנוך לנער וגו'\" הוא גילוי מילתא ב­עלמא].\nד. אולם לכאורה חידוש גדול הוא לומר שישנה חובת חינוך מדאורייתא<sup data-n=\"589\">27</sup>, ולא הוזכר זה בפוסקים, אלא כולם נקטו דחובת החינוך אינו אלא מד\"ס, וכמפורש בלשון אדמו\"ר הזקן בשלחנו ריש הל' ת\"ת הנ\"ל \"שהקטן פטור מכל המצות וגם אביו אינו חייב לחנכו במצות מן התורה אלא מד\"ס כו'\"<sup data-n=\"590\">28</sup>.\nועפ\"ז כיון שמה\"ת ברגע שקטן נעשה גדול מחוייב מיד בקיום כה\"ת כולה, ואם לא נתחנך ונתרגל במצוות לפנ\"ז מן הנמנע שיוכל להזהר כדבעי בכל מ\"ע ומל\"ת מיד כשיגדל, א\"כ איך אפשר לומר דאין חיוב מה\"ת להכינו ולהכשירו לזמן גדלותו לבל יעבור על מצוות התורה מחמת (חסרון ידיעה ו)חוסר הכנה<sup data-n=\"591\">29</sup>. ועוד, ע\"פ משנת\"ל דמצד חיוב המצות שיחולו תיכף כשיגדל איכא חובת הכנה שברגע שית­",[["586","24","פרשתנו יח, יט. וראה לעיל הערה 13."],["587","25","יש להעיר דמצינו דיעה מפורשת דישנו גדר של חינוך מדאורייתא, והוא בתרומת הדשן (פסקים סי' סב) שכ' דקטן העובר עבירה בקטנותו א\"צ לעשות תשובה ע\"ז כשיגדיל דקטן אינו בר אזהרה כלל כדמוכח מהא דקטן אוכל נבילות אין ב\"ד מצווין להפרישו (יבמות קיד, א) — \"והא דאייתי קרא (יבמות שם) דאסרה תורה דלא ליספו לי' בידים יש לומר הטעם דקפיד רחמנא שלא ירגיל אותו לעבור עבירות וכשיגדל יבקש לימודו\". אבל בשו\"ת חת\"ס (או\"ח ספ\"ג) כ' ד\"זה אינו עיקר דלא דרשינן טעמי' דקרא\", ע\"ש. ובשו\"ת אדמו\"ר הזקן הנ\"ל סי' מא \"אבל למספי איסור בידים לקטן דאסור לכ\"ע לאו משום חינוך אתינן עלה אלא מדכתיב לא תאכלום כו', דחינוך אינו מוטל אלא על האב בלבד. . ע' א\"ח סי' שמג\". וכן מוכח לכאורה ממה שפסק בהל' שבת (שם) ס\"ה \"לספות לו איסור בידים אסור לכל אדם מן התורה אפילו אינו בר הבנה כלל שנא' לא תאכלום כו'\"."],["588","26","בכתובות כב, א (ועוד) \"למה לי קרא סברא הוא\". וראה פנ\"י ברכות לה, סע\"א. בית האוצר מערכת א כלל קלא. ושם (בסופו) מביא מחזקוני (נח ז, כא) \"יש כמה מצות שחייבים בני אדם לשמרן מכח סברת הדעת אע\"פ שלא נצטוו\"."],["589","27","בכללות המצות. וגם במצות פרטיות כמו הקהל (הנ\"ל הערה 14), הרי נוסף ע\"ז שבכמה מקו­מות משמע שאין זה בגדר חינוך, הרי מלשון הרמב\"ן עצמו \"קטנים הקרובים להתחנך\" מובן שאין זו מצות חינוך באופן הרגיל. וכן ב\"ליספו לי' בידים\" לדעת התרוה\"ד (הנ\"ל הערה 25), הרי פשוט שאינה דומה הקפידה שירגיל עצמו באיסור לשאר עניני חינוך."],["590","28","ובאו\"ח סשמ\"ג ס\"ב וכן במהד\"ת סוף סי' ד כ' (רק) שהוא חיוב \"מד\"ס\", \"שחייבו חכמים\"."],["591","29","יש לדון אם אפשר לחייב האב (או כל מי שיש בידו) לחנך הבן מחמת \"לפני עור\", דכיון דקטן אינו יכול לחנך את עצמו, והוא נמצא ברשותו של האב, א\"כ בזה שאינו מחנכו ה\"ה מכשילו, והוי כתרי עברי נהרא."]]],[1301670127,"גדל יוכל לקיימן, והרי חובה זו קיימת ועומדת אלא שא\"א שתחול על הקטן שאינו בר דיעה, ולמה לא העבירה התורה החיוב על האב או הב\"ד, וכנ\"ל.\nה. ונראה, דמה שנת\"ל (סעיף ב), דכיון שמיד כשהגדיל הקטן ה\"ה מתחייב בכל המצוות כולן, לכן אם לא קיימן או עבר עליהן מחמת חסרון ידיעה והכנה קודמת נחשב כמבטל מ\"ע וכעובר על מל\"ת — אינו מוכרח. ובהקדים:\nכשהתורה מחייבת באיזו מצוה, פשוט שהחיוב חל רק באופן שתוכל להתקיים בדרך הטבע, דלא ניתנה תורה למלאכי השרת<sup data-n=\"592\">30</sup>, ואם קיומה דורש שהיית זמן אינו עובר על החיוב כל משך אותו הזמן. ולדוגמא, במצות ביעור חמץ, הרי כל זמן שעוסק בביעורו עד שנתבער בפועל אינו עובר על מצות תשביתו. דזהו גדר המצוה — לעשות מה שביכולתו לבער החמץ, ואם מתעסק בזה ה\"ה עוסק בקיום המצוה. ובלשון אדמו\"ר הזקן<sup data-n=\"593\">31</sup> \"מתחילת שעה ז'. . כל רגע ורגע שנמצא חמץ ברשותו ואינו מתעסק לבערו הוא עובר על מ\"ע של תורה\", משא\"כ כשמתעסק בביעורו הרי ההתעסקות היא חלק מקיום המצוה (היינו ההתעסקות בהכנת הביעור, ולא רק העסק בעצם הביעור). ואין זה שייך לדין אונס רחמנא פטרי' (שנאמר, שמאותו רגע של מציאת החמץ ה\"ה עובר על מצות השבתה, אלא שכל הזמן הנדרש כדי לבערו נחשב כאנוס, ורחמנא פטרי'), דזה שייך רק אם כבר חל החיוב ונאנס ע\"י דבר צדדי שמעכב קיומו, אבל אם מעצם טבע הדברים אי אפשר לקיים החיוב מבלי שהיית זמן או הכנה והכשרה מוק­דמת הרי זהו חלק מהחיוב.\nוהנה במצות שקיומן בזמנים מיוחדים, אם קיום המצוה דורש הכנה והכשרה, כגון תקיעת שופר שצריך להתאמן ולהת­רגל כדי שיוכל לתקוע, או אם צריך השתדלות מוקדמת כדי להשיג חפצי המצוה כמו ד' מינים וכדומה, מובן לכ­אורה שחיוב ההכנה מתחיל לפני זמן קיום המצוה כדי שבבוא זמנה יוכל לקיימה כתיקונה<sup data-n=\"594\">32</sup>. ולהעיר דהחיוב לקיים כל ה­תורה כולה הוא חיוב תמידי, וגם מצוות",[["592","30","ברכות כה, ב. וש\"נ. ולהעיר מבכורות (יז, ב) \"ת\"ש (דאפשר לצמצם בידי אדם) ממדת כלים. . דרחמנא אמר עביד ובכל היכי דמצית למיעבד ניחא לי'\". וראה ע\"ז (ג, א) \"אין הקב\"ה בא בטרוניא עם בריותיו\". ובשמו\"ר (פל\"ד, א) \"לא בא על האדם אלא לפי כוחו\"."],["593","31","או\"ח ר\"ס תמה."],["594","32","על דרך זה מצינו לענין מ\"ע דתשביתו — בפסחים ו, א: א\"ר הא דאמרת (המפרש והיוצא בשיירא) קודם שלשים יום אין זקוק לבער לא אמרן אלא שאין דעתו לחזור אבל דעתו לחזור אפילו מראש השנה זקוק לבער (דכי הדר בי' בימי הפסח עבר עלי' וההיא שעתא לאו ברשותי' היא דלבטלי' כו' — רש\"י). ובשו\"ע אדמו\"ר הזקן או\"ח סתל\"ו ס\"ו: \"וזה שיוצא מביתו ולא יחזור קודם הפסח שכשיגיע חצות יום י\"ד לא יוכל לבדוק ולבער החמץ שבביתו הרי בשעה זו שהוא מפליג מביתו חל עליו מצות תשביתו מן התורה<sup data-n=\"e15\">*</sup>, שמן התורה אין חילוק בין תוך ל' יום לקודם ל'\" (וראה קו\"א סתל\"ב סק\"א ומה שהביא שם מהרא\"ש פ\"ק דפסחים ס\"י).\nובמנ\"ח (מצוה ה אות ז) מביא מ\"ש הצל\"ח (פסחים ג, ב) ש\"לא מצינו (במי שהוא בדרך רחוקה) שיהי' מחוייב לעלות ולהתקרב קודם זמן הפסח\" כדי שיוכל להקריבו, וכתב ע\"ז המנ\"ח \"ודבריו אינם מובנים לי כלל, דודאי מצות עשה על כל ישראל לעשות הפסח ככל מ\"ע שבעולם, ומחוייב לילך מקצה הארץ להתקרב עצמו כדי לקיים מ\"ע. . אטו לולב ושופר כי לא יהי' מחוייב לקנות קודם החג, ובחג אינו בנמצא, וכי אינו מבטל בזה המ\"ע, אתמהה\". ובפשטות גם הצל\"ח יודה דבשאר המצוות מחוייב להכין א\"ע קודם הזמן, ודבריו אמורים רק לענין דרך רחוקה שהוא פטור מיוחד<sup data-n=\"e16\">**</sup>. ובשאילת יעב\"ץ סקכ\"ז \"בודאי א\"א לומר ג\"כ שהרחוקים מאד יתחייבו לעלות לרגל מתחילת השנה לעשות הפסח. . ונלע\"ד שכך הוא הענין, ששלשים יום לפני הפסח חל חובת עשייתו על הרחוקים שיעתיקו מבתיהם. . מזמן שחל חובת ביעור חמץ כו'\", ע\"ש."],["e15","*","וכן משמע בחינוך מצוה ט שכ' \"ומאימת מוטל עליו המצוה אם יוצא לדרך כו'\" וקאי במ\"ע דתשביתו מה\"ת."],["e16","**","אבל ראה לקח טוב שבהערה הבאה \"המקום הי\"א\"."]]],[1301670128,"שעצם קיומן צ\"ל בזמן מסויים, מ\"מ החיוב שיתקיימו בזמנן הוא תמידי. ולכן מי שנתעצל להשיג ד' מינים קודם החג, ולכן לא הי' יכול לקיים מצות נטילתם בזמנה, נחשב כמבטל מ\"ע<sup data-n=\"595\">33</sup>.\nאמנם בקטן שנתגדל, כיון שקטן פטור מכל התורה כולה, ולא שייך בי' (בהיותו קטן) שום סרך של חיוב מה\"ת<sup data-n=\"596\">34</sup>, והתחלת",[["595","33","ובלקח טוב (להר\"י ענגיל) כלל ו אות ג (ד\"ה ואמנם נלע\"ד ואילך) האריך בענין זה (אם יש חיוב גם קודם זמן המצוה), ומביא מבעה\"מ ספ\"ק דשבת שכ' בטעמא דאין מפליגין בספינה פחות משלשה ימים קודם לשבת ד\"מקום סכנה הוא וכל שלשה ימים קודם לשבת קמי שבתא מקרי ונראה כמתנה לדחות את השבת מפני שאין דבר שעומד בפני פקוח נפש\", הרי דלפני ג' ימים קודם שבת אינו מחוייב לדאוג על שמירת השבת. אבל יש לחלק, דהתם הרי מה שיעשה בשבת הוא בהיתר כיון שפקו\"נ דוחה שבת, ואין האיסור בפחות מג' ימים רק מפני שנראה כמתכוון לדחות את השבת (ועד\"ז הוא בעוד דוגמאות שמביא שם). וראה גם שו\"ת צ\"צ יו\"ד סצ\"ב. שו\"ת אבני נזר או\"ח סשכ\"א. שד\"ח כללים מערכת המ\"ם כלל קלד.\nבצפע\"נ הל' שבועות פ\"ה הט\"ו \"והנה באמת יש נ\"מ בין מ\"ע. שיש מ\"ע שהחיוב חל עליו רק בזמנו אבל קודם לכן אין עליו חיוב כלל שיעשה המצוה בזמנו ויש שאף קודם לזה מחויב לראות שכשיבוא הזמן יקיים המצוה. . וס\"ל לרבינו דגבי סוכה כיון דצריך שלא יהא מן העשוי והוה העשי' ג\"כ מן ההכשר שפיר י\"ל דיש עליו חיוב כל השנה שיהא לו סוכה בזמנה. . משא\"כ במצה דאין עליו חיוב כלל קודם הזמן שיאכל בזמנו\" [ועפ\"ז מבאר שם החילוק בלשון הרמב\"ם שם הי\"ח \"שלא יאכל מצה שנה או שנתיים\" וגבי סוכה כ' \"שלא ישב בצל סוכה לעולם\". ע\"ש]. אבל לכאורה מובן דמ\"ש שאין עליו חיוב כלל קודם הזמן, היינו שאין עליו חיוב עשי', אבל החיוב (דאכילת מצה בליל פסח) אקר­קפתא דגברא הוא חיוב תמידי גם קודם הפסח. ואולי י\"ל כוונתו, דגבי סוכה המצוה עצמה מתחלת קודם זמן חובת הישיבה כיון שבהכרח שתהי' עשי' קודם החג, משא\"כ גבי מצה דיכול לאפותה בליל פסח, לכן עצם המצוה חל רק בזמן חובת אכילתה, אבל היכא שבפועל לא תהי' בידו מצה בליל הפסח אם לא ישתדל לפנ\"ז, לכאורה פשוט שמצות אכילה בליל פסח מחייבתו להשתדל בזה גם קודם הפסח<sup data-n=\"e17\">*</sup>. וראה לקח טוב שם, שגם את\"ל שהחיוב הוא רק בזמן המצוה, נראה פשוט דמי שאין לו אלא לולב אחד לפני סוכות ויודע שגם בסוכות לא יהי' לו רק לולב זה וישרפנו לפני סוכות אזי חשוב מה\"ת מבטל עשה כיון שיודע שעי\"ז לא יוכל לקיים חיוב התורה בעת אשר יבוא עליו. וצ\"ע."],["596","34","הראשונים נחלקו בקטן שהגיע לחינוך אם הוא כמחוייב בדבר מדרבנן, דלדעת רש\"י (ברכות מח, א) והרמב\"ן (הובא בר\"ן ספ\"ב דמגילה) מצוות שעושה הקטן משום חינוך \"לאו מצוה דידי' אלא דאבוה, דאיהו לא מיחייב במצות כל עיקר\", ולדעת התוס' (ברכות שם) והר\"ן (הנ\"ל) מיקרי מחוייב בדבר מדרבנן ויכול להוציא את הגדול שאכל שיעורא דרבנן<sup data-n=\"e18\">*</sup>. ובמ\"א נת' שיש לתמוה על שיטת תוס' ודעימי', דכיון שמה\"ת אין הקטן בר דיעה ולא שייך בי' שום גדר של חיוב, איך יחולו עליו חיובים מדרבנן (וגם אין סיבה שיטילו עליו חכמים חיובים כיון דמצד חינוך די אם כל החובה מוטלת על האב). ונתבאר דגם לשי' תוס' תחילת חלות החיוב היא רק על האב, אלא דכיון דגוף החיוב הוא שהאב ישפיע ויכריח שהבן עצמו יעשה המצוה, הרי למעשה איכא\nחיוב בעשי' זו, ולכן מקרי מחוייב בדבר, דאף שאין החובה בעשי' זו על הבן עצמו כ\"א על אביו, סו\"ס עשיית הקטן היא עשי' של חיוב. — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171234\" data-slug=\"likkutei-sichot\" data-id=\"1300171234\">לקו\"ש חי\"ז ע' 234</a> ואילך."],["e17","*","ולהעיר שמיישב שם (ע\"פ חידושו דיש נפק\"מ בין המ\"ע) דברי התוס' בקידושין (כט, א) דאמאי מילה לא הוי מ\"ע שהזמ\"ג דהא אינו נימול בלילה. ויל\"ע אם מתאים עם המבואר בפנים ה­הערה."],["e18","*","וכ\"מ דעת הרמב\"ם שפסק בהל' ברכות פ\"ה הט\"ו­טז \"בן מברך לאביו\", וכן הוא לשונו בכ\"מ (מצויין לעיל הערה 1) דקטן חייב בציצית, בסוכה וכו' — ראה בארוכה בלקו\"ש הנסמן בפנים ההערה."]]],[1301670129,"כל המציאות של חיוב אינו אלא משנת­גדל, לכן אם מצד טבע הדברים נחוץ זמן של לימוד והכנה עד שיוכל לקיים כל המצות, הרי זמן הכנה זו (מה\"ת) מתחיל רק אחרי שנתגדל, ושוב אא\"ל שעובר על שום מצוה עד שחולף הזמן של ההכנה הדרושה לקיום אותה מצוה.\nואף כי זהו חידוש גדול בהלכה, מ\"מ נראה דמסברא מוכרח הוא, דאיך יחול איזה חיוב באופן שמעצם טבעו א\"א לקיימו, ומכיון שהאפשריות של קיום ה­מצוה כדבעי אינה אלא ע\"י הקדמה של לימוד וחינוך הדורש זמן מסויים, לכן צ\"ל דכל זה נכלל בעצם החיוב. ולכן אין סברא שהתורה תחייב לחנכו בעודו בקט­נותו כדי שיוכל לקיים כל המצוות כשיג­דיל, ואדרבה, התחלת חלות החיוב אינה אלא ברגע שנתגדל, ואם צריך זמן של חינוך והכשרה, הרי זה כלול בעצם חלות החיובים שחלים אחרי שנתגדל<sup data-n=\"597\">35</sup>.\nו. והוכחה לסברא זו יש להביא מגר הבא להתגייר, דקי\"ל דמודיעין אותו (רק) מקצת מצות קלות ומקצת מצות חמורות [וגם זה רק כדי שיפרוש, כדאיתא בגמ']<sup data-n=\"598\">36</sup>. והרמב\"ם<sup data-n=\"599\">37</sup> הוסיף \"ומודיעין אותו עיקרי הדת שהוא ייחוד השם ואיסור עכו\"ם ומאריכין בדבר הזה ומודיעין אותו מקצת מצות. . ואין מאריכין בדבר זה\". והנה פשוט דאם לא נתלמד ונתחנך בעשיית כל המצוות קודם גירותו, לא יוכל לקיימן מיד אחר הגירות<sup data-n=\"600\">38</sup>, וא\"כ למה אין מלמדין אותו כל המצוות ובכל פרטיהם, ואדרבה — \"אין מאריכין בדבר זה\". וע\"כ צ\"ל כנ\"ל בנוגע לקטן, דכיון שכל עיקר החיוב בתומ\"צ חל רק אחרי הגירות, לכן גם החיוב של הכנה והלימוד מתחיל רק אז, ואם ידרוש זמן של הכנה ורגילות עד שיוכל לקיים מצוות מסויימות כהלכתן, הרי כל משך אותו הזמן אינו עובר על מצוות אלו.\nובדוגמת קטן שנתגדל (וגר שנתגייר) אירע לאבותינו בשעת מ\"ת שאז נתחייבו לראשונה בתורה ובמצוות<sup data-n=\"601\">39</sup>, ובודאי נד­רש זמן של לימוד והכנה עד שהיו יכולים לקיים המצוות<sup data-n=\"602\">40</sup>, וכן עד שהיו יכולים להכין חפצי המצוות כמו ציצית ותפלין<sup data-n=\"603\">41</sup>,",[["597","35","ובסגנון אחר, החיוב דהכשר מצוה שייך רק כשישנו חיוב מצוה על הגברא, שאז חל עליו גם החיוב להכין ולהכשיר כל הדרוש לקיום המצוה, משא\"כ בקטן שאינו בר חיובא, לא שייך שמהחיוב שבגדלותו יסתעף חלות חיוב של הכשר והכנה בקטנותו, וגם בזה קיימא התמי' שבש\"ס (פסחים קטז, א) \"חיובי לדרדקי\", שלא שייך שום גדר חיוב ביחס לקטנים."],["598","36","יבמות מז, א­ב. וראה דק\"ס השלם (ירו­שלים, תשמ\"ו). וש\"נ."],["599","37","הל' איסו\"ב פי\"ד ה\"ב."],["600","38","ואין לומר דכיון שאינו מוכרח להתגייר א\"א שיחולו עליו שום דינים, דהרי הותר ללמדו מקצת מצות כו' גם קודם הגירות אף שעכו\"ם שלמד תורה חייב מיתה (סנהדרין נט, א). ולהעיר ממהרש\"א בחדא\"ג שבת לא, א. שו\"ת רעק\"א סי' מא. טו\"א חגיגה יג, א."],["601","39","פיה\"מ להרמב\"ם חולין ספ\"ז. — וכבר העירו (ראה בית האוצר להר\"י ענגיל כלל א אות ז) מל' הרמב\"ם הל' מלכים רפ\"ט \"ונשלמה תורה על ידו\". ולהעיר ממדרש ויק\"ר פ\"א, יו\"ד \"אע\"פ שניתנה תורה סייג לישראל מסיני לא נענשו עלי' עד שנשנית באוה\"מ, משל לדיוטגמא שהיא כתובה ומחותמת ונכנסה למדינה אין בני המדינה נענשים עלי' עד שתתפרש להן בדימוסי' של מדינה כו'\"."],["602","40","דרק במצות מתי מספר נאמר \"כאשר צוך\" (ואתחנן ה, יב ובפרש\"י. שם, טז ובפרש\"י. וראה פרש\"י בשלח טו, כה)."],["603","41","בבית אלקים (להמבי\"ט) שער היסודות פל\"ז כ' דבנ\"י לא הניחו תפלין במדבר. אבל ביל\"ש שלח טו, לד (מובא ברבותינו בעה\"ת שם, לב) מפורש דהניחו. וכן משמע בקידושין לז, ב."]]],[1301670130,"ופשוט דאין לומר שכל אותו הזמן שהיו עסוקים בהכנה היו מבטלים מ\"ע (ונפטרו רק משום דאונס רחמנא פטרי'), אלא ש­כיון שאז הותחל כל עיקר החיוב, לפיכך חל באופן שיוכלו לקיימן, דהיינו בהק­דמת כל ההכנות הדרושות, כולל גם החינוך והרגילות.\nוכן הוא אצל כל קטן שנתגדל (ועד\"ז גר שנתגייר), שכל החיוב שלו בתורה ומצוות מתחיל רק בהגיעו לגדלות, לכן כל הזמן שהוא צריך להתעסק בלימוד והכנה וחינוך עד שיוכל לקיים איזו מצוה כהלכתה או להזהר מאיזו עבירה, אינו מבטל אותה מ\"ע ואינו עובר על אותה מל\"ת, ואדרבה ה\"ה עסוק בקיומם<sup data-n=\"604\">42</sup>, ו­להכי ליכא חובת חינוך בעודו קטן מן התורה<sup data-n=\"605\">43</sup>.\nז. ע\"פ הנ\"ל יש לבאר ענין תמוה בשייכות לאברהם אבינו:\nבפסוק<sup data-n=\"606\">44</sup> \"ואברהם זקן בא בימים\" ארז\"ל<sup data-n=\"607\">45</sup> שאברהם אבינו עבד עבודתו במשך כל ימי חייו, עד שכל ימיו היו \"יומין שלימין\"<sup data-n=\"608\">46</sup>. ולכאורה צריך ביאור: איך אפשר לומר שכל ימיו של אברהם היו בשלימות, והרי חסרו בעבודתו ג' שנותיו הראשונות, כמחז\"ל<sup data-n=\"609\">47</sup> \"בן ג' שנים הכיר אברהם את בוראו שנאמר<sup data-n=\"610\">48</sup> עקב אשר שמע אברהם בקולי, חושבני' מאה ושבעין ותרין שנין\". וכ\"ש וק\"ו לפי ה­דיעות דבן ארבעים שנה הכיר את בוראו, או בן מ\"ח<sup data-n=\"611\">49</sup>, שצריך ביאור איך אפשר לומר עליו \"בא בימים\", שלא הי' חסר אצלו אפילו יום אחד, ועד שאמרו רז\"ל<sup data-n=\"612\">50</sup> (בנוגע לשרה, שלכאורה מזה מובן שכן הוא באברהם) \"כולן שוין לטובה\"?\nוע\"פ הנ\"ל, דענין ההכנה והכשרה ל­מצוה הוי תוצאה ופרט בעצם החיוב, יש לומר עד\"ז גם בנוגע לאברהם אבינו:\nזה שאברהם הכיר את בוראו בהיותו בן ג' שנה בא ע\"י הכנתו והכשרתו בזמן שלפנ\"ז, לחקור ולדרוש את האלקים, וב­לשון הרמב\"ם<sup data-n=\"613\">51</sup> \"התחיל לשוטט בדעתו. .",[["604","42","וי\"ל דע\"ד זה הוא בהציווי דהקמת המשכן — \"ועשו לי מקדש ושכנתי בתוכם\" (תרומה כה, ח) שמזמן הציווי (למחרת יוה\"כ — פרש\"י תשא ל, טז) עד ההקמה והתחלת העבודה בו (ר\"ח ניסן — פקודי מ, יז) עברו כמעט ששה חדשים, ובינתיים היו עסוקים בנדבת המשכן, בעשייתו ובעשיית כליו ע\"י חכמי לב. ופשוט שכל משך אותו הזמן שבין הציווי והקיום, קיימו המ\"ע ד\"ועשו לי מקדש\", דכיון שהכנות אלו היו נחוצות בשביל הקמת המשכן, הרי ההתעסקות בהם היא (התחלת) קיום המצוה<sup data-n=\"e19\">*</sup>."],["605","43","היינו חובת חינוך פרטי בכל מצוה ומצוה, אבל עדיין יתכן דאיכא חובה כללית \"לחנכו ב­קדושה\", כנ\"ל הערה 23. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071163\" data-slug=\"likkutei-sichot\" data-id=\"1300071163\">לקו\"ש ח\"ז ע' 151</a> בהערות."],["606","44","ח\"ש כד, א."],["607","45","ראה זח\"א קכט, א. רכד, א. ועוד."],["608","46","ראה ד\"ה ואברהם זקן תשל\"ח, תשמ\"ו (סה\"מ מלוקט ח\"א ע' רפט. תנא). וש\"נ."],["609","47","נדרים לב, סע\"א."],["610","48","תולדות כו, ה."],["611","49","ב\"ר פ\"ל, ח. וש\"נ. וראה כס\"מ לרמב\"ם שבהערה 51."],["612","50","פרש\"י ר\"פ ח\"ש."],["613","51","הל' ע\"ז פ\"א ה\"ג.\nברמב\"ם שם \"משנגמל איתן זה. . והוא קטן\". ולהעיר, שהרמב\"ם ס\"ל כמ\"ד בן מ' שנה הכיר את בוראו (וברמב\"ם שם \"וכל העם עובדי ע\"ז והוא עובד עמהם\". וראה ב\"ר פל\"ט, ח). אבל מזה מובן להדיעה דבן ג' שנה הכיר את בוראו, שהתחיל \"לשוטט בדעתו\" לפני שהגיע לגיל שלש שנים. וראה הערה הבאה."],["e19","*","וגם לפמ\"ש בצפע\"נ מהדו\"ת (להל' ת\"ת פ\"ג ה\"ג) — \"נ\"מ בין משכן למקדש, דבמשכן הוי המצוה הבנין. . אבל הבנין של מקדש הוא רק כדי שיהי' כו'\" (ע\"ש), הרי לכאורה זהו רק העסק בהבני' שהוא גוף המצוה אבל לא הנדבה וההבאה להמשכן, ומ\"מ גם התעסקות זו נחשבת (כהתחלת) קיום המצוה. ואכ\"מ."]]],[1301670131,"והי' תמה האיך אפשר שיהי' הגלגל הזה נוהג תמיד ולא יהי' לו מנהיג, ומי יסבב אותו, ולבו משוטט ומבין עד שהשיג דרך האמת כו'\". וכיון שבמשך כל ג' השנים<sup data-n=\"614\">52</sup> הי' עסוק בהכשר והכנה להכרת בוראו, שייך לומר שהיו \"יומין שלימין\", גם ב­שנים לפני שהכיר את בוראו, וגם בנוגע לג' שנים הראשונות.\nאלא שאעפ\"כ אין זה בכלל \"שמע אברהם בקולי\" כל זמן שלא הכיר את בוראו בפועל, ומ\"מ אין שום חסרון בכך שעדיין לא הכיר אז את בוראו, כי כך מוכרח בטבע הדברים, שהי' דורש זמן של הכנה והכשרה.\n[ע\"ד הנ\"ל, דזה שבן י\"ג שנה ויום א' אינו יכול להתחיל מיד בקיום המצוה בשלימותה, אין הפירוש בזה שיש חסרון אצלו בקיום המצוה ורק שאינו נענש כי הוא בגדר \"אונס\" דרחמנא פטרי', אלא שמלכתחילה כך מותנה בעצם החיוב, ש­בתחלה עוסק בהכנה והכשרה כו' ואח\"כ מקיים בפועל ובשלימות כו'].\nח. והנה כל הנ\"ל הוא מן התורה, אבל מדברי סופרים ישנו ציווי וחיוב גמור בחינוך קטן, ואדרבה — חמורים וערבים דברי סופרים יותר מדברי תורה<sup data-n=\"615\">53</sup>.\nויש להוסיף, שכללות הענין דקיום המצות בזמן הגלות הוא ענין של \"חינוך\" לגבי קיום המצות אחרי הגאולה, כדאיתא בספרי<sup data-n=\"616\">54</sup> \"אע\"פ שאני מגלה אתכם מן הארץ לחוצה לארץ, היו מצויינין במצוות, שכשאתם חוזרים לא יהיו עליכם חדשים. . הציבי<sup data-n=\"617\">55</sup> לך ציונים\", שכן, \"עיקר כל ה­מצוות ליושבים בארץ ה'\"<sup data-n=\"618\">56</sup>.\nוע\"י קיום המצוות בזמן הגלות, מ­מהרים ומזרזים את הזמן דקיום המצוות בתכלית השלימות, כמצות רצונך<sup data-n=\"619\">57</sup>, ב­גאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות אחש\"פ וש\"פ שמיני תשמ\"ז; ש\"פ וירא תשמ\"ח) </span>",[["614","52","וי\"ל שהתחיל מיד בצאתו לאויר העולם, ע\"ד שמצינו (ב\"ר פל\"ו, ה. ויק\"ר פ\"ה, א) שלפני המבול \"כשהיתה אחת מהם יולדת. . היתה אומרת לבנה (הנולד) צא והבא לי צור לחתוך טבורא\". ומזה מובן גם לאחרי המבול אצל יחידי סגולה כמו האבות, ולכן יתכן שמיד בצאתו לאויר העולם הי' שייך כבר לשוטט בדעתו כו'."],["615","53","סנהדרין פח, ב (במשנה). ע\"ז לה, א ובפרש\"י. ירושלמי ברכות פ\"א ה\"ד."],["616","54","עקב יא, יז — הובא בפרש\"י שם, יח."],["617","55","ירמי' לא, כ."],["618","56","רמב\"ן אחרי יח, כה."],["619","57","תו\"ח ר\"פ ויחי. המשך וככה תרל\"ז פי\"ז ואילך. ועוד."]]],[1301670132,"<h3>שיחה ב</h3>\nא. וה' המטיר על סדום ועל עמורה גפרית ואש גו' ויהפוך את הערים האל ואת כל הככר ואת כל יושבי הערים גו'<sup data-n=\"620\">1</sup>.\nובפרש\"י עה\"פ<sup data-n=\"621\">2</sup>, דמ\"ש \"ויהפוך את הערים האל\" קאי לא רק על סדום וע­מורה שנזכרו בפסוק שלפניו, אלא על כל ארבע הערים שבככר<sup data-n=\"622\">3</sup>, וכמפורש בפ' נצבים<sup data-n=\"623\">4</sup> \"כמהפכת סדום ועמורה אדמה וצבוים\" [ואף שלעיל<sup data-n=\"624\">5</sup> פרש\"י שחמשה כרכים היו בככר (והם חמשת המלכים שנזכרו בפ' לך<sup data-n=\"625\">6</sup>, סדום ועמורה אדמה צבוים וצוער), רק ארבע מהם נהפכו, כי המלאך הסכים לבקשת לוט \"לבלתי הפכי את העיר (צוער)\"<sup data-n=\"626\">7</sup>, כמבו­אר במפרשים<sup data-n=\"627\">8</sup>].\nומבאר בצפנת פענח (להרגצובי) עה\"ת<sup data-n=\"628\">9</sup> טעם החילוק בין עונשן של סדום ועמורה לאדמה וצבוים, שהראשונות נשרפו באש מן השמים, ואילו אדמה וצבוים רק נהפכו — כי סדום ועמורה נענשו מדין עיר הנדחת<sup data-n=\"629\">10</sup> (כמובן מירו­שלמי<sup data-n=\"630\">11</sup> ותוספתא<sup data-n=\"631\">12</sup>), ולכך נשרפו (כדין עיר הנדחת<sup data-n=\"632\">13</sup>), משא\"כ אדמה וצבוים לא היו יכולות להיות נידונות מדין עיר הנדחת, כפסק המשנה<sup data-n=\"633\">14</sup> שאין עושין ג' עיירות עיר הנדחת, ולכן רק נהפכו.\nוהנה חילוק זה בין עונשן של סדום ועמורה לאדמה וצבוים מוכרח גם ב­פשוטם של כתובים, דעונש שריפה (גפ­רית ואש מן השמים) נזכר רק בסדום ועמורה, ובהפיכת הערים נאמר \"ויהפוך את הערים האל\" (וקאי על ד' הערים, וכנ\"ל מפרש\"י)<sup data-n=\"634\">15</sup> — וא\"כ יש לעיין, מהו הטעם ע\"פ פשוטו של מקרא לחילוק זה?\nומובן, שביאור הנ\"ל של הצפע\"נ אינו ענין לפשוטו של מקרא, כי ע\"ד הפשט — (א) עיקר העונש של סדום ועמורה לא הי' מחמת חטא עבודה זרה<sup data-n=\"635\">16</sup>, אלא (ב­לשון הכתוב<sup data-n=\"636\">17</sup>) לפי ש\"יד עני ואביון לא",[["620","1","פרשתנו יט, כד­כה."],["621","2","שם, כה."],["622","3","ומקורו בב\"ר (פנ\"א, ד), אלא דשם \"חמשת כרכים הללו\". וראה מפרשי ב\"ר שם. מפרשי רש\"י שצויינו בהערה 8. ועוד."],["623","4","כט, כב."],["624","5","פרשתנו יח, יז. שם, כד. וראה רש\"י שם, כט."],["625","6","יד, ב. שם, ח. וראה נח י, יט (הובא בפרש\"י פרשתנו שם, יז. אלא שבנח שם לא נזכר בלע (צוער), רק \"לשע\". ואכ\"מ)."],["626","7","פרשתנו יט, כא."],["627","8","ראה רא\"ם, ס' זכרון, נחלת יעקב, דברי דוד (להט\"ז), דבק טוב ועוד."],["628","9","פרשתנו כאן (ולעיל יח, כד). נצבים שם."],["629","10","ראה גם אלשיך פרשתנו כאן."],["630","11","סנהדרין פ\"י ה\"ח."],["631","12","סנהדרין פי\"ד, א."],["632","13","פ' ראה יג, יז."],["633","14","ריש סנהדרין. ובגמ' שם טז, ב."],["634","15","דעכצ\"ל (בפשש\"מ) שגם \"אדמה וצבוים\" בכלל (ולא רק סדום ועמורה שנזכרו בפסוק של­פנ\"ז), שהרי מפורש בנצבים (כנ\"ל) \"כמהפכת סדום ועמורה אדמה וצבוים\". אלא שרש\"י לא הביאו כאן, ומשמע שמוכרח גם מלשון הכתוב כאן. וראה בחיי כאן. באר בשדה על פרש\"י. ואכ\"מ."],["635","16","אף שגם חטא זה הי' אצלם, כפרש\"י פר­שתנו (יט, כד ד\"ה המטיר על סדום). וראה סנהדרין קט, א. רד\"ק לך יג, יג (ובפרש\"י לך שם \"יודעים רבונם ומתכוונים למרוד בו\")."],["636","17","יחזקאל טז, מט. הובא בראב\"ע לך שם. רמב\"ן פרשתנו יט, ה (ע\"ש). — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051168\" data-slug=\"likkutei-sichot\" data-id=\"1300051168\">לקו\"ש ח\"ה ע' 156</a> הערה 45 ובשוה\"ג שם. וש\"נ."]]],[1301670133,"החזיקה\" (וכדלקמן סעיף ג), (ב) כל דין עיר הנדחת אינו שייך בב\"נ וקודם מ\"ת, (ג) בפשוטו של מקרא לא נזכר הדין דאין עושין עיר הנדחת שלש עיירות, (ד) ואם מצד הסברא (כמ\"ד בגמ'<sup data-n=\"637\">18</sup> שהוא \"משום קרחה\"<sup data-n=\"638\">19</sup>) — הרי אין חילוק בזה בין שריפה או הפיכה, דאותה הסברא שאין לשרוף (ולהחריב) ג' עיירות, מ­חייבת ג\"כ שלא להחריבן באופן של הפיכה.\nב. ויובן זה בהקדם דיוק לשון ה­כתוב<sup data-n=\"639\">20</sup> (בתחילת הענין), \"ויאמר ה' זעקת סדום ועמורה כי רבה וחטאתם כי כבדה מאד\", דיש לעיין אמאי נזכרו (בפירוש) בכתוב רק סדום ועמורה ולא שאר ה­ערים שבככר (ורק בפרש\"י<sup data-n=\"624\">5</sup> הובא שהיו חמשה כרכים).\n[ברד\"ק<sup data-n=\"639\">20</sup> תי' \"כי הם ראשי הממל­כות\" (וג' הערים האחרות היו טפלות להן). אבל לכאורה אינו ביאור מספיק, כי א\"כ הול\"ל רק סדום, שהרי (בל' ה­רד\"ק שם) \"סדום היתה אם לכולם\", וכהובא בפרש\"י<sup data-n=\"642\">21</sup> (בטעם שאמר ה'<sup data-n=\"642\">21</sup> \"אם אמצא בסדום (דוקא) חמשים צדי­קים גו' ונשאתי לכל המקום בעבורם\") \"לפי שסדום היתה מטרפולין וחשובה מכולם תלה בה הכתוב\", וכן מצינו ש­המלאך<sup data-n=\"644\">22</sup> הלך רק לסדום — וא\"כ גם בנדו\"ד, אם כוונת הכתוב רק להזכיר העיקר, הו\"ל להסתפק גם כאן בהזכרת סדום<sup data-n=\"645\">23</sup> (וע\"ד לשון רש\"י כמ\"פ<sup data-n=\"646\">24</sup> גבי שליחות המלאכים \"להפוך (להשחית) את סדום\"), ולמה הזכיר גם עמורה<sup data-n=\"647\">25</sup>?].\nומשמע מזה, שעיקר החוטאים היו אנשי סדום ועמורה<sup data-n=\"648\">26</sup>.\nוזהו גם הטעם שרק בסדום ועמורה המטיר ה' גפרית ואש, וכפרש\"י עה\"פ<sup data-n=\"649\">27</sup> ד\"כשבא ליסר הבריות מביא עליהם אש מן השמים\", היינו שאנשי סדום ועמורה שגדל חטאם מתו ונאבדו מתוך יסורים של \"אש מן השמים\", משא\"כ אנשי שאר הערים רק נאבדו ע\"י הפיכתן.\nאבל אין זה ביאור מספיק, כי מ­פרש\"י גבי בקשת לוט \"הנה<sup data-n=\"650\">28</sup> נא העיר הזאת קרובה לנוס שמה גו'\" — \"קרובה ישיבתה נתיישבה מקרוב לפיכך לא נת­מלאה סאתה עדיין\", \"הלא מצער היא — והלא עונותי' מועטין\"<sup data-n=\"651\">29</sup>, מוכח, ששני הערים האחרות (אדמה וצבוים) נתמלאה",[["637","18","סנהדרין שם."],["638","19","ובר\"ח סנהדרין שם משמע, שגם זה הוא מטעם \"שמא ישמעו נכרים ויחריבו את א\"י\" (סנ­הדרין שם, בטעם שאין עושין עיר הנדחת סמוכה לספר)."],["639","20","יח, כ."],["624","5","פרשתנו יח, יז. שם, כד. וראה רש\"י שם, כט."],["639","20","יח, כ."],["642","21","יח, כו."],["642","21","יח, כו."],["644","22","היינו, לא רק המלאך שהלך להציל את לוט שהי' גר בסדום, אלא גם המלאך המשחית כו' (ראה רש\"י יח, ב) הלך לסדום דוקא. וראה גם לעיל (יח, טז) \"וישקיפו על פני סדום\" (דוקא)."],["645","23","אבל מ\"ש לעיל (לך שם) \"ואנשי סדום (דוקא) רעים וחטאים גו'\" אינו מטעם חשיבות, אלא לפי שרק זה נוגע שם, ד\"אעפ\"כ לא נמנע לוט מלשכון עמהם\" (רש\"י שם)."],["646","24","פרשתנו יח, ב. שם, לג. יט, טז."],["647","25","ומ\"ש (לך יג, י) \"לפני שחת ה' את סדום ואת עמורה\", אינו מפני חשיבותם, אלא לפי שעיקר ההשחתה היתה בהם, שנשרפו (כדלקמן הערה 48).\nועד\"ז מ\"ש שם (יד, יא) \"ויקחו את כל רכוש סדום ועמורה\", לכאורה י\"ל כי כן הי' בפועל, שלקחו רק רכושם ולא דשאר העיירות (ואולי מפני שהיו עיירות קטנות כו'). ואכ\"מ."],["648","26","להעיר מהאזינו לב, לב ובפרש\"י (\"מעשה סדום ועמורה\"). ישעי' א, י ובפרש\"י שם. ועוד."],["649","27","יט, כה ד\"ה מן השמים."],["650","28","יט, כ."],["651","29","וראה משכיל לדוד לך (יד, ב), שמטעם זה לא נזכר בכתוב שם שם מלך בלע (צוער), כי שמות מלכי שאר ד' הערים רומזים על רשעתם, כפרש\"י שם (הובא לקמן ריש ס\"ג), משא\"כ צוער שעונותי' מועטין."]]],[1301670134,"סאתן. וא\"כ אמאי לא נענשו גם הם ע\"י \"אש מן השמים\"?\nג. ויש לומר הביאור בזה, ע\"פ פרש\"י לעיל בפ' לך<sup data-n=\"652\">30</sup>, בפירוש שמות המלכים, \"ברע מלך סדום. . ברשע מלך עמורה שנאב מלך אדמה ושמאבר מלך צבוים\", וז\"ל<sup data-n=\"653\">31</sup>: \"ברע — רע לשמים ורע לבריות; ברשע — שנתעלה ב­רשעו<sup data-n=\"654\">32</sup>; שנאב — שונא אביו שבשמים; שמאבר — שם אבר לעוף ולקפוץ ו­למרוד בהקב\"ה\".\nהרי בשני האחרונים מודגשת בשמם רק מרידתם נגד הקב\"ה (בין אדם ל­מקום), ואילו אצל \"ברע\" הי' רע כפול — רע לשמים ורע לבריות. ובפשטות זהו הפירוש ד\"ברע\" — \"ב' (סוגי) רע\". ועפ\"ז נ\"ל, דמ\"ש רש\"י אח\"כ בפירוש \"ברשע\" — \"שנתעלה ברשעו\", היינו הוספה על \"ברע\", היינו שגם אצל \"ברשע\" היו ב' סוגי רשע (\"ב' רשע\"), לשמים ולבריות, ונקרא \"ברשע\" (לא \"ברע\") לפי \"שנת­עלה ברשעו\".\nויש לומר, שזהו גם החילוק בין רשעת אנשי ערים אלה בשנים הבאות<sup data-n=\"655\">33</sup> (כשנענשו על חטאם), דרשעת אדמה וצבוים היתה בעיקר בחטאים שבין אדם למקום, רע לשמים, משא\"כ בסדום ו­עמורה הי' רע כפול, הן לשמים (שמרדו בה'<sup data-n=\"656\">34</sup> והיו עובדי ע\"ז<sup data-n=\"657\">35</sup>) והן לבריות, ואדרבה, עיקר הרשעה של סדום ועמו­רה אשר בגללה נענשו בעונש חמור כזה הי' (כמפורש בקרא<sup data-n=\"636\">17</sup>) \"יד עני ואביון לא החזיקה\", וכמובא גם בפרש\"י פרשתנו<sup data-n=\"659\">36</sup> \"הכצעקתה, צעקת ריבה אחת שהרגוה מיתה משונה על שנתנה מזון לעני\" (וכמובן ג\"כ מהנהגת אנשי סדום כשבאו המלאכים אל לוט<sup data-n=\"660\">37</sup>).\nד. וע\"פ זה מובן גם החילוק בין עונשם של הערים, עד שאין רש\"י צריך לפרשו, כי מובן הוא מפרש\"י לעיל:\nבס\"פ נח<sup data-n=\"661\">38</sup> מבאר רש\"י ההבדל בין עונשם של דור המבול ושל דור הפלגה, וז\"ל: \"וכי איזו קשה של דור המבול או של דור הפלגה, אלו לא פשטו יד בעיקר ואלו פשטו יד בעיקר להלחם בו, ואלו נשטפו ואלו לא נאבדו מן העולם, אלא שדור המבול היו גזלנים והיתה מריבה ביניהם לכך נאבדו, ואלו היו נוהגים אהבה וריעות ביניהם כו' למדת ששנאוי המחלוקת וגדול השלום\".",[["652","30","שם."],["653","31","ומקורו בתנחומא שם (ח)<sup data-n=\"e20\">*</sup>. — ובב\"ר (פמ\"ב, ה) נדרש באו\"א. ואכ\"מ."],["654","32","בדפוס ראשון ורוב כת\"י רש\"י שתח\"י ליתא ד\"ה ברע וד\"ה ברשע. אבל ישנם בדפוסי רש\"י הנפוצים (ובדפוס שני (וא' מכת\"י רש\"י שתח\"י): ברע שהי' רע. ברשע שהי' רשע)."],["655","33","לשיטת רש\"י בפירושו עה\"ת בפ' בא (יב, מ) — שברית בין הבתרים היתה שלשים שנה לפני לידת יצחק — מלחמת ד' מלכים עם החמשה בפ' לך (שקדמה לברית בין הבתרים, כסדרם בקרא. וכמפורש ברש\"י לך טו, א)<sup data-n=\"e21\">*</sup>, היתה בערך כט שנה לפני הפיכת סדום ועמורה (שקדמה ללידת יצחק בשנה אחת — ראה פרשתנו יח, י וברש\"י שם)."],["656","34","רש\"י לך לך יג, יג. וראה רד\"ק שם."],["657","35","נסמן לעיל הערה 16."],["636","17","יחזקאל טז, מט. הובא בראב\"ע לך שם. רמב\"ן פרשתנו יט, ה (ע\"ש). — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051168\" data-slug=\"likkutei-sichot\" data-id=\"1300051168\">לקו\"ש ח\"ה ע' 156</a> הערה 45 ובשוה\"ג שם. וש\"נ."],["659","36","יח, כא. — אלא שרש\"י הביאו רק כפירוש שני (ועוד מקדים \"ורבותינו דרשו\"), דאינו פשוטו ממש, כי כיצד יתכן לומר שהריגת \"ריבה אחת\" היתה ע\"י תושבי ב' ערים (סדום ועמורה)."],["660","37","פרשתנו יט, ד ואילך. וראה רש\"י שם, ב ד\"ה ולינו."],["661","38","יא, ט."],["e20","*","אלא ש\"ברשע\" מפרש \"שנעשה רשע\", ואילו בפרש\"י \"שנתעלה ברשעו\"."],["e21","*","כ\"כ ברבותינו בעה\"ת לך יב, ד (בשיטת רש\"י). אבל ראה תוד\"ה לא ברכות ז, ב. רש\"י פרשתנו יט, כ. ואכ\"מ."]]],[1301670135,"הרי מפורש, שעונש דור המבול, ש­נשטפו ונאבדו, הי' בעיקר מפני ש\"היו גזלנים והיתה מריבה ביניהם\". וכן מובן מפרש\"י בריש פ' נח, עה\"פ<sup data-n=\"662\">39</sup> \"כי מלאה הארץ חמס\" — \"לא נחתם גזר דינם אלא על הגזל\", היינו, דאע\"פ שחטאו גם בעריות וע\"א, כפרש\"י שם גופא<sup data-n=\"663\">40</sup>, \"ותשחת — לשון ערוה וע\"א\", ועד שזו היתה סיבת העונש באופן של \"קץ כל בשר\"<sup data-n=\"662\">39</sup>, כפרש\"י שם \"כל מקום שאתה מוצא זנות וע\"א אנדרלמוסיא באה ל­עולם והורגת טובים ורעים\", מ\"מ, \"לא נחתם גזר דינם אלא על הגזל\".\nומבואר במפרשים<sup data-n=\"665\">41</sup> בטעם הדבר, כי גזל ומריבה הם היפך יישובו של עולם ומחזירים את העולם לתהו. ונ\"ל בכוונת הדברים, דאין המבול רק עונש חמור על חטאים חמורים, אלא ענינו כעין חרטה על כללות בריאת האדם והעולם<sup data-n=\"666\">42</sup>, שהנ­הגת הנבראים הביאה לידי כך שהקב\"ה התחרט כביכול על עצם הבריאה, וב­מילא החריב עולמו אשר ברא, באופן של \"וימח<sup data-n=\"667\">43</sup> את כל היקום גו'\", איבוד מוחלט<sup data-n=\"668\">44</sup>. וזהו שהסיבה העיקרית לגזירה זו היא עון גזל ומריבה, כי רק הנהגה באופן שמחזיר את העולם לתהו, היפך יישוב העולם, היא המנגדת לעצם ה­בריאה<sup data-n=\"669\">45</sup>.\nועפ\"ז יש לבאר כפל הענין בכתוב<sup data-n=\"662\">39</sup> \"קץ כל בשר בא לפני כי מלאה הארץ חמס גו' והנני משחיתם את הארץ\": \"קץ כל בשר\" ענינו עונש החוטאים על גודל חטאם, ולפי שמדובר בעון זנות וע\"א הרי העונש באופן של \"קץ כל בשר\", \"אנדרלמוסיא כו' והורגת טובים ורעים\" (ועונש כזה אינו מוגבל לזמן המבול, וכדיוק לשון רש\"י \"כל מקום שאתה מוצא זנות וע\"א כו'\"); משא\"כ על ידי ש\"מלאה הארץ חמס (עון גזל). . הנני משחיתם את הארץ\", וכפרש\"י \"עם ה­ארץ, שאף ג' טפחים של עומק המחרי­שה נמוחו ונטשטשו\"<sup data-n=\"671\">46</sup>, שעצם הארץ נשחתה, שדבר זה הוא לפי שהמבול לא הי' רק עונש על החוטאים אלא ענין של איבוד עצם הארץ (היפך בריאת העולם).\nוע\"פ כל זה מובן גם לעניננו — עונש סדום ועמורה כו':\nהחילוק בין המטרת \"גפרית ואש. . מן השמים\" להפיכת הערים הוא, דב­הפיכת הערים נהרגו יושבי הערים וגם נחרב כל צמח האדמה<sup data-n=\"672\">47</sup>, אבל אין בזה השחתת האדמה עצמה, וזוהי ההוספה בזה ש\"וה' המטיר גו' גפרית ואש\", ד­נוסף על יסורי הבריות, הרי עוד ועיקר, שבזה נשרפו הערים ונשחתו כליל<sup data-n=\"673\">48</sup>",[["662","39","ו, יג."],["663","40","שם, יא."],["662","39","ו, יג."],["665","41","ראה גו\"א. אמרי שפר על פרש\"י בשם תולדות יצחק. דברי דוד (להט\"ז). צידה לדרך. דבק טוב בהגהה. הואיל משה (באר היטב). ועוד."],["666","42","ראה בכ\"ז בארוכה לעיל ע' 35 ואילך."],["667","43","נח ז, כג."],["668","44","וי\"ל שזהו דיוק ל' רש\"י הנ\"ל \"ואלו נשטפו\" (ולא \"נאבדו\", כלשון רש\"י עצמו שם אח\"כ, וגם בנוגע לדור המבול) — כי \"נשטפו\" מורה על העדר וביטול המציאות לגמרי, משא\"כ \"נאבדו\" שאינו מכריח שנתבטלה מציאותם (דיתכן שמצי­אותם קיימת אלא שאין יודעים היכן נמצאות)."],["669","45","ראה תולדות יצחק (שהובא באמרי שפר שם) \"היפך הכוונה הראשונה בבריאת העולם\"."],["662","39","ו, יג."],["671","46","בפרש\"י הוא פירוש שני, אבל י\"ל שה­חילוק בין שני הפירושים הוא רק בפירש התיבות \"את הארץ\", אבל לכו\"ע חלק מהארץ נמחה במי המבול. ולהעיר מרש\"י נח ח, יג­יד."],["672","47","כלשון הכתוב כאן (יט, כה)."],["673","48","ועפ\"ז יובן ל' הכתוב לעיל (לך לך יג, י) \"שחת ה' את סדום ואת עמורה\", כי עיקר ענין ה­השחתה הוא בשריפת סדום ועמורה ולא (כ\"כ) בהפיכת הערים. וראה ל' הכתוב יט, כח­כט. ישעי' א, ט (וראה שם, ז). שם יג, ט. ירמי' מט, יח; נ, מ (\"ושכני'\"). עמוס ד, יא (\"מוצל משרפה\"). ואכ\"מ."]]],[1301670136,"(ע\"ד<sup data-n=\"674\">49</sup> \"הנני משחיתם את הארץ\" ע\"י ה­מבול<sup data-n=\"675\">*49</sup>).\nולכן הוטל עונש זה רק על סדום ועמורה, שעיקר חטאם הי' בין אדם לחבירו (ע\"ד עונש דור המבול לפי ש\"היו גזלנים והיתה מריבה ביניהם\"), משא\"כ אדמה וצבוים שעיקר חטאם הי' בין אדם למקום נענשו רק בהפיכה.\nה. ובפנימיות הענינים יש לומר:\nמבואר בחסידות<sup data-n=\"676\">50</sup> בטעם עונש סדום, שנאבד ונחרב לגמרי, כי הנהגת סדום, היפך השלום ואחדות, היא ע\"ד עולם התהו, שבתהו \"כל א' בפני עצמו, ענפין מתפרדין\", וזהו טעם המ\"ד<sup data-n=\"677\">51</sup> ד\"האומר שלי שלי ושלך שלך. . זו מדת סדום\", כי עצם ענין הפירוד וההתחלקות זמ\"ז ה\"ז כענין עולם התהו, ענפין מתפרדין. וזהו\"ע איבוד סדום ועמורה כו', שהוא ע\"ד ה\"שבירה\" דעולם התוהו (כמחז\"ל<sup data-n=\"678\">52</sup> \"שהי' בורא עולמות ומחריבן\"), שמטרתו הוא \"סותר ע\"מ לבנות\", בשביל בריאת עולם התיקון שענינו עולם של התכללות ואחדות כו'.\nאמנם, תכלית הכוונה היא, שב\"כלים\" דתיקון יומשכו ויתגלו גם ה\"אורות דתהו\" שהם למעלה ממדידה והגבלה, אלא כיון שיהי' ב\"כלים דתיקון\", אין בזה ענין של פירוד ושבירה, אלא אד­רבה, תכלית האחדות כו'.\nועפ\"ז יש לפרש מ\"ש ביחזקאל<sup data-n=\"679\">53</sup> ש­לעתיד ישובו ערי סדום, \"ושבתי את שביתהן את שבית סדום ובנותי'\", דיש לומר, שהתוכן הפנימי דשיבת ובנין ערים אלו הוא, שבזמן הגאולה יתגלו למטה אורות דתהו, אלא שאז יומשכו אורות אלה בכלים דתיקון דוקא (בנין, היפך השבירה).\nוזהו גם מה שאמרו במדרש<sup data-n=\"680\">54</sup> \"מ­צאתי<sup data-n=\"681\">55</sup> דוד עבדי, היכן מצאתי אותו בסדום\", דלכאורה תמוה, כיצד יתכן שדוד מלכא משיחא יהי' שייך לסדום דוקא? אלא זהו מצד המעלה הפנימית שבה, גילוי אורות דתהו, ולכן \"מצאתי אותו בסדום\" דוקא, כי זהו ענינו של דוד מלכא משיחא, שעל ידו יהי' גילוי אורות דתהו (שלמעלה ממדידה והג­בלה), אלא שיומשכו בכלים דתיקון דוקא.\nועפ\"ז אולי יש לומר, שזהו התוכן הפנימי למעליותא שבשני סוגי הערים דסדום ובנותי' שישובו לעתיד לבוא: סדום ועמורה (שנשרפו) רומזות על אורות דתהו שלמעלה ממדידה והגבלה, ושתי הערים אדמה וצבוים (שהם ע\"ד דור הפלגה<sup data-n=\"682\">56</sup> כנ\"ל, שלא הי' שם (כ\"כ)",[["674","49","ולא ממש (ראה לעיל שם)<sup data-n=\"e22\">*</sup>."],["675","*49","ראה תוספתא תענית פ\"ב, יא. יל\"ש נח רמז סא. וראה ב\"ר פרשתנו פמ\"ט, ט<sup data-n=\"e23\">*</sup>."],["676","50","אוה\"ת פרשתנו צט, ב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670591\" data-slug=\"torat-chaim\" data-id=\"2300670591\">תו\"ח נח (עז, א</a>). פרשתנו (קח, ג). ובכ\"מ."],["677","51","אבות פ\"ה מ\"י."],["678","52","ב\"ר פ\"ג, ז."],["679","53","טז, נג. וראה של\"ה חלק תושב\"כ פ' לך (רעט, א), וע\"ש שזהו הטעם שאברהם השתדל כ\"כ בהצלת סדום."],["680","54","ב\"ר פרשתנו (פ\"נ, י. הובא בשל\"ה שם). וראה יבמות עז, א. מאמרי אדה\"ז תקס\"ו ריש ע' תג."],["681","55","תהלים פט, כא."],["682","56","ראה דרושי הפלגה בתו\"א, תו\"ח ואוה\"ת (כרך ו) פ' נח — ע\"ד השייכות דדור ההפלגה לההתכללות דעולם התיקון (נזכר באוה\"ת פרשתנו שם (ק, א))."],["e22","*","וראה \"רשימות\" חוברת ג' (קה\"ת תשנ\"ה) ע' 39. המו\"ל."],["e23","*","וראה \"רשימות\" שם (ע' 9­38). המו\"ל."]]],[1301670137,"ענין הגזל ומריבה) הוא ע\"ד ענין ההתכללות דכלים דתיקון<sup data-n=\"683\">57</sup> — ושיבת כל ד' הערים יחד מורה על חיבור והתאחדות אורות דתהו וכלים דתיקון.\n<span data-k=\"q\">(משיחות ש\"פ וירא וח\"ש תשמ\"ג, ש\"פ נח תשמ\"ב) </span>",[["683","57","אלא שבאוה\"ת פרשתנו שם, שעונש סדום הוא \"כמו שבה\"כ ויהפוך את הערים וכו'\" — שזה הי' גם בשני ערים הנ\"ל."]]],[1301670138,"<h3>שיחה ג</h3>\nא. \"ויאמר אל תשלח ידך אל הנער ואל תעש לו מאומה כי עתה ידעתי כי ירא אלקים אתה גו'\"<sup data-n=\"684\">1</sup>, ובפרש\"י על \"כי עתה ידעתי\" (ד\"ה הא') מביא מאמרו של ר' אבא<sup data-n=\"685\">2</sup> \"א\"ל אברהם אפרש לפניך את שיחתי אתמול אמרת לי<sup data-n=\"686\">3</sup> כי ביצחק יקרא לך זרע וחזרת ואמרת<sup data-n=\"687\">4</sup> קח נא את בנך עכשיו אתה אומר לי אל תשלח ידך אל הנער א\"ל הקב\"ה לא אחלל בריתי ומוצא שפתי לא אשנה<sup data-n=\"688\">5</sup> כשאמרתי לך קח מוצא שפתי לא אשנה לא אמרתי לך שחטהו אלא העלהו אסקתי' אחתי' [ה­עלית אותו — הורידו]\".\nוכבר תמהו מפרשים<sup data-n=\"689\">6</sup>:\nא) מנ\"ל לרש\"י כ\"ז בפשוטו של מקרא<sup data-n=\"690\">7</sup>? איפה מרומז ב\"כי עתה ידעתי\" שאברהם תמה \"אתמול אמרת לי כו' וח­זרת ואמרת כו'\", והקב\"ה השיבו ד\"מוצא שפתי לא אשנה, לא אמרתי לך שחטהו כו'\".\nב) למה תמה אברהם רק כאשר נצ­טווה \"אל תשלח ידך גו'\", ולא לפנ\"ז — תיכף כשנצטווה \"קח נא את בנך\" (שזהו בסתירה להבטחת הקב\"ה \"כי ביצחק יקרא לך זרע\")?\nגם יש לדייק:\nמקורו של מאמר זה הוא בבראשית רבה<sup data-n=\"691\">8</sup>, אבל שם לפנינו, נוסף לזה שהובא בשם ר' אחא<sup data-n=\"692\">9</sup> (ולא ר' אבא), עם עוד שינויי לשון<sup data-n=\"693\">10</sup> — יש גם שינוי עיקרי בתוכן:\nבמדרש איתא \"א\"ר אחא התחיל אברהם תמי', אין הדברים הללו אלא דברים של תימה, אתמול אמרת כו'\", היינו שאברהם תמה על הנהגת הקב\"ה. וגם לפי הגירסא<sup data-n=\"694\">11</sup> (שקרובה ללשון רש\"י) \"אף את לפניך שיחות (בתמי')\", הרי הכוונה בזה היא, כמ\"ש בפירוש המד\"ר המיוחס לרש\"י (ועד\"ז הוא בילקוט<sup data-n=\"695\">12</sup>) \"אמר אברהם כביכול יש לפניך שיחות כבני אדם שמחליפין דיבורן\";\nמשא\"כ בפרש\"י הגירסא \"א\"ל אברהם אפרש לפניך את שיחתי\" — שלשון זו אינה ביטוי של תמי' כלפי מעלה, ואינה מוסבת על \"שיחות\" (דברי) הקב\"ה, אלא על דברי אברהם (\"שיחתי\").\nויש להבין (א) למה בחר רש\"י בגירסא זו דוקא. (ב) מהו תוכן הקדמה",[["684","1","פרשתנו כב, יב."],["685","2","ראה לקמן בפנים בהמשך הסעיף ובהנסמן שם."],["686","3","פרשתנו כא, יב. וראה לקמן הערה 17 ב­שוה\"ג הב'."],["687","4","כב, ב."],["688","5","תהלים פט, לה."],["689","6","ראה יפה תואר (השלם) לב\"ר פנ\"ו, ח (יב). נזר הקדש (השלם) לפנ\"ז (שם, ב). וכן במפרשי רש\"י — דברי דוד כאן. ס' חלקי אבנים על פרש\"י (פירדא, תג\"ן. וכמ\"פ לאח\"ז). באר יצחק. באר בשדה. מלאכת הקודש. ועוד."],["690","7","ולהעיר שבדפוס א' וב' דפרש\"י, וכן ברוב כת\"י רש\"י שתח\"י — ד\"ה זה ליתא. וראה הערה 18."],["691","8","שם."],["692","9","וכ\"ה בתנחומא באבער פרשתנו מ. וראה ב\"ר הוצאת תיאודור­אלבק שם בחילופי נוסחאות."],["693","10","וראה בפרטיות בב\"ר הוצאה הנ\"ל ובחי­לופי נוסחאות שם."],["694","11","כ\"ה בב\"ר הוצאה הנ\"ל. וראה חילופי נוסחאות שם."],["695","12","שמעוני — פרשתנו רמז קא."]]],[1301670139,"זו, שלכאורה היא שפת יתר, ולמה לא התחיל תיכף בגוף הענין \"אתמול אמרת כו'\"? (ג) איזו \"שיחה\" שלו בא אברהם לפרש<sup data-n=\"696\">13</sup>?\nב. ונ\"ל שאכן זוהי כוונת רש\"י בהע­תקת לשון זו (\"אפרש לפניך את שיחתי\"), להבהיר, שכוונת אברהם אבינו בדבריו אלה לא היתה לתמוה על דברי הקב\"ה\n[כי ע\"פ פשוטו של מקרא אין לומר שאברהם אבינו הרהר אחרי מדותיו של הקב\"ה. וכמפורש בפרש\"י לעיל<sup data-n=\"697\">14</sup> ש­הקב\"ה ניסה את אברהם \"אם יהרהר אחר דבריו של הקב\"ה שאמר לו ללכת אל ארץ כנען ועכשיו משיאו לצאת ממנה\" — דאף שהם דברים סותרים, מ\"מ לא הרהר (אפילו) \"אחר דבריו של הקב\"ה\". וכן מצינו בפרש\"י להלן (ס\"פ שמות<sup data-n=\"698\">15</sup>) בנוגע לנדו\"ד, שזו היתה מעלת אברהם על משה רבינו, שא\"ל הקב\"ה למשה \"הרהרת על מדותי, לא כאברהם שאמרתי לו כי ביצחק יקרא לך זרע<sup data-n=\"686\">3</sup> ואח\"כ אמרתי לו העלהו לעולה<sup data-n=\"687\">4</sup> ולא הרהר אחר מדותי\" (והיינו, שלא רק שלא היתה אצל אברהם חלישות בקיום הציווי בפועל, אלא שאף במחשבתו לא עלה שום הרהור<sup data-n=\"701\">16</sup> \"אחר מדותי\")<sup data-n=\"702\">17</sup>. וא\"כ ודאי, דגם בסוף הענין, כאשר גדלה הסתירה ש\"עכשיו אתה אומר לי אל תשלח ידך\" — לא הרהר אברהם אחר מדותיו של הקב\"ה (ומה גם להביע תמיהתו בדיבור)],\nאלא לפרש לפני הקב\"ה את כוונתו (של אברהם) בדבריו הקודמים לזה<sup data-n=\"703\">18</sup>.",[["696","13","בדברי דוד פי' \"כלומר עד הנה הי' לי קושיא בלבי אבל עכשיו אני מקשה בפירוש\". אבל ראה לקמן סעיף ב."],["697","14","לך יב, י."],["698","15","ו, א. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161047\" data-slug=\"likkutei-sichot\" data-id=\"1300161047\">לקו\"ש חט\"ז (ע' 47</a> ואילך) טעם השינוי בפרש\"י וארא (ו, ט)."],["686","3","פרשתנו כא, יב. וראה לקמן הערה 17 ב­שוה\"ג הב'."],["687","4","כב, ב."],["701","16","וגם לה\"מדרש אגדה\" בפרש\"י לעיל (כב, ה) שאברהם אמר \"אראה היכן הוא מה שאמר לי המקום (לך טו, ה) כה יהי' זרעך\" — אין זה ענין של הרהור אחר מדותיו ח\"ו, אלא אדרבה, מצד הוודאות שהבטחה זו תתקיים (ורוצה לראות \"היכן\" תתקיים). וראה משכיל לדוד ובאר בשדה על פרש\"י שם."],["702","17","ומזה גופא מובן, שאין לומר שהטעם שלא שאל אברהם \"אתמול אמרת כו'\" תיכף כשנצטווה \"קח נא גו'\" הוא לפי שידע שאפשר שהבטחת הקב\"ה תתבטל ע\"י חטא (ע\"ד פרש\"י וישלח לב, יא) — ראה ראב\"ע פרשתנו (כב, א), ובארוכה ביפה תואר ונזר הקודש הנ\"ל (הערה 6) — כי לפ\"ז מהו החידוש שלא הרהר אחרי מדותיו.\nויש לומר, שרש\"י מרמז כאן הטעם שבנדו\"ד לא שייך זה, בהעתיקו תחילת הכתוב \"לא אחלל בריתי\" [אף שאח\"כ בהמשך פירושו מפרט רק זה ש\"מוצא שפתי לא אשנה\", דקאי על הציווי ד\"קח נא\"] — כי \"לא אחלל בריתי\" קאי על ההבטחה \"כי ביצחק יקרא לך זרע\"<sup data-n=\"e24\">*</sup>, שהיתה באופן של \"ברית\" [לך יז, יט (אבל ברש\"י שם דקאי על ברית מילה). שם, כא. וכן בברית בין הבתרים — שם טו, ה. שם, יח. רש\"י פרשתנו כא, א]<sup data-n=\"e25\">**</sup>, ו\"ברית\" מורה על דבר נצחי, שלא שייך בו שינוי ואא\"פ לו להתבטל."],["703","18","אבל להעיר, שבכמה כת\"י רש\"י שתח\"י הגירסא \"אשפוך לפניך (את) שיחותי\". וכ\"ה בדפוס רומא (הנ\"ל). אבל בדפוסים הנפוצים הוא כבפנים."],["e24","*","וכמ\"ש בתנחומא פרשתנו שם. אגדת ברא­שית פל\"א. וכן מפורש בב\"ר שם להגירסא שבב\"ר הוצאת תיאודור­אלבק (וראה חילופי נוסחאות שם. וראה ב\"ר שם, ה: הפר ברית).\nולהעיר, שכ\"ה הגירסא בפרש\"י בדפוס רומא (א' מדפוסים הראשונים דפרש\"י), וכן בא' כת\"י רש\"י שתח\"י — \"כשאמרתי לך כי ביצחק. . לא אחלל בריתי ואת בריתי אקים את יצחק, כשאמרתי לך קח נא ומוצא כו'\" [ואולי נשמט זה בדפוסים שלפנינו מפני תיבות דומות (\"כשאמרתי לך. . כשאמרתי לך\")]."],["e25","**","וראה השקו\"ט ביפ\"ת ונזר הקודש שם (פנ\"ו, טו), בטעם שהביא אברהם \"כי ביצחק יקרא לך זרע\", ולא הכתוב \"ואת בריתי אקים את יצחק\" (שמפורש בו הלשון \"ברית\"). ובפשטות י\"ל כי בפסוק זה מודגשת יותר השייכות לאברהם, \"יקרא לך זרע\". ואכ\"מ."]]],[1301670140,"דהנה בד\"ה שלפנ\"ז מפרש רש\"י \"אל תשלח — לשחוט, א\"ל אם כן לחנם באתי לכאן, אעשה בו חבלה ואוציא ממנו מעט דם, א\"ל אל תעש לו מאומה, אל תעש בו מום\", היינו, שהיו כאן חילופי דברים בין אברהם והמלאך, שאברהם רצה לע­שות חבלה ביצחק (דאל\"כ נמצא ש\"לחנם באתי לכאן\"), וע\"ז ענה המלאך \"אל תעש לו מאומה, אל תעש בו מום\",\nולאחרי זה פירש אברהם את שיחתו זו, דזה שרצה לעשות חבלה ביצחק היינו מפני ש\"אתמול אמרת כו' וחזרת ואמרת כו'\", וע\"ז בא שוב מענה (הקב\"ה, ע\"י) המלאך \"כי עתה ידעתי גו'\" (ואין צורך אפילו בחבלה), כדלקמן.\nג. הסברת הענין:\nלאחרי שאברהם אמר \"א\"כ לחנם באתי לכאן אעשה בו חבלה כו'\", ונענה בשלילה (\"אל תעש לו מאומה\"), חשב אברהם, שאולי הטעם שנצטווה \"אל תש­לח ידך גו'\" (היפך הציווי ד\"קח נא גו'\") הוא לפי שאינו ראוי לזה ולא עמד ב­נסיון כדבעי, כי לבו אינו שלם עמו (דאף שמוכן לקיים ציווי זה בפועל, מ\"מ, ה\"ה מהרהר אחרי מדותיו כו'), ולפיכך אין מניחים אותו לקיים הציווי ד\"קח נא גו'\".\nוחשב אברהם שזהו ג\"כ הטעם שלא נתקבלה בקשתו ד\"אעשה בו חבלה כו'\", כי בזה \"הודה\" שבאמת אינו מוכן לקיים הציווי ד\"קח נא את בנך\" ולפיכך מבקש שעכ\"פ יוכל לקיימו במקצת (ע\"י חבלה והוצאת דם), כדי שלא תהי' ביאתו לכאן \"חנם\" — ולכן נענה בשלילה;\nוכדי לשלול קס\"ד זו המשיך אברהם לטעון — \"אפרש לפניך את שיחתי\", שבקשתו \"אעשה בו חבלה כו'\" לאחרי שנצטווה \"אל תשלח ידך לשחוט\", היתה (לא לגרוע מקיום ציווי ה', בקשה שיוכל לקיים עכ\"פ ב\"מקצת\" ה\"קח נא גו'\", אלא) לפי שלדעתו נתברר אז שזו היתה מעיקרא כוונת הציווי \"קח נא\" — לא שישחוט את בנו, אלא שיוציא דם כדי לזרקו על המזבח.\nוהטעם שחשב שזה הי' הציווי מעי­קרא — הסביר באמרו \"אתמול אמרת לי כי ביצחק יקרא לך זרע וחזרת ואמרת קח נא את בנך עכשיו אתה אומר לי אל תשלח ידך אל הנער\", כלומר: לכתחילה אכן לא הבין אברהם כיצד יכולים ל­התקיים שני דיבורי ה' (כי ביצחק גו' וקח נא גו') הסותרים (אלא שכיון ש­נצטווה בפירוש \"קח גו' והעלהו גו'\" קיים זה מבלי להרהר אחרי מדותיו של הקב\"ה); אבל עכשיו שנצטווה \"אל תשלח ידך לשחוט\", הרי אפשר להכריע בין שני הכתובים ולקיים שניהם<sup data-n=\"704\">19</sup> — ע\"י עשיית חבלה והוצאת דם (וזריקתו על המזבח).\nוזו היתה טענת אברהם \"אעשה בו חבלה כו'\", שעי\"ז יוכל לקיים ציווי ה' בשלימותו, ויתקיימו כל ג' דיבורי ה' — \"(אתמול אמרת לי) כי ביצחק גו'\"; \"קח נא גו'\"; \"(עכשיו אתה אומר לי) אל תש­לח גו'\".\nוע\"ז נענה ש\"עתה ידעתי כי ירא אלקים אתה גו'\", ואין בו שום חסרון — כי לא נמנע ממנו מלקיים ציווי השם, שהרי מלכתחלה \"לא אמרתי לך שחטהו אלא העלהו, אסקתי' אחתי'\" (וזהו הטעם שאין סתירה בין שני הענינים ד\"כי ביצ­חק גו'\" ו\"קח נא גו'\") — ונמצא שאברהם קיים ציווי השם (\"העלהו\") בשלימותו.",[["704","19","ראה גם נזר הקודש שבהערה 6. באר בשדה על פרש\"י."]]],[1301670141,"ד. עפ\"ז מתורץ בפשטות הכרחו של רש\"י על פירוש זה, שהיו כאן עוד חילו­פי דברים בין אברהם והקב\"ה (\"אתמול אמרת כו' א\"ל הקב\"ה לא אחלל בריתי כו'\") — שההכרח הוא מדברי הקב\"ה לאברהם \"כי עתה ידעתי\" (שעל זה כתב את פירושו).\nוהביאור בזה:\nלכאורה צריך ביאור, לשם מה הוצ­רך הקב\"ה לומר לאברהם שעמד בנסיון (גם בלי שחיטת יצחק) ו\"עתה ידעתי כי ירא אלקים אתה\"? הרי כשם שאברהם אבינו לא הרהר אחרי מדותיו של הקב\"ה כאשר נצטווה \"קח נא את בנך\" אלא מיהר לקיים הציווי מבלי לחפש הסברה ותירוץ על ציווי זה, הרי ודאי כאשר ציווהו הקב\"ה שוב \"אל תשלח ידך\", לא הי' צורך לבאר לאברהם הטעם על כך (שגם בלי שחיטת יצחק כבר עמד בנסיון ו\"ידעתי כי ירא אלקים אתה גו'\"), כי אברהם לא הרהר אחרי מדותיו של הקב\"ה [ובפרט שבודאי הי' יכול להבין מעצמו<sup data-n=\"705\">20</sup> שכ\"ז הי' רק נסיון<sup data-n=\"706\">21</sup> ואין צורך שהקב\"ה יאמר לו בפירוש \"כי עתה ידעתי גו'\"].\nועכצ\"ל שדברי הקב\"ה \"כי עתה ידעתי גו'\" לא באו (רק) לבאר לאברהם מטרת נסיון העקידה, אלא שזה הי' גם מענה על דברי אברהם, שאל יטעה לומר שאינו ירא אלקים ולא נתקיימה מטרת הנסיון, אלא אדרבא \"עתה ידעתי כי ירא אלקים אתה\".\nוהיינו, כנ\"ל, דכאשר אברהם שמע את הציווי \"אל תשלח גו' ואל תעש לו מאומה\", אע\"פ שהקב\"ה ציווהו \"קח נא את בנך גו' והעלהו שם לעולה\" — הסיק מזה, שאולי הטעם שהקב\"ה אינו מניחו לקיים הציווי ד\"קח נא גו'\" הוא מפני שאינו ראוי לזה — וע\"ז ענה לו הקב\"ה \"(אל תשלח גו') כי עתה ידעתי כי ירא אלקים אתה גו'\", דזה שציווהו \"אל תש­לח גו'\" אינו בגלל חסרון ח\"ו באברהם, דאדרבה, \"עתה ידעתי כי ירא אלקים אתה\", אלא זהו לפי ש\"לא אמרתי לך שחטהו אלא העלהו\".\nה. והנה בדרך זו יתיישב ג\"כ מה שהעתיק רש\"י שם בעל המאמר<sup data-n=\"707\">22</sup>, ובזה גופא נקט דוקא הגירסא ר' אבא (ולא ר' אחא — כבבראשית רבה לפנינו<sup data-n=\"708\">23</sup>).\nדע\"פ הנ\"ל יש לומר, שכוונת רש\"י בהעתיקו שמו של ר' אבא היא לרמז, שזה שר' אבא נקט שדברי אברהם \"אתמול אמרת לי כו'\" לא נאמרו כמתמי' על דברי ה' (אלא רק לפרש את שיחתו, שרוצה לקיים ציווי השם בשלימות) — כי לשיטתו אזיל:\nבמסכת חגיגה<sup data-n=\"709\">24</sup> שנינו \"כל שלא חס על כבוד קונו כו'\", ובגמרא שם<sup data-n=\"710\">25</sup> — \"מאי היא, ר' אבא<sup data-n=\"711\">26</sup> אמר זה המסתכל",[["705","20","ראה יפ\"ת ונזר הקודש הנ\"ל (פנ\"ו, יב)."],["706","21","ובפרט ע\"פ פרש\"י לעיל (כב, ב) \"א\"ל בבקשה ממך עמוד לי בזה הנסיון כו'\"."],["707","22","ובפרט שלעיל על הפסוק (כב, ב) \"והעלהו שם לעולה\" כבר הביא רש\"י את הפירוש \"לא אמר לו שחטהו. . אלא להעלהו\" — ושם לא העתיק שם בעל המאמר (אף שג\"ז מקורו במאמר זה של ר' אבא)."],["708","23","וכן במדרש תנחומא, כנ\"ל הערה 9."],["709","24","משנה שם רפ\"ב (יא, ב)."],["710","25","טז, א."],["711","26","בקידושין (מ, סע\"א) הובא מאמר זה בשם רבה<sup data-n=\"e26\">*</sup>. אבל ע\"פ הידוע שסוגיא במקומה ראוי לסמוך עלי' יותר מסוגיא שאינה במקומה (דרכי שלום (בשד\"ח הוצאת קה\"ת כרך י') כללי הש\"ס אות ס' סתי\"ז. וש\"נ) — נ\"ל שהגירסא העיקרית היא ר' אבא, כבחגיגה שם, שהרי שם עיקר מקומה של הסוגיא ע\"ד \"כבוד קונו\"."],["e26","*","וכ\"ה גירסת הר\"ח בחגיגה שם. ובנוסח הכ\"י בדק\"ס חגיגה שם — \"רבא\", ובהמשך הגמ' שם \"רבה\". וראה בהגהות שם."]]],[1301670142,"בקשת. . דכתיב<sup data-n=\"712\">27</sup> כמראה הקשת אשר יהי' בענן ביום הגשם כן מראה הנוגה סביב הוא מראה דמות כבוד ה'\".\nוהנה, אף שבפשטות כוונת ר' אבא היא, שההסתכלות בקשת היא כעין הסתכלות במראה השכינה (כיון ש\"מראה הקשת. . כן מראה הנוגה סביב גו'\")<sup data-n=\"713\">28</sup>, מ\"מ מצינו<sup data-n=\"714\">29</sup>, שאיסור הסתכלות בקשת שייך ג\"כ לאות הקשת שלא יהי' עוד מבול (שלכן מברכים על ראיית הקשת \"ברוך זוכר הברית\"<sup data-n=\"715\">30</sup>, כמובא בהמשך הסוגיא שם<sup data-n=\"716\">31</sup>).\nו. ויובן זה בהקדים דיוק הלשון \"המסתכל בקשת\", שהכוונה בזה אינה לראי' סתם — שהרי אדרבה, חכמים תקנו ברכה מיוחדת על ראיית הקשת — אלא הסתכלות באופן של עיון<sup data-n=\"717\">32</sup> והת­בוננות<sup data-n=\"718\">33</sup>.\nויש לבאר הדיוק בזה: השייכות בין קשת לכבוד קונו הוא מפני \"מראה ה­קשת\" שראה יחזקאל במרכבה (\"כמראה הקשת גו' כן מראה הנוגה סביב\"), ובפרט ע\"פ המסופר בגמ' שם לפנ\"ז<sup data-n=\"719\">34</sup> דכאשר דרש ר' יהושע במעשה מרכבה \"נתקשרו שמים בעבים ונראה כמין קשת בענן\", שמזה מובן עוד יותר, שמראה הקשת שייך למעשה מרכבה. וזהו תוכן האיסור להסתכל בקשת, לפי שזה מרמז על ההסתכלות וההתבוננות בעניני מעשה מרכבה, שזהו היפך כבוד קונו, לפי שענינים אלו צ\"ל בהסתר דוקא<sup data-n=\"720\">35</sup> (בלשון הכתוב<sup data-n=\"721\">36</sup> \"כבוד אלקים הסתר דבר\"), כיון שהם למעלה מהשגת השכל האנושי וההתבוננות בהם תביא לידי שאלות וספיקות כו' [ועפ\"ז שני הענינים שבמשנה<sup data-n=\"722\">37</sup> — (א) האיסור לדרוש במעשה מרכבה אפילו ביחיד \"אא\"כ הי' חכם כו'\", (ב) \"כל שלא חס על כבוד קונו\" (שלפי ר' אבא קאי על המסתכל בקשת) — תוכנם חד].\nועפ\"ז יש לומר, שתוכן איסור זה שייך גם לאות הקשת, כי מצד \"כבוד קונו\" אין ראוי להסתכל ולהתבונן בתוכן ענין הקשת, כיון שיכולה להתעורר עי\"ז שאלה<sup data-n=\"723\">38</sup> וקושיא על הנהגתו של הקב\"ה, שבהמשך אלי' ניתנה אות הקשת.\nדהנה הטעם שלא יהי' עוד מבול על הארץ (שע\"ז בא אות הקשת) מפורש בקרא<sup data-n=\"724\">39</sup> \"לא אוסיף לקלל עוד את האד­מה בעבור האדם כי יצר לב האדם רע",[["712","27","יחזקאל א, כח."],["713","28","וראה ר\"ח חגיגה שם: זה המסתכל בקשת ואומר כגון זה דמות ה'."],["714","29","ראה רמב\"ן נח (ט, יב). אברבנאל שם. ולהעיר גם מכלי יקר (שם, יד). ועוד."],["715","30","ברכות נט, א."],["716","31","לפי גירסת הע\"י חגיגה שם. וראה גם הגהות הב\"ח שם."],["717","32","ב\"י לטאו\"ח סרכ\"ט בשם הרא\"ש. וראה פרישה שם. וראה ערוך מע' קשת. — וראה ערכי הכינויים (לבעל סה\"ד) מע' ראי'. יד מלאכי (כלל ה\"א אות קעט). שד\"ח כללים מע' הה\"א (כרך א' קטו, ב. כרך ח א'תרפא, ב ואילך). וש\"נ."],["718","33","ע\"ד \"הסתכל בשלשה דברים כו'\" (אבות רפ\"ב ורפ\"ג) — אוה\"ת שה\"ש (ע' שלא). וראה סה\"מ תש\"א ע' 113 ואילך. ועוד."],["719","34","חגיגה יד, ב. ועד\"ז בכ\"מ בזהר. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171362\" data-slug=\"likkutei-sichot\" data-id=\"1300171362\">לקו\"ש חי\"ז ע' 362</a> ואילך."],["720","35","כאריכות הסוגיא בחגיגה שם רפ\"ב (יג, א ואילך)."],["721","36","משלי כה, ב. וראה ירושלמי חגיגה שם (פ\"ב ה\"א)."],["722","37","חגיגה שם רפ\"ב."],["723","38","ראה גם אברבנאל נח שם."],["724","39","נח ח, כא."]]],[1301670143,"מנעוריו\", והרי סברא זו עצמה שימשה כטעם להבאת המבול, כמ\"ש<sup data-n=\"725\">40</sup> \"וירא ה' כי רבה רעת האדם בארץ וכל יצר מחשבות לבו רק רע כל היום\". ומה נש­תנה שבתחילה סברא זו חייבה להביא המבול, ואח\"כ נהפך שסברא זו עצמה תחייב שלא להביא עוד מבול על ה­ארץ<sup data-n=\"726\">41</sup>?!\nועוד זאת: כיון שהקב\"ה ברא את האדם מלכתחילה באופן ש\"יצר לב האדם רע מנעוריו\", הרי ודאי שהי' ידוע לפניו ית' שסו\"ס יבוא לידי מצב ש\"יצר מחשבות לבו רק רע כל היום\", ואעפ\"כ ברא הקב\"ה את עולמו, ומה נתחדש אח\"כ שבגלל זה \"וינחם<sup data-n=\"727\">42</sup> ה' כי עשה את האדם\"?\nוזהו שאומר ר' אבא שהמסתכל ב­קשת — היינו המעיין ומתבונן בתוכן אות הקשת — ה\"ז בגדר \"לא חס על כבוד קונו\"<sup data-n=\"728\">43</sup>, כי התבוננות זו יכולה לגרום אצלו לספיקות אודות הנהגת הקב\"ה.\nור' אבא לשיטתו, שודאי שאברהם לא כיוון לתמוה על הסתירה בדברי הקב\"ה — \"אתמול אמרת כו' וחזרת ואמרת כו'\" — היפך הנהגה של \"חס על כבוד קונו\", אלא כוונתו היתה אך ורק לפרש לפני הקב\"ה \"את שיחתי\", כנ\"ל באורך.\n<span data-k=\"q\">(משיחת ש\"פ וירא תשמ\"ח)</span>",[["725","40","ס\"פ בראשית (ו, ה)."],["726","41","כמו שהקשה באברבנאל (ועוד) נח שם. וראה ע\"ד החסידות — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370068\" data-slug=\"torah-or\" data-id=\"3901370068\">תו\"א פרשתנו (טו, סע\"ב</a>). תו\"ח שם (ד\"ה ארדה נא פ\"כ ואילך). המשך באתי לגני השי\"ת פי\"ח. ועוד."],["727","42","בראשית שם, ו. — וראה רש\"י שם \"וזה כתבתי לתשובת אפיקורוס א'. . אין אתם מודים שהקב\"ה רואה את הנולד כו' א\"ל כך מעשה הקב\"ה כו'\"."],["728","43","וכמשנ\"ת במ\"א (שיחת ש\"פ בראשית תשל\"ו. וראה סה\"ש תנש\"א ח\"א ע' 70 ואילך) בדיוק ל' רש\"י הנ\"ל \"וזה כתבתי לתשובת אפיקורוס א'\", שאין השקו\"ט בשאלה זו דבר הראוי כו'. וראה גם לקו\"ש חל\"ד ע' 15­14."]]],[1301670144,"<h3>שיחה א</h3>\nא. עה\"פ<sup data-n=\"729\">1</sup> \"ויקם שדה עפרון\" פרש\"י \"תקומה היתה לו שיצא מיד הדיוט ליד מלך. ופשוטו של מקרא ויקם השדה והמערה אשר בו וכל העץ לאברהם<sup data-n=\"730\">2</sup> למקנה וגו'\".\nובפשטות כותב כאן רש\"י ב' פירו­שים בתיבת \"ויקם\": א) מלשון תקומה, ב) מלשון \"קנין\", והוא פשוטו של מקרא, \"דומיא<sup data-n=\"731\">3</sup> דוקם<sup data-n=\"732\">4</sup> הבית אשר בעיר אשר לו חומה לצמיתות לקונה שפרש\"י<sup data-n=\"732\">4</sup> יצא מ­כחו של מוכר ועמד בכחו של קונה\"<sup data-n=\"734\">5</sup>.\nוזה שלא הסתפק רש\"י בפירוש ויקם מלשון קנין, כפשוטו של מקרא, כתבו מפרשים<sup data-n=\"735\">6</sup>, שהוא משום \"שאין הקונה כתוב אחר הקימה (כמו בכתוב דוקם הבית כו' לצמיתות לקונה) כי לאברהם למקנה אינו דבק עם הפסוק הקודם לו מפני פיסוק הטעמים, [ו]עכ\"ל שאין פי­רוש ויקם אלא מלשון תקומה. . אבל לפי פשוטו של מקרא דלא חייש לפיסוק הטעמים פירשוהו כמשמעו מלשון קנין דומיא דויקם<sup data-n=\"736\">7</sup> השדה והמערה וזהו ש­אמר ופשוטו של מקרא ויקם השדה וה­מערה וכל העץ לאברהם למקנה הדביק לאברהם למקנה עם מלת ויקם שבפסוק הקודם לאפוקי מבעלי הדרש שלא הדביקום\".\nולכאורה ביאור זה דחוק הוא, שהרי כבר קבע רש\"י כלל גדול<sup data-n=\"737\">8</sup> בנוגע לפי­רושו \"אני לא באתי אלא לפשוטו של מקרא ולאגדה המיישבת דברי המקרא\", היינו, שרק כשיש קושי בכתוב שאינו מתורץ ע\"ד הפשט אזי מביא דברי אגדה ליישב הפשט. ומאחר שעל פי \"פשוטו של מקרא (ד)לא חייש (רש\"י) לפיסוק הטעמים\"<sup data-n=\"738\">9</sup>, הרי שבפשוטו של מקרא אין זו קושיא (וכפי שמצינו כמה פעמים ב­כמה כתובים שהם בהמשך זל\"ז אף שהם ב' פסוקים<sup data-n=\"739\">10</sup>), וא\"כ למה הוצרך רש\"י להביא עוד פי' מבעלי הדרש<sup data-n=\"740\">11</sup>, ויתירה מזו, מקדימו כפירוש ראשון ועיקרי ב­פשוטו של מקרא.\nב. יש מבארים<sup data-n=\"741\">12</sup>, דלפי הפירוש ב­פשוטו של מקרא הרי התיבות \"שדה עפרון אשר במכפלה אשר לפני ממרא\" מיותרות, דהול\"ל \"ויקם השדה והמערה וגו' לאברהם למקנה גו'\", דאטו עד השתא לא ידענא שהי' שדה עפרון. ולכן מפרש שהיתה תקומה לשדה עפרון, שכלל השדה היתה לו תקומה, ולכך אמר שדה עפרון, כלומר שהשדה שהי' מתייחס לעפרון ושבמכפלה ושעל פני ממרא תקומה היתה לו שנכנס לרשות אברהם, אבל לאידך — לפי' המדרש \"תקומה היתה לו\" קשה, כיון דכבר אמר \"",[["729","1","פרשתנו כג, יז."],["730","2","שם, יח."],["731","3","לשון הרא\"ם כאן."],["732","4","בהר כה, ל."],["732","4","בהר כה, ל."],["734","5","וראה שפ\"ח כאן בסופו."],["735","6","רא\"ם. וראה גם גו\"א ולבוש כאן."],["736","7","פרשתנו כג, כ."],["737","8","בראשית ג, ח. ובכ\"מ."],["738","9","וכ\"ה בלבוש שם."],["739","10","כן הקשה ביפ\"ת השלם לב\"ר כאן (פנ\"ח, יוד (ח)) \"כמה פסוקים דבוקים כו' רבו מספר\". ע\"ש."],["740","11","בגו\"א שם: ופשוטו של מקרא כו' ואין להקפיד על שהפסיק בשני כתובים לפי שרמז לך ג\"כ המדרש הנזכר. ועדיין צ\"ע למה הקדים רש\"י הדרש, כבפנים."],["741","12","שפ\"ח כאן ויפ\"ת השלם לב\"ר שם."]]],[1301670145,"ויקם שדה עפרון\" למה הזכיר פעם ב' \"השדה והמערה כו'\", הול\"ל \"ויקם שדה עפרון וגו' והמערה וכל העץ\", וגם דלפי פי' תקומה היתה לו אין לו חיבור עם כתוב שלאח\"ז לאברהם למקנה — לכך צריך גם הפירוש לפי \"פשוטו\" שקם ה­שדה והמערה וכל העץ לאברהם למקנה.\nולפי פירוש זה, כוונת רש\"י היא, שהפסוק עצמו מכריח ב' פירושים, דבזה שמתחלה אמר שדה עפרון ואח\"כ כפל השדה והמערה מוכח, דתרתי קמ\"ל, שהיתה תקומה לשדה עפרון ושקם השדה והמערה לאברהם למקנה.\nאך עדיין אינו מובן, מדוע מקדים רש\"י הפירוש שע\"ד הדרש לפשוטו של מקרא?\n[בפשטות י\"ל דסדר הפירושים שב­פרש\"י הוא לפי סדרם בפירוש הכתוב (\"ויקם שדה עפרון — תקומה היתה לו\", והמשך הכתוב \"השדה והמערה גו'\" פי­רושו ד\"ויקם. . לאברהם למקנה\"). אבל לכאורה אין זה טעם מספיק להקדים דרש לפני הפירוש ע\"פ \"פשוטו של מק­רא\"].\nולכן צ\"ל דס\"ל לרש\"י, שפירוש \"ויקם\" מלשון \"תקומה\" אינו דרש בלבד, וכדמוכח גם מזה שרש\"י אינו מקדים \"ארז\"ל\" או \"רבותינו פירשו\" וכיו\"ב.\nוזה שמדגיש בפירוש השני \"ופשוטו של מקרא ויקם השדה כו' לאברהם ל­מקנה\" הוא ללמדנו, שהיתרון בפירוש \"תקומה היתה לו\", שבגללו מקדימו לפירוש השני, הוא [לא מצד הפשט של מקרא זה — שהרי \"פשוטו של מקרא\" זה, הן פירוש תיבת \"ויקם\" והן פשטות המשך ב' המקראות, הוא כפירוש השני<sup data-n=\"742\">13</sup>, ד\"ויקם כו' לאברהם למקנה\" היינו ש­נקנה לאברהם — אלא] משום שעל ידו מתורץ קושי בכללות הפרשה כאן [אף שפשוטו של מקרא זה הוא כפירוש השני].\nג. והביאור בזה: בתחלה, כשדבר אברהם עם בני חת, בקש מהם \"תנו<sup data-n=\"743\">14</sup> לי אחוזת קבר עמכם ואקברה מתי מלפני\", וכן לאח\"ז<sup data-n=\"744\">15</sup> כשבקש \"אם יש את נפשכם לקבור את מתי מלפני שמעוני ופגעו לי בעפרון בן צוחר\" בקש \"ויתן לי את מערת המכפלה. . אשר בקצה שדהו. . לאחוזת קבר\", כלומר, כל השקו\"ט היתה אודות המערה בלבד; אמנם לאחר ש­אמר עפרון לאברהם<sup data-n=\"745\">16</sup> \"לא אדני שמעני השדה נתתי לך והמערה אשר בו לך נתתי'\", ענה אברהם<sup data-n=\"746\">17</sup> \"נתתי כסף השדה קח ממני ואקברה את מתי שמה\", שקיבל הצעת עפרון על השדה, ואפילו לא הזכיר את המערה.\nוצריך ביאור: זה שעפרון הציע \"לא אדני שמעני השדה נתתי לך\" יל\"פ גם לפי פשוטו של מקרא, שכוונת עפרון היתה רק להראות ישרותו וטוב לבו, כתוכן דיבורו בכלל \"לא<sup data-n=\"747\">18</sup> אדוני לא תקנה אותה בדמים\", \"נתתי לך\", אבל באמת רצה להוציא עוד כסף מאברהם (וכפי שמביא רש\"י בהפרשה<sup data-n=\"748\">19</sup> שאמר הרבה ואפילו מעט לא עשה)<sup data-n=\"749\">20</sup>, אבל למה קיבל אברהם הצעה זו מעפרון",[["742","13","להעיר, שגם בתיב\"ע כאן פסוק יז \"וקם זבין כו'\"."],["743","14","כג, ד."],["744","15","כג, ח­ט."],["745","16","כג, יא."],["746","17","כג, יג."],["747","18","רש\"י שם, יא."],["748","19","כג, טז."],["749","20","ראה רמב\"ן כאן (כג, ט): אמר לו דרך מוסר או מרמה."]]],[1301670146,"[במפרשי התורה<sup data-n=\"750\">21</sup> ביארו הדבר, אבל לכאורה זוהי שאלה גם בפשוטו של מקרא, והו\"ל לרש\"י לתרצה, ולכאורה לא מצינו ביאור בזה בפרש\"י].\nגם צלה\"ב (כדיוק המפרשים<sup data-n=\"751\">22</sup>) בה­פסוקים כאן \"ויקם שדה עפרון אשר במכפלה גו' השדה והמערה. . לאברהם למקנה גו' ואחר כן קבר אברהם את שרה אשתו גו' ויקם השדה והמערה אשר בו לאברהם לאחוזת קבר מאת בני חת\", למה הוצרך לומר ב' פעמים \"ויקם\"?\n[באור החיים האריך בזה<sup data-n=\"752\">23</sup>, ומבאר, שזהו להודיע ד\"היתה הקני' כאן ככל משפטי הקנין\", ד\"לאחר ששקל אברהם לעפרון דמי המערה בזה סלק עפרון זכותו מעל הקרקע כמ\"ש רמב\"ם<sup data-n=\"753\">24</sup>. . שהגוי מעת שלקח הדמים סילק זכותו וישראל לא קנה עד שיגיע שטר לידו, ונמצאו נכסים אלו כנכסי מדבר\", וגמר הקנין הי' אח\"כ \"באמצעות החזקה ש­הוחזק בה במה שקבר בה את שרה\"<sup data-n=\"754\">25</sup>. וזהו ה\"ויקם\" השני שרק אז אחרי שקבר את שרה נקנה לאברהם. אבל ביאור זה הוא ע\"פ הלכה, כי בפשש\"מ אין שום רמז לכל זה, ובפשטות נקנה השדה לאברהם על ידי הכסף גופא, כפשוטו של מקרא].\nוכדי לתרץ כל זה מקדים רש\"י עה\"פ \"ויקם שדה עפרון — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", כדלקמן.\nד. ויובן זה ע\"פ ביאור דיוק ל' רש\"י \"מיד הדיוט ליד מלך\", דלכאורה<sup data-n=\"755\">26</sup> הרי עפרון נעשה שר<sup data-n=\"756\">27</sup> קודם המכירה, כמו שהביא רש\"י לפנ\"ז<sup data-n=\"757\">28</sup> \"אותו היום מנוהו שוטר<sup data-n=\"758\">29</sup> עליהם מפני חשיבותו של אבר­הם\", והול\"ל ל' רשע וצדיק וכיו\"ב ולא \"הדיוט\" ו\"מלך\" (ובמדרש<sup data-n=\"759\">30</sup> אכן איתא \"דהות דבר איניש זעיר ואיתעבידת לבר נש רב\").\nוהביאור בזה: החילוק בגדר הקנין כשהדיוט קונה מהדיוט, גם כשאחד חשוב מהשני, לקנין של מלך הוא, דקנין הדיוט מהדיוט תוכנו שינוי רשות, והיינו דשם הקנין הוא, יציאה מבעלות א' לבעלות שני, ובמילא אף שיש בזה שי­נויים באופני הקנין דכסף שטר וחזקה<sup data-n=\"760\">31</sup>, הרי בכל האופנים שם הקנין הוא יציאה מרשות א' לשני.",[["750","21","ראה רמב\"ן שם. ר\"י בכור שור (שם, יא­יב). חזקוני (שם, יא). אברבנאל כאן. אוה\"ח שם (סוף פסוק ט)."],["751","22","ראה רשב\"ם. חזקוני (פסוק יז; כ). ריב\"א. ר\"י בכור שור. רבינו בחיי פסוק כ. ועוד. וראה גם אברבנאל כאן."],["752","23","פסוק יט. וראה בהנסמן בהערה שלפנ\"ז."],["753","24","הל' זכי' ומתנה פ\"א הי\"ד."],["754","25","ל' האוה\"ח (וראה גם ר\"י בכור שור, חזקוני ורבינו בחיי). וראה בהנסמן לקמן הערה 37."],["755","26","כן הקשה במשכיל לדוד על פרש\"י כאן."],["756","27","כן הוא במשכיל לדוד \"קודם המכירה נעשה שר על העיר\". אבל לשון רש\"י היא (כדלקמן בפנים) \"שוטר\", ולא \"שופט\"<sup data-n=\"e27\">*</sup> כלשון רש\"י בלוט (לעיל וירא יט, א), וכבמדרש כאן (ב\"ר פנ\"ח, ז) ארכוסטרטיגוס (פירוש הערוך גדול שבנציבים. מ\"כ לב\"ר). ולהעיר גם מהשינוי בהמשך רש\"י \"מפני חשיבותו של אברהם שהי' צריך לו עלה לגדולה\", ובמדרש \"דלא יהא בר נש רב זבין מן בר נש זעיר\". אבל במושב זקנים עה\"ת מעתיק מ\"פי' ר\"ש\" \"אותו היום מינוהו שר ושופט עליהם על שנצטרך לו אברהם\". ואולי תיבת \"שוטר\" בפרש\"י כאן פירושה \"שופט\". ודוחק גדול הוא כפשוט. ואכ\"מ."],["757","28","כג, יוד."],["758","29","ראה לעיל הערה 27."],["759","30","ב\"ר פנ\"ח, ח. וראה יפ\"ת השלם שם."],["760","31","ראה הערה הבאה."],["e27","*","אבל להעיר שבדפוס שני דרש\"י כאן: שופט."]]],[1301670147,"אבל כאשר מלך קונה מיד הדיוט, הרי זה באופן דהפקעת רשות לגמרי, ואין לייחסו כאן לשם הפרטי של האיש שהוא זה שמכר השדה להמלך.\nבסגנון אחר: כאשר א' קונה מהשני, מכיון שגדרו של קנין הוא מעשה משו­תף דהמוכר (הנותן) והקונה (המקבל), אם במעשה הקנין או בסמיכת דעת — הק­נאת המוכר, הרי כשם שבמעשה הקנין ישנו שם המוכר<sup data-n=\"761\">32</sup>, נשאר השם גם על גוף השדה, ששדה זו לקח פלוני מפלוני.\nמשא\"כ בקניית מלך, עיקר גדר קנין הוא לא מצד הנותן והמוכר, אלא מצד המלך (והרי בידו של המלך ליקח הכל מאנשי המדינה בפועל<sup data-n=\"762\">33</sup>), ולכן לא נשאר שם בעלות שלפנ\"ז על השדה<sup data-n=\"763\">34</sup>.\nוזהו שמדייק רש\"י \"תקומה היתה לו שיצא מיד הדיוט ליד מלך\", שאין זה רק גדר קנין סתם ממוכר ללוקח, דשדה עפרון נקנה לאברהם, אלא \"תקומה הי­תה לו\", יציאה משם הדיוט לשם מלך, ובמילא אין כאן שייכות לשם פרטי ואין נפק\"מ בזה בין הדיוט ממש לשר — כי בזה שווים הם.\nה. ויש לומר, שענין זה הוא בהתאם לתוכן הכללי בהנהגת אברהם, שלא רצה לקבל המערה במתנה אלא קנאה, ובזה גופא הדגיש שקנייתו תהי' \"בכסף מלא\", \"אשלם כל שווי'\"<sup data-n=\"764\">35</sup> — שכוונת אברהם בזה היתה כדי לסלק (שם) עפ­רון לגמרי מן השדה, היינו לא רק שלא יהי' לעפרון שום בעלות וזכות (או אף שייכות) ממוני בהשדה [שעי\"ז אין שום סרך של \"צדיק<sup data-n=\"765\">36</sup> קבור בקבר שאינו שלו\"<sup data-n=\"766\">37</sup>], אלא עוד זאת, שגם נסתלק שמו של עפרון מהשדה<sup data-n=\"767\">38</sup>, אפילו בתור \"נותן\" או \"מוכר\" מקום קבר לקבורת שרה.\nומטעם זה הדגיש \"בכסף מלא\", היינו שהכסף שנותן אינו בגדר קנין כסף, אלא שנותן כל שוויות השדה<sup data-n=\"768\">39</sup>, כי בקנין כסף יש השתתפות דנתינת וסמיכת דעת המקנה (כנ\"ל), משא\"כ כשמשלם בכסף שוויות הדבר, באופן שלא חסר כלום אצל המוכר, הרי עיקר הקנין הוא מצד (נתינת שוויות הדבר ד)הקונה ולא הק­נאת המקנה (המוכר).\nועפ\"ז מובן עוד יותר הדגשת הכתוב אחרי הסיפור ש\"וישקול אברהם לעפרון את הכסף גו'\"<sup data-n=\"748\">19</sup> — \"ויקם שדה עפרון\". דלכאורה, לפי פשוטו של מקרא שה­",[["761","32","אלא שבזה חילוקי קנינים, אם הוי עיקרו מצד הקונה (כבחזקה) או מצד המקנה­המוכר (בשטר), ולפי מדה זו תלוי תוקף שם המקנה על הקרקע (אבל בכללות בכל קנין ישנה השתתפות שניהם). וראה סוגיית הגמ' והלימודים בקידושין כו, א. ואכ\"מ."],["762","33","ראה רמב\"ם הל' מלכים פ\"ד."],["763","34","ויש להוסיף בזה: מכיון שכל אנשי המדינה וכל אשר להם הם ברשות ובעלות המלך, דרכוש העיר והמדינה הוא בבעלותו הכללית תמיד, הרי נמצא, דכאשר הוא בבעלות הפרטית של א' מאנשי המדינה, הוא ע\"ד נתינת רשות מהמלך להשתמשות, ובמילא, כשעובר בחזרה לבעלות המלך בטל לגמרי שם ההדיוט."],["764","35","כג, ט ובפרש\"י."],["765","36","ב\"ב קיב, א."],["766","37","אברבנאל כאן. וראה נחלת יעקב לפרש\"י כאן שבא ללמד שלא רצה אברהם לקוברה עד שקנה השדה והמערה בכל דיני הקנאות כו' לפיכך קנאה אברהם בתחלה בכסף ואח\"כ בשטר כו' ואח\"כ כו' החזקה. עיי\"ש. וראה פדר\"א פל\"ו וברד\"ל שם. ש\"ך עה\"ת פרשתנו עה\"פ (יז). וראה שו\"ת חת\"ס יו\"ד סי' שלא — בפירוש דברי הרמב\"ן פרשתנו כג, יא. צפע\"נ עה\"ת כאן פסוק יט. ועוד."],["767","38","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101062\" data-slug=\"likkutei-sichot\" data-id=\"1300101062\">לקו\"ש ח\"י ע' 62</a> ואילך.\nודברי יעקב (ויחי מט, כט­לב) היו כדי שלא יערערו כו' כמ\"ש במפרשי התורה שם. וראה סוף פרשתנו (כה, ט­י). ואכ\"מ."],["768","39","ראה ש\"ך עה\"ת שם."],["748","19","כג, טז."]]],[1301670148,"כוונה היא שנקנה לאברהם, מאי קמ\"ל כאן, ולכאורה כל הפסוק מיותר הוא? וזהו שמפרש רש\"י דתוכן הכתוב כאן — \"תקומה היתה לו, שיצא מיד הדיוט ליד מלך\", שהכתוב בא לומר, דנוסף לסילוק שם עפרון מן השדה ע\"י עצם קניית השדה \"בכסף מלא\", הנה עוד זאת, ש\"ויקם גו' — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", שנפקע שם עפרון לגמרי מן השדה, כיון \"שיצא מיד הדיוט ליד מלך\", כנ\"ל.\nוזהו גם דיוק הלשון בכתוב שלאח\"ז — \"ואחרי כן קבר אברהם את שרה אשתו אל מערת שדה המכפלה\" (דלכ­אורה פשיטא שקבר את שרה רק לאחרי שקנה השדה) — כי רק לאחרי ש\"תקומה היתה לו\", שנפקע לגמרי שם הדיוט ממנה, היינו שלא רק שלא נשאר שום בעלות לעפרון<sup data-n=\"770\">40</sup>, אלא עוד זאת, דאין כאן שום ענין של הדיוט (אפילו שהוא מכר את השדה לאברהם), כי הוא שדה של \"מלך\" בלי שום שייכות גם בשם (שהי' למפרע) לשם עפרון — אז קבר אברהם את שרה אשתו.\nו. בדרך זו יש ליישב עוד דיוק בהמשך השקו\"ט דאברהם ובני חת<sup data-n=\"771\">41</sup>:\nאברהם ביקש תחילה \"תנו<sup data-n=\"743\">14</sup> לי אחוזת קבר עמכם\", ובפרש\"י \"אחוזת קבר לבית הקברות\", היינו, שאברהם ביקש לא רק מקום לקבורת שרה בלבד (או אפילו לקברים אחדים), אלא \"אחוזת קרקע לבית הקברות\", ואילו בני חת ענו<sup data-n=\"773\">42</sup> \"במבחר קברנו (קבר שלנו) קבור את מתך, איש ממנו את קברו לא יכלה ממך מקבור מתך\", שמזה מובן שלא רצו לתת לאברהם \"אחוזת קרקע לבית הקברות\";\nועד\"ז מצינו אח\"כ, כשביקש מעפרון מערת המכפלה \"אשר בקצה שדהו\", אמר אברהם \"בכסף מלא יתננה לי גו' לאחוזת קבר\"<sup data-n=\"774\">43</sup>, אמנם לאחרי שעפרון הציע לו את כל השדה עם \"המערה אשר בו לך נתתי'. . קבור מתך\"<sup data-n=\"745\">16</sup>, הסכים אברהם ואמר \"ואקברה את מתי שמה\"<sup data-n=\"746\">17</sup> (ושוב לא הדגיש הענין ד\"אחוזת קבר\");\nולאידך, בסיום הענין, אחרי סיפור קבורת שרה בפועל, נאמר שוב<sup data-n=\"736\">7</sup>: \"ויקם השדה והמערה גו' לאחוזת קבר\"!\nוע\"פ הנ\"ל י\"ל הביאור בזה:\nכוונת אברהם בזה שבקש \"אחוזת קבר — אחוזת קרקע לבית הקברות\", היתה שהוא יעשה את אחוזת הקרקע ל­בית הקברות, היינו שקודם כל הוא יקנה אחוזת קרקע, ורק אחרי שהיא בבעלותו של אברהם יעשנה \"בית הקברות\", כי עי\"ז מודגש יותר שאין שמו של עפרון על \"בית הקברות\" זה.\nאבל לאחרי שעפרון הציע לתת לו את כל השדה (לא רק המערה המיוחדת לקבורה), שוב לא הי' צורך להדגיש שקונה \"אחוזת קבר\", כיון שכל השדה (לא רק המערה) הוא בבעלותו של אבר­הם, באופן שפעולתו ומעשהו בהשדה אינו שייך כלל לנותן ומוכר השדה, ואז \"ואקברה את מתי שמה\", כי אין בתוכן קבורת שרה בשדה שום שייכות לעפרון, אלא אדם עושה בתוך שלו וא\"צ שימכרו לו.\nועפ\"ז מובן גם הטעם שבסיום הענין מוסיף הכתוב עוד פעם \"ויקם השדה והמערה אשר בו לאברהם (ומדייק) ל­",[["770","40","ראה הערה 37."],["771","41","ראה גם מלבי\"ם כאן, ומבאר כל השקו\"ט בהכתובים ע\"פ הרמב\"ן שהי' חוק ונימוס לבני חת שלא ליתן אחוזת קבר לגר כו'."],["743","14","כג, ד."],["773","42","כג, ו."],["774","43","כג, ט."],["745","16","כג, יא."],["746","17","כג, יג."],["736","7","פרשתנו כג, כ."]]],[1301670149,"אחוזת קבר\", להדגיש, דסו\"ס נתקיימה בקשת אברהם שיותן לו \"אחוזת קבר\", וזהו \"ויקם\" (\"תקומה\") השני, כי בזה שהשדה נעשה \"אחוזת קבר\" של אברהם, נתחזקה בעלותו על השדה, ובמילא מובן שהוספה זו בשייכותו של השדה לאבר­הם הוסיפה ג\"כ במעלת השדה (\"תקומה היתה לו\"); אלא שתקומה זו היתה צ\"ל רק לאחרי ש\"ויקם שדה עפרון — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", וכבר נפקע שם עפרון לגמרי מן השדה [ומ\"ש גם ב\"ויקם\" השני \"מאת בני חת\", ה\"ז רק משום שבתחילה הי' השדה ב­בעלות כללית שלהם<sup data-n=\"778\">44</sup>].\nז. והנה ידוע דחברון<sup data-n=\"779\">45</sup> ובפרט מקום מערת המכפלה הוא המקום הראשון בא\"י שנקנה לעם ישראל בפועל לצמי­תות, וכדאיתא במדרש<sup data-n=\"780\">46</sup> שהוא \"אחד משלשה מקומות שאין אומות העולם יכולין להונות את ישראל לומר גזולים הן בידכם ואלו הן מערת המכפלה<sup data-n=\"781\">47</sup> ובית המקדש וקבורתו של יוסף\".\nוי\"ל שמזה מובן, שיש הוראה בעבו­דה הרוחנית של כאו\"א מישראל ד\"מאַך דאָ ארץ ישראל\"<sup data-n=\"782\">48</sup> (\"עשה כאן א\"י\"), שבכל מקום המצאו צריך יהודי לעשות ארץ ישראל — שעשיית ארץ ישראל היא באופן ש\"תקומה היתה לו, שיצא מיד הדיוט ליד מלך\".\nוביאור הענין:\nכשם שתקומת השדה היתה עוד קודם קבורת שרה, אלא ע\"י זה שנכנס לרשותו של אברהם, הנה עד\"ז בעבודה רוחנית, שכאשר יהודי בא לאיזה מקום או שיש לו שייכות לענין שבעולם שפשוט ש\"מה' מצעדי גבר כוננו ודרכו יחפץ\"<sup data-n=\"783\">49</sup>, לקיים שליחותו לעשות ממנו א\"י, עליו להכיר ולדעת, שע\"י עצם המצאו במקום ההוא הרי \"תקומה היתה לו\", שעוד בטרם גישתו לקיים בו מצוה כו', כבר נעשה במקום ענין של עלי' ותקומה<sup data-n=\"784\">50</sup>, יציאה מיד הדיוט, ע\"י עצם הענין שהוא ברשות ישראל.\nומזה מובן עוד ענין, שאי אפשר שיהי' שום מונע מעבודתו ומעכב לעשות \"כאן ארץ ישראל\", כי מאחר ש\"תקומה היתה לו\", כי כבר יצא מיד הדיוט ליד מלך, ועד למלכו של עולם, ע\"י שנכנס לרשות ישראל, שכל ישראל בני מלכים הם<sup data-n=\"785\">51</sup>, ויתירה מזו, מלכים הם<sup data-n=\"786\">52</sup>, והיינו שגם כאשר הדבר שבעולם הוא לא סתם דבר גשמי אלא ענין ודבר חשוב בעולם (כמו עפרון שלא הי' הדיוט, שהרי עלה לגדולה, מנוהו שוטר עליהם), מ\"מ לגבי",[["778","44","להעיר מריב\"א, פענח רזא ומושב זקנים כאן. וראה בארוכה לקו\"ש חלק ל' (ע' 84, 86)."],["779","45","ראה הערה 47."],["780","46","ב\"ר פע\"ט, ז."],["781","47","בבחיי כאן סוף פסוק כ' חשיב \"שלשה מקומות שהיו מעולים מכל שאר המקומות אשר באו לידם על ידי קניית כסף ואלו הן חברון והר גריזים והר עיבל והר המורי'\", ומביא בנוגע לחברון פסוק שונה מבמדרש — \"לאברהם למקנה וכתיב השדה אשר קנה אברהם\". ואכ\"מ."],["782","48","ראה אגרות קודש אדמו\"ר מהוריי\"ץ נ\"ע כרך א' ע' תפה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101003\" data-slug=\"likkutei-sichot\" data-id=\"1300101003\">לקו\"ש ח\"י בתחלתו ע' 3</a> ואילך."],["783","49","תהלים לז, כג. וראה \"היום יום\" יו\"ד תמוז. י\"ד מרחשון. ועוד."],["784","50","להעיר גם מהמבואר בכ\"מ שדברים שב­עולם שבהם יכולים לקיים מצוה הם נעלים יותר מדברים שבעולם שאא\"פ לקיים בהם מצוה, ובזה גופא — עילוי בהזמנת הדבר למצוה בפועל (גם קודם הקיום בפועל) — ראה בכ\"ז תו\"א מג\"א צ, סע\"ב ואילך. שערי אורה ד\"ה יביאו לבוש מלכות פ\"ה ואילך, ופע\"ג ובקיצורים לשם. וראה תו\"ש ע' 4. המשך תער\"ב פקע\"ט. סה\"מ תש\"ט ע' 148 בהערה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191370\" data-slug=\"likkutei-sichot\" data-id=\"1300191370\">לקו\"ש חי\"ט ע' 357</a> ואילך."],["785","51","שבת סז, א."],["786","52","זח\"ב כו, ריש ע\"ב. הקדמת תקו\"ז בתחלתה."]]],[1301670150,"איש ישראל ה\"ז הדיוט, שאינו תופס מקום לגבי איש ישראל, ולגבי כחו ועבודתו לעשות כאן א\"י.\nואופן עשייתו הוא כמו \"מלך\", אמר מלכא עקר טורא<sup data-n=\"787\">53</sup>, שגם כשנראה כאן טורא, יצר הרע שנדמה כהר<sup data-n=\"788\">54</sup>, הרי הוא עוקרו ממקומו ומכניסו לרשות הקדו­שה<sup data-n=\"789\">55</sup>.\nואח\"כ הוא הולך לקיים מצותו להמשיך קדושה בעניני העולם לעשות א\"י בפועל.\nח. ומכל זה הוראה ברורה גם בנוגע לארץ ישראל כפשוטה, שהרי היתרון דמקום השדה ומערת המכפלה שבחברון הוא בכך שהוא אחד משלשה מקומות שאין אומות העולם יכולין להונות את ישראל (כנ\"ל):\nאף שגם בנוגע לכל ארץ ישראל אין מקום לטענת גזילה, כמו שהאריך רש\"י בריש פירושו על התורה, \"כל הארץ של הקב\"ה היא, הוא בראה ונתנה לאשר ישר בעיניו, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו\", מ\"מ ה\"ז מענה לאומות העולם שטוענים לישראל \"לסטים אתם\", אבל<sup data-n=\"790\">56</sup> בג' מקומות אלו אין שם אפילו קס\"ד לטענה שיצטרכו לענות להם, מאחר שג' מקומות אלו באו לידם ע\"י תשלום כסף.\nוטעם הדבר מובן ע\"פ מ\"ש במפר­שים<sup data-n=\"791\">57</sup> שהיחוד בג' מקומות אלו הוא בזה שמקומות אלו מיוחדים בקדושתם תמיד, גם בזמן הגלות: מקום המקדש, דתמיד בקדושתו עומד כמו שארז\"ל ופסק ה­רמב\"ם<sup data-n=\"792\">58</sup> להלכה דקדושת המקדש מפני השכינה ושכינה אינה בטילה לעולם, \"לא זזה השכינה מתוך ההיכל. . אין השכינה זזה מכותל מערבי\"<sup data-n=\"793\">59</sup>. וכן מערת המכפלה מקום קבורת האבות שעל ידה עוברת התפלה דכל ישראל<sup data-n=\"794\">60</sup>, ומעין זה לגבי מקום קבורתו של יוסף<sup data-n=\"795\">61</sup>.\nועפ\"ז י\"ל, דמג' מקומות אלו גופא, הרי מקום מערת המכפלה מיוחד בזה, שנוסף ע\"ז שנקנה לאברהם לפני כיבוש הארץ, הי' זה המקום הראשון בארץ ישראל שנקנה לאברהם שקנהו עבור קבורת שרה, אמו של יצחק בלי כל שייכות לישמעאל, דשייכותה של שרה היא רק לעם ישראל<sup data-n=\"796\">62</sup>, ומאז הי' שם מקום קבורת אבות דבנ\"י אברהם ושרה יצחק ורבקה יעקב ולאה.\nועל ידי חברון ומערת המכפלה ניתן תוקף וחיזוק, תוקף דמלך, שארץ ישראל תשאר לבנ\"י גם ברגעים האחרונים דגלות, ובקרוב ממש נזכה לביאת משיח צדקנו, שאז תהי' כל ארץ ישראל ב­שלימותה, ירחיב ה\"א את גבולך, גם ארץ קיני קניזי וקדמוני<sup data-n=\"797\">63</sup>, שניתנו בברית בין הבתרים לאברהם אבינו, באופן ד­\"לזרעך<sup data-n=\"798\">64</sup> נתתי את הארץ הזאת מנהר מצרים עד הנהר הגדול נהר פרת את הקיני ואת הקניזי ואת הקדמוני\", ביחד עם ארץ ז' האומות, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות כ\"ף מ\"ח וש\"פ ח\"ש תשמ\"ו)</span>",[["787","53","ראה ב\"ב ג, ב."],["788","54","סוכה נב, א."],["789","55","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091376\" data-slug=\"likkutei-sichot\" data-id=\"1300091376\">לקו\"ש ח\"ט ע' 349</a> בשוה\"ג."],["790","56","ראה יפ\"ת השלם לב\"ר שם."],["791","57","נזר הקודש לב\"ר שם."],["792","58","הל' ביהב\"ח ספ\"ו."],["793","59","שמו\"ר פ\"ב, ב."],["794","60","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251098\" data-slug=\"likkutei-sichot\" data-id=\"1300251098\">לקו\"ש חכ\"ה ע' 98</a>. וש\"נ."],["795","61","ראה נזר הקודש שם."],["796","62","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151147\" data-slug=\"likkutei-sichot\" data-id=\"1300151147\">לקו\"ש חט\"ו ע' 147</a> ואילך."],["797","63","פ' ראה יב, כ. ספרי שם. שופטים יט, ח. רש\"י שם."],["798","64","לך טו, יח­יט."]]],[1301670151,"<h3>שיחה ב</h3>\nא. \"ואברהם זקן בא בימים\"<sup data-n=\"799\">1</sup>. וכתב הכלי יקר, \"הרבה מפרשים תמהו והלא כבר נאמר [לעיל בפ' וירא<sup data-n=\"800\">2</sup>] ואברהם ושרה זקנים באים בימים והי' כמו ל\"ז<sup data-n=\"801\">3</sup> שנים בין שני זמנים אלו\" — ומהו שנאמר כאן \"ואברהם זקן בא בימים\", שרק עתה נזדקן כו'?\nוהנה תמי' זו היא (גם) לפי פשוטו של מקרא, וצ\"ע למה לא מצינו יישוב עלי' בפירוש רש\"י על התורה [וכמשנ\"ת כמ\"פ, שבפירושו על התורה מיישב רש\"י כל דבר הקשה בפשוטו של מקרא, ובמקום שלא מצא רש\"י פירוש (מספיק) ליישב המקראות ע\"פ פשוטם, כ' רש\"י<sup data-n=\"802\">4</sup> \"איני יו­דע\" וכיו\"ב].\nוהנה במדרש<sup data-n=\"803\">5</sup> איתא \"כבר כתיב ואבר­הם ושרה זקנים, מה ת\"ל ואברהם זקן, אלא שהחזירו הקב\"ה לימי נערותיו צריך לכתוב פעם שני' ואברהם זקן\". ולכאורה אפשר לומר שתירוץ זה יש לו מקום גם לפי פשוטו של מקרא<sup data-n=\"804\">6</sup>, וכמפורש ב­פרש\"י<sup data-n=\"805\">7</sup> בנוגע לשרה שהקב\"ה בירכה \"ש­חזרה לנערותה\" [וכפשטות הכתובים דפ' וירא, דאע\"פ ש\"(ואברהם ושרה זקנים גו') חדל להיות לשרה אורח גו' אחרי בלותי היתה לי עדנה ואדוני זקן\"<sup data-n=\"806\">8</sup>, מ\"מ נולד לשרה בן ו\"היניקה בנים שרה\"<sup data-n=\"807\">9</sup>], ומזה מובן, לכאורה, גם בנוגע לאברהם, דאע\"פ שמלכתחילה \"ואברהם ושרה זקנים באים בימים\" (וכדברי שרה \"אחרי בלותי גו' ואדוני זקן\", שגם אצל אברהם כבר עבר הזמן שיוכל להוליד בנים<sup data-n=\"808\">10</sup>), מ\"מ חזר לנערותו. ולכן הוצרך הכתוב להודיע, שאחרי שעברו (כמו) ל\"ז<sup data-n=\"801\">3</sup> שנה מלידת יצחק, שוב \"ואברהם זקן בא בימים\".\nאבל, אי אפשר לתרץ כן בדרך הפשט, כי מצינו אח\"כ (בסוף הפרשה<sup data-n=\"810\">11</sup>) שאברהם נשא אשה אחרת והוליד ממנה כמה בנים (בני קטורה)<sup data-n=\"811\">12</sup>.\nב. עוד תירוץ מצינו במדרש<sup data-n=\"803\">5</sup>, \"כאן [בפ' וירא] זקנה שיש בה לחלוחית ולהלן [בפרשתנו] בזקנה שאין בה לחלוחית\", היינו, שבפ' וירא מדובר בתחילת ימי ה­זקנה כשעדיין יש באדם \"לחלוחית\", משא\"כ \"ואברהם זקן\" בפרשתנו פירושו זקנה ש\"אין בו לחלוחית\"<sup data-n=\"813\">13</sup>.",[["799","1","פרשתנו כד, א."],["800","2","יח, יא."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["802","4","ראה לדוגמא פרש\"י תולדות כח, ה. ועוד (נסמנו ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו\"ש ח\"ה ע' 1</a> בהערה)."],["803","5","ב\"ר וירא שם (פמ\"ח, טז)."],["804","6","וצע\"ק בכלי יקר שם, שכ' שפירוש זה \"אין לו סמך מן המקרא\"."],["805","7","לך לך יז, טז."],["806","8","יח, יא­יב וכפרש\"י שם."],["807","9","וירא כא, ז. וראה רש\"י שם."],["808","10","ראה גם לקמן ע' 94. — וב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201080\" data-slug=\"likkutei-sichot\" data-id=\"1300201080\">לקו\"ש ח\"כ ע' 80</a> ואילך נת' באו\"א, שאצל אברהם לא היתה מלכת­חילה תשות כח בנוגע ללידה. ע\"ש. ואכ\"מ."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["810","11","כה, א ואילך."],["811","12","וראה לקמן שם ואילך, שזה הי' נס נוסף, ששוב חזר לנערותו כו'. אבל לכאורה אין זה פשוטו ממש. — וראה לקו\"ש ח\"כ הנ\"ל. ואכ\"מ."],["803","5","ב\"ר וירא שם (פמ\"ח, טז)."],["813","13","ולפירוש זה, תוכן הזקנה כאן אינו בשייכות לענין הלידה (ראה נזר הקודש (השלם) לב\"ר וירא שם)."]]],[1301670152,"אבל לכאורה אין לחילוק זה שייכות לדרך הפשט, שהרי בשני המקומות נאמ­רה אותה הלשון \"זקן בא בימים\" (\"זקנים באים בימים\"), ולמה לא נרמז בלשון הכתוב חילוק זה בין שני שלבי זקנה (כמו \"זקן מאד\" וכיו\"ב)?\nברמב\"ן<sup data-n=\"814\">14</sup> מפרש, שיש חילוק בין \"ב­אים בימים\" דפ' וירא ו\"בא בימים\" דפר­שתנו, כי \"באים בימים\" הוא לשון הווה, \"כמו הבאים<sup data-n=\"815\">15</sup> בשערים האלה\", ולכן פירושו ש\"מתחילים בימי הזקנה\" (כש­עדיין \"יש בה לחלוחית\"), שנכנסים ובאים עתה לימי זקנה; משא\"כ \"בא בימים\" הוא לשון עבר, \"כמו בא<sup data-n=\"816\">16</sup> אחיך במרמה\", ופירושו \"שכבר בא בימים\".\nאבל קשה לומר שגם רש\"י ס\"ל חילוק זה בפירוש כתובים אלה, דא\"כ הו\"ל לכ­תוב כן בפירוש, וע\"ד שמצינו להלן ב­פרש\"י (בפ' ויצא<sup data-n=\"817\">17</sup>), שמפרש החילוק בין ב' הפעמים שנאמר שרחל \"באה\", \"הרא­שון [ש\"הטעם באל\"ף\"] לשון עושה וה­שני<sup data-n=\"818\">18</sup> [ש\"הטעם למעלה בבי\"ת\"] לשון עשתה\"<sup data-n=\"819\">19</sup>.\nג. ויובן זה בהקדים פירוש כפל ה­לשון \"זקנים באים בימים\" (וכן כאן \"זקן בא בימים\") — דלכאורה יש להבין, מהי ההוספה בלשון \"בא(ים) בימים\" על \"זקן\"?\nוגם בזו — לא מצינו שרש\"י בפירושו על התורה יפרש לשון זו. ועכצ\"ל, דס\"ל שהפירוש של \"בא בימים\" הוא פשוט כדי כך עד שאין צורך לפרשו.\nוהנה לפי כמה פשטנים, הלשון \"בא בימים\" מורה על זקנה מופלגת, וכפירוש הראב\"ע<sup data-n=\"820\">20</sup> \"באים בימים\" — \"הגיעו לימים רבים\". אבל צ\"ע, איך נרמז בלשון \"בא בימים\" שהכוונה ל\"ימים רבים\" עוד יותר מסתם \"זקנה\".\n[ברמב\"ן<sup data-n=\"821\">21</sup> כ': \"האדם בימי בחרותיו יקרא עומד בימים, ויקראו ימיו כי הם שלו. . אבל כאשר יזקין ויחי' ימים רבים מרוב בני האדם בדורו יקרא בא בימים מפני שהוא כבא בארץ אחרת כו'\". אבל לכאורה אין זו פשטות משמעות הביטוי \"בא בימים\"<sup data-n=\"822\">22</sup>, ועד כדי לומר שלא הוזקק רש\"י לפרשו בהדיא וסומך על הלומד מקרא (הכולל גם \"בן חמש\"<sup data-n=\"823\">23</sup>) שיבין זה מעצמו!].\nועוד זאת: הגיל של בן מאה שנה לאיש (שני אברהם) ובן צ' לאשה (שני שרה) לא נחשב, לכאורה, לזקנה מופלגת בתקופה ההיא. ויתר על כן: הלשון \"זקן בא בימים\" מצינו גם אצל דוד (בהפטרת פרשתנו<sup data-n=\"824\">24</sup>)",[["814","14","פרשתנו כד, א. וראה גם כלי יקר שם."],["815","15","ירמי' ז, ב."],["816","16","תולדות כז, לה."],["817","17","כט, ו. וכן בפרש\"י לעיל לך (טו, יז). ע\"ש. רש\"י ויגש (מו, כו — הובא ביפה תואר (השלם) לב\"ר שם)."],["818","18","ויצא שם, ט."],["819","19","כלומר: אע\"פ שגם בנדו\"ד, \"הטעם\" ב­תיבת \"באים\" (בכתוב \"ואברהם ושרה זקנים באים בימים\") הוא \"באלף\" (לשון הווה) — מ\"מ, את\"ל שרש\"י ס\"ל שזהו החילוק בין שני הכתובים, הו\"ל לפרש כן להדיא (כבמקומות שבהערה 17). ומדלא פירש כן משמע דס\"ל שגם \"ואברהם זקן בא בימים\" הוא ל' הווה (ולא עבר). וראה גם עקידה פרשתנו, שהקשה על פי' הרמב\"ן."],["820","20","וירא שם (יח, יא). — וראה גם רד\"ק שם: \"מנהג הכתוב לאמר הלשון הזו על האדם שגברה וכבדה עליו הזקנה שהוא בא בימים הידועים שהם דרך כל הארץ\", ועד\"ז פי' בפרשתנו כאן \"בימים שהם השלמת ימי אדם בעולם\"."],["821","21","וירא שם."],["822","22","וכן פי' הרד\"ק הנ\"ל (הערה 20) \"בימים הידועים\", \"השלמת ימי אדם כו'\" — לא מונח בפשטות הל' \"בא בימים\". ועכ\"פ, אם רש\"י ס\"ל כן הו\"ל לפרשו להדיא."],["823","23","כפסק המשנה אבות ספ\"ה."],["824","24","מ\"א בתחלתו."]]],[1301670153,"בהיותו קרוב לבן שבעים שנה<sup data-n=\"825\">25</sup>, שגיל זה בודאי אינו נחשב<sup data-n=\"826\">26</sup> לזקנה מופלגת<sup data-n=\"827\">27</sup>.\nד. ויש לומר הביאור בזה:\nהפירוש ד\"בא בימים\" הוא — כפשטות התיבות — שהגיע ובא (נכנס) בתוך הימים, כמו בא בבית וכיו\"ב. זאת אומרת, שאין זה תיאור מספר שנות האדם (אם רב או מעט), אלא אופן חיי האדם בימים אלו.\nכלומר: הימים שעברו על האדם וה­מאורעות שבהם, אינם כמו דבר העובר וחולף שלא נשאר ממנו רושם, כי אם הם באופן שהאדם \"הכניס\" את מהותו ונפשו בתוך כל יום ויום ומאורעותיו והר­פתקאותיו, שאז כל יום ויום וכל מאורע ומאורע (הן דבר המשמח, והן הפכו ח\"ו) פועל ומשפיע עליו, עד שניכר בגלוי בתווי פניו כו'<sup data-n=\"828\">28</sup>.\n[וכפי שרואים במוחש, שאין כל בני אותו גיל דומים זל\"ז, ולפעמים א' מהם נראה יותר מבוגר מזולתו, כי ניכר עליו רושם המאורעות שעברו עליו, מכיון שכל מאורע כו' נגע לל בו].\nוזהו גם פירוש הלשון \"זקן בא בימים\" אצל דוד, אף שמספר שנות חייו הי' קרוב לשבעים שנה בלבד, כי ריבוי המאורעות שעברו עליו (כמו ריבוי המלחמות, עגמת נפש מבנו כו' וכיו\"ב), הותירו את רישומן עליו, באופן של \"בא בימים\".\nוזהו \"ואברהם ושרה זקנים באים ב­ימים\", שלא רק שהיו \"זקנים\" מפני מספר שנות חייהם, אלא עוד זאת, שימי חייהם לא חלפו ועברו מהם, אלא היו באופן של \"באים בימים\", כנ\"ל.\nה. עפ\"ז יש לבאר גם מ\"ש בפרשתנו עוד פעם \"ואברהם זקן בא בימים\" — דיש לומר, שעיקר החידוש אינו בתיבת \"זקן\" (כי גם לפנ\"ז הי' זקן, כנ\"ל), אלא בכך שהי' \"בא בימים\":\nמטבע הדברים, שככל שהאדם הולך ומתבגר, אין המאורעות מסביבו משפיעים עליו (כל כך) — אם מפני שנעשה מתון יותר (\"כל זמן שהם מזקינים דעתם מתיישבת\"<sup data-n=\"829\">29</sup>), או לפי שטבעו של זקן שכבר עבר הרבה בחייו, שאין הדברים שסביבו תופסים מקום אצלו.\nולכן, אף שכבר נאמר \"ואברהם ושרה זקנים באים בימים\", מצד ריבוי המאו­רעות שעברו עליהם עד הזמן ההוא, מ\"מ יש צורך להודיע ולחדש שגם לאחרי שעברו אצל אברהם עוד ל\"ז<sup data-n=\"801\">3</sup> שנה, הי' \"אברהם [לא רק] זקן [אלא גם] בא בימים\",",[["825","25","משא\"כ מ\"ש ביהושע (יהושע יג, א) \"זקן בא בימים\" — לאחרי ז' שני כיבוש — הי' לכה\"פ קרוב לתשעים שנה (ראה סדר הדורות ב\"א תמח. ועוד).\nולהעיר שגם אצל יהושע נכפל עוד הפעם הלשון \"זקן בא בימים\" (יהושע כג, א). ואכ\"מ."],["826","26","ראה גם יפה תואר (השלם) לב\"ר פרשתנו (שבהערה 28)."],["827","27","להעיר (ע\"ד ההלכה) מטור יו\"ד ר\"ס רמד \"שיבה שהוא מופלג בזקנה דהיינו בן שבעים\". אבל שם עיקר ההדגשה הוא על \"שיבה\" דקאי על בן שבעים (אבות ספ\"ה), וכמ\"ש בב\"י שם. וראה רמב\"ם הל' סנהדרין (פ\"ב ה\"ג), דמוכח שם, ד\"זקן מופלג בשנים\" הוא יותר מ\"בעלי שיבה\" (ראה לח\"מ שם. רמב\"ם שם ה\"ו). וראה גיטין (כח, א) \"כיון דאיפליג כו'\", וקאי על יותר מבן תשעים (ראה רש\"י שם). ואכ\"מ."],["828","28","בב\"ר פרשתנו (פנ\"ט, ו) \"יש לך אדם שהוא בזקנה ואינו בימים [שקפצה עליו זקנה], בימים ואינו בזקנה [שהזקנה אינה ניכרת עליו], אבל כאן זקנה כנגד ימים וימים כנגד זקנה\" (וראה במפרשים שם, המעלה שבזה). ולפ\"ז, \"זקן\" היינו תואר ופעולת הזקנה, ו\"בא בימים\" קאי על כמות הזמן (\"ימים\"). וכן פי' במצו\"ד ליהושע (יג, א).\nאבל פשטות הפירוש דתיבת \"זקן\" אינה תואר על פעולת הזקנה, אלא ריבוי כמות של שנים, כדמצינו בכמה קראי. ולאידך, בלשון \"בא בימים\" אינו מודגש כ\"כ ריבוי הימים."],["829","29","משנה קנים ספ\"ג."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."]]],[1301670154,"שגם המאורעות דל\"ז<sup data-n=\"801\">3</sup> שנים אלו השפיעו עליו והותירו רושמם בו, באופן של \"בא בימים\".\nואדרבה: יש לומר, שדוקא בימים אלו היו מאורעות חשובים ומכריעים בחיי אברהם עוד יותר מהמאורעות בשנות חייו הקודמים — לידת יצחק (ש\"ביצחק יקרא לך זרע\"<sup data-n=\"832\">30</sup>), עד לעקידת יצחק ופטירת שרה וכו'.\nו. על פי פירוש זה ב\"בא בימים\" (שימי האדם הם באופן ש\"נכנס\" בהם ופו­עלים עליו רושם כו') — יובן היטב פירוש הזהר<sup data-n=\"833\">31</sup> ב\"בא בימים\" — שכל ימי חייו היו שלמים בעבודת השם, שלא החסיר מלע­בוד את השם אפילו יום אחד מימי חייו.\nלפי הנ\"ל מובן, שפירוש הזהר אינו ע\"ד הרמז בלבד, אלא הוא מיוסד על הפירוש הפשוט ב\"בא בימים\", שלא הי' יום אצל אברהם שרק חלף ועבר, אלא אברהם בא ונכנס ב\"ימיו\", לעבוד את השם בכל יום ויום כפי שהי' נדרש בכל יום לפי ענינו.\nכלומר: הענין ד\"בא בימים\" לפי פשו­טו של מקרא (הנ\"ל), קאי על חייו הגש­מיים של אברהם, שמאורעות כל יום ויום השפיעו עליו וכו'; ואילו בזהר, פנימיות התורה, מודגש התוכן הפנימי של חיי אברהם, שהם חיי הנשמה ועבודת השם שלו, שהם חיי אברהם האמיתיים [ובלשון רבינו הזקן<sup data-n=\"834\">32</sup> \"שחיי הצדיק אינם חיים ב­שרים כי אם חיים רוחניים\"], ולכן מפרש, דזה שאברהם בא ונכנס בכל יום ויום (עד שהי' ניכר עליו הרושם של כל ימי חייו), היינו לפי שכל ימיו היו ממולאים בעבודת השם, באופן שכל יום ויום הי' יום \"חי\".\n(משיחת ש\"פ חיי שרה תשמ\"ח)\n{*} {*} {*}\nז. ע\"פ הנ\"ל בביאור דברי הזהר בפי­רוש \"בא בימים\", יש לבאר גם כן לשון הכתוב בתחילת פרשתנו \"ויהיו חיי שרה מאה שנה גו' שני חיי שרה\", דלכאורה יש לדייק: בדרך כלל, כשנאמר סכום שני חיי אדם בתורה, לשון הכתוב היא<sup data-n=\"835\">33</sup> \"ויהיו ימי. . \" או \"(ימי) שני חיי גו'\", וא\"כ גם כאן הול\"ל \"ויהיו ימי שרה\" או \"ויהיו שני שרה\" — ומהו הלשון \"ויהיו חיי שרה\"?\nויש לומר הביאור בזה:\nעיקר החידוש בכתוב זה הוא להודיע שכל ימי שרה היו ממולאים בעבודת השם בתכלית השלימות, בלשון המדרש<sup data-n=\"836\">34</sup> \"כ­שם שהן תמימים כך שנותם תמימים\", ועד (כפרש\"י<sup data-n=\"837\">35</sup>) ש\"כולן שוין לטובה\", שמדת ה\"טוב\" של כל שנותי' היתה באופן שווה.\nולכאורה הדברים תמוהים: כיצד אפשר לומר שכל קכ\"ז השנים של שרה היו \"שוין לטובה\"? הרי מובן, שאין ל­השוות את מעמדה ומצבה בהיותה באור כשדים, וכן בחרן, לגבי מעמדה ומצבה לאחרי שבאה \"אל הארץ אשר אראך\"<sup data-n=\"838\">36</sup>, ולאידך — בקכ\"ז שנה אלו נכלל גם הזמן שהיתה בבית פרעה וכן בבית אבימלך וכו'.",[["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["832","30","וירא כא, יב."],["833","31","ראה זהר פרשתנו קכט, א. זהר ויחי רכא, ב ואילך. רכד, א. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370351\" data-slug=\"torah-or\" data-id=\"3901370351\">תו\"א פרשתנו טז, א</a>. משפטים עט, ב. ועוד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201328\" data-slug=\"likkutei-sichot\" data-id=\"1300201328\">לקו\"ש ח\"ד ע' 1194</a>. ח\"כ ע' 315 ואילך. וש\"נ."],["834","32","תניא אגה\"ק ביאור לסי' ז\"ך בתחלתו (קמו, ב)."],["835","33","ראה לדוגמא בדורות שנמנו בס\"פ ברא­שית; נח ט, כט; ס\"פ נח; סוף פרשתנו (כה, ז. שם, יז). ועוד."],["836","34","ב\"ר ריש פרשתנו."],["837","35","ריש פרשתנו."],["838","36","ר\"פ לך לך."]]],[1301670155,"אך הביאור בזה — בפשטות<sup data-n=\"839\">37</sup>: \"חיי שרה\" פירושו — הענינים שבהם חייתה שרה, ו\"חיי שרה\" היו \"שוין לטובה\", ב­משך כל שנותי' [ע\"ד הנ\"ל מזהר בפירוש \"בא בימים\" שנאמר אצל אברהם, שכל יום ויום הי' שלם בעבודת ה'].\nדהנה מובן, שהמשמעות האמיתית ד­\"חיי שרה\" לא היו חיי הגוף שלה (אכילה ושינה וכיו\"ב) — דלא בענינים אלו \"חיי­תה\" שרה אמנו. ופשיטא, כאשר היתה ב­בית פרעה או בבית אבימלך, הרי הצד הבלתי­רצוי שבזה לא הי' חלק מ\"חיי שרה\" [שהרי אדרבה, היותה סגורה בבית פרעה ובית אבימלך גרם לה צער גדול].\nאלא \"חיי שרה\" הם החיים הרוחניים שלה, החל מג' המצוות המיוחדות לנשי ישראל, כמובא בפרש\"י פרשתנו<sup data-n=\"840\">38</sup> \"נר דלוק מערב שבת לערב שבת, וברכה מצוי' בעיסה, וענן קשור על האהל\" (כמבואר במפרשים<sup data-n=\"841\">39</sup> שהם כנגד ג' ה­מצוות דהדלקת נר שבת, חלה ונדה).\nוחיים אלו היו \"שוין לטובה\" כל רגע ורגע בהיותה עלי אדמות<sup data-n=\"842\">40</sup>.\nוזוהי ההדגשה \"ויהיו חיי שרה גו'\" — דאף שימי ושני שרה, כללו הרבה חילו­קים ושינויים במעמדה ומצבה, אבל \"חיי שרה\" היו באופן שוה במשך כל ימי חיי', \"כולן שוין לטובה\"<sup data-n=\"843\">41</sup>.\n<span data-k=\"q\">(משיחת ש\"פ חיי שרה תשמ\"ג)</span>",[["839","37","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201338\" data-slug=\"likkutei-sichot\" data-id=\"1300201338\">הביאור ע\"פ</a> פנימיות הענינים — ראה לקו\"ש ח\"ה ע' 352 ואילך. ח\"כ ע' 325 ואילך. ועוד."],["840","38","כד, סז."],["841","39","חזקוני, גו\"א ועוד שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151172\" data-slug=\"likkutei-sichot\" data-id=\"1300151172\">לקו\"ש חט\"ו ע' 172</a>. ועוד."],["842","40","גם בהיותה בבית פרעה כו'."],["843","41","ופירוש סיום הכתוב \"שני חיי שרה\" (שממנו נלמד \"כולן שוין לטובה\") — שבמשך כל שנותי', היו חיי' שוין לטובה."]]],[1301670156,"<h3>שיחה ג</h3>\nא. \"ויוסף אברהם ויקח אשה ושמה קטורה ותלד לו גו'\"<sup data-n=\"844\">1</sup>.\nוידועה התמי' בזה: בכמה כתובים קודמים מפורש, שלידת יצחק בהיות אברהם בן מאה היתה דבר נסי (לא רק בגלל גילה של שרה אלא גם) כיון ש­אברהם הי' בגיל שע\"פ טבע אינו יכול להוליד:\n\"ויפל<sup data-n=\"845\">2</sup> אברהם על פניו ויצחק ויאמר בלבו הלבן מאה שנה יולד (ואם שרה הבת תשעים שנה תלד)\"; \"ואברהם<sup data-n=\"846\">3</sup> ושרה זקנים באים בימים גו' ותצחק שרה בקרבה לאמר אחרי בלותי היתה לי עדנה ואדוני זקן\"; \"ותאמר מי מלל לאברהם גו' כי ילדתי בן לזקוניו\"<sup data-n=\"847\">4</sup>, ועד \"שהיו ליצני הדור אומרים מאבימלך נתעברה שרה\"<sup data-n=\"848\">5</sup>.\nע\"פ זה יש להבין מדוע כשנולדו לאברהם עוד ששה בנים, ארבעים שנה לאחרי לידת יצחק, כשהי' בן ק\"מ שנה<sup data-n=\"849\">6</sup>, לא נתפרש בכתוב שזהו דבר נסי ומופ­לא וכו'.\nוהנה הרמב\"ן<sup data-n=\"845\">2</sup> כתב אודות לידת יצחק שאין הפלא בבן ק' שיוליד<sup data-n=\"851\">7</sup>, ומביא ראי' מהנ\"ל — ש\"אחרי זה מ' שנה הוליד בנים רבים מקטורה\". אבל אין לפרש כן שיטת ודעת רש\"י, שהרי מ­פשטות הכתובים הנ\"ל לא משמע כן, ואם ס\"ל לרש\"י הכי הי' לו לפרשו, ויתרה מזה מפירושו גופא<sup data-n=\"845\">2</sup> משמע ל­היפך, שכתב \"אע\"פ שדורות הראשונים היו מולידין בני ת\"ק שנה בימי אברהם נתמעטו השנים כבר ובא תשות כח בעולם וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהם בני ס' ובני ע'\"<sup data-n=\"853\">8</sup>.\nואפילו את\"ל שאצל אברהם<sup data-n=\"854\">9</sup> לא הי­תה תשות כח עד היותו בן מאה<sup data-n=\"855\">10</sup> [או ש(לאחר זמן ד\"ואברהם<sup data-n=\"856\">11</sup> ושרה זקנים\") חזר לנערותו והוליד בהיותו בן מאה<sup data-n=\"857\">12</sup>], הרי לאחרי זה נאמר בפרשתנו (עוד פעם) \"ואברהם זקן בא בימים\"<sup data-n=\"858\">13</sup>, היינו",[["844","1","פרשתנו כה, א."],["845","2","לך יז, יז."],["846","3","וירא יח, יא­יב. וראה שם, יג."],["847","4","שם כא, ז."],["848","5","לשון רש\"י ר\"פ תולדות."],["849","6","ראה רש\"י פרשתנו (כד, סב) שבעת שחזר יצחק מהליכתו להביא את הגר לאברהם שישאנה פגש את רבקה כו', ויצחק נשא את רבקה בהיותו בן ארבעים שנה (תולדות כה, כ)."],["845","2","לך יז, יז."],["851","7","וראה גם רמב\"ן ויגש מו, טו."],["845","2","לך יז, יז."],["853","8","ראה גם ראב\"ע לך שם. אלא שממשיך \"וכ­אשר תסתכל ותרא כי דבר שרה נפלא מדבר אברהם\"."],["854","9","ראה בארוכה במפרשי רש\"י לך שם. ולדעת כמה (הרא\"ם ועוד) לא הי' שום נס בזה שאברהם הוליד. אבל ראה גו\"א ובאר בשדה שם (ועוד), שגם בזה שאברהם הוליד הי' נס, כדיוק לשון הכתובים הנ\"ל. וראה הערה הבאה."],["855","10","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201080\" data-slug=\"likkutei-sichot\" data-id=\"1300201080\">לקו\"ש ח\"כ ע' 80</a> ואילך. אבל גם בפרש\"י יש לפרש בכמה אופנים. ובפרט שברש\"י אין בירור גמור, ע\"ד שרש\"י עצמו ב­פשש\"מ מביא כמ\"פ ב' (ויותר) פירושים בכתוב.\nועוד, דאפילו את\"ל (כנ\"ל) דאצל אברהם לא הי' נס מאחר שלא היתה אצלו תשות כח מתחילה, הרי זה גופא הוא פלא וחסד — ראה פרש\"י לך שם."],["856","11","וירא יח, יא."],["857","12","ראה ב\"ר פנ\"ג, ט \"מלל. . מוליד למאה שנה. . יבשה ונעשה מלילות\". וראה ב\"ר שהובא בסמוך בפנים."],["858","13","כד, א. — וראה לעיל ע' 89 ואילך."]]],[1301670157,"שהי' אצלו זיקנה שנוסף לאח\"ז, וא\"כ הרי הולדת בני קטורה בהיותו בן ק\"מ היא דבר נסי.\nוכמובן מדברי המדרש<sup data-n=\"859\">14</sup> על הכתוב \"ואברהם זקן גו'\" — \"אמר ר' יוחנן כבר כתיב ואברהם ושרה זקנים מה ת\"ל ואב­רהם זקן אלא שהחזירו הקב\"ה לימי נערותיו צריך לכתוב פעם שני' ואברהם זקן, רב אמי אמר כאן זקנה שיש בה לחלוחית ולהלן בזקנה שאין בה לח­לוחית\"<sup data-n=\"860\">15</sup> — הרי שאפילו את\"ל שלידת יצחק היתה נס מצד אברהם (שזקנה ותשות כח השייכת להולדה לא שלטה עליו), מ\"מ צריך לנס בשביל הולדת הבנים מקטורה שהיתה לאחרי שכבר נאמר עוה\"פ \"ואברהם זקן בא בימים\"<sup data-n=\"861\">16</sup>.\nב. ויש לומר נקודת הביאור בזה:\nבסיפור לידת יצחק נאמר<sup data-n=\"862\">17</sup> \"ותאמר שרה צחוק עשה לי אלקים כל השומע יצחק לי\", ופרש\"י<sup data-n=\"863\">18</sup> \"הרבה עקרות נפק­דו עמה, הרבה חולים נתרפאו בו ביום, הרבה תפלות נענו עמה, ורב שחוק הי' בעולם\", הרי שהנס דלידת יצחק הי' באופן כזה שגרם ישועה והצלה בכל העולם, עד שהביא ששמחה ורב שחוק הי' בעולם.\nובזה יובן מ\"ש רש\"י שם עה\"פ<sup data-n=\"847\">4</sup> היניקה בנים שרה — \"מהו בנים לשון רבים, ביום המשתה הביאו השרות את בניהן עמהן והניקה אותם, שהיו אומרות לא ילדה שרה אלא אסופי הביאה מן השוק\"<sup data-n=\"865\">19</sup>, וכן בפרשת לך לך<sup data-n=\"866\">20</sup> פרש\"י \"ובהנקת שדים כשנצרכה לכך ביום מש­תה של יצחק שהיו מרננים עליהם שה­ביאו אסופי מן השוק ואומרים בננו הוא והביאה כל אחת בנה עמה ומניקתה לא הביאה והיא היניקה את כולם\".\nדלכאורה, אם טעם הדבר הי' רק כדי להוכיח ששרה ילדה את יצחק ואינו אסופי מן השוק, הי' מספיק שכולם יראו שמניקה את יצחק, או שתניק עוד כמה בנים, אבל למה הוצרכה להניק את \"כולם\"? אלא שהי' בזה ענין נוסף, שהנס דלידת יצחק גרם לכו\"כ עניני השפעה ועד ל\"רב שחוק. . בעולם\", ולכן בא זה לידי ביטוי גם בזה שהניקה בניהם של כל השרות.\nועפ\"ז י\"ל, שכשם שמצינו אצל שרה, שהנס דלידת יצחק גרם לעוד כמה נסים אצלה ובזכותה, ונסים שהביאו ישועה והצלה בעולם (\"הרבה עקרות נפקדו עמה. . נענו עמה\", ועד להניק בניהם של כל השרות) — עד\"ז הוא בנוגע לאברהם, שהנס דלידת יצחק גרם לעוד נסים אצלו, שנולדו לו עוד בנים בדרך פלא ונס (לאחרי ש\"אברהם זקן בא בימים\"), ובנים אלו אינם בני ישראל אלא מאומות העולם (ע\"ד הנ\"ל בשרה).\nג. אלא שטעמא בעי: מהו הטעם שהנס דלידת יצחק גרם לעוד נסים שיהי' \"שחוק. . בעולם\"?\nוגם יש להבין השינוי בזה בין אב­רהם לשרה:\nא) אצל שרה היתה פעולה זו בעולם",[["859","14","ב\"ר פמ\"ח, טז."],["860","15","ראה בארוכה מפרשי המדרש."],["861","16","וראה בארוכה נזר הקודש (השלם) לב\"ר שם (וראה גם באר בשדה לך שם). וראה פי' מהרז\"ו שם. ועוד."],["862","17","וירא כא, ו."],["863","18","והוא בב\"ר פנ\"ג, ח. וראה פסיקתא רבתי פ' מב (מג) — וה' פקד. פסיקתא דר\"כ פ' כב — שוש אשיש."],["847","4","שם כא, ז."],["865","19","מב\"מ פז, א. ב\"ר שם, ט. ובכ\"מ. וראה פדר\"א פנ\"ב. פסיקתא דר\"כ שם."],["866","20","יז, טז. ומסיים: בראשית רבה רמזו במקצת."]]],[1301670158,"תיכף ומיד, \"הרבה עקרות נפקדו בו ביום\", וכן זה שהניקה בנים שרה, ואילו אצל אברהם הי' זה משך זמן רב — ארבעים שנה — אחר לידת יצחק.\nב) אצל שרה בא זה כתוצאה ממילא מלידת יצחק, בלי פעולה מיוחדת מצד שרה, משא\"כ אצל אברהם הי' זה כענין בפ\"ע, הולדת בנים — אוה\"ע (מקטורה) באופן נסי.\nויש לומר, שבזה נרמז ענין עיקרי ויסודי בהשפעת בני ישראל באומות העולם.\nדהנה מצינו שקודם לידת יצחק הי' צ\"ל שינוי שמם של אברהם ושרה, כ­פרש\"י<sup data-n=\"867\">21</sup> \"אברם אין לו בן אבל אברהם יש לו בן, וכן שרי לא תלד אבל שרה תלד\". שהטעם הוא לפי ש\"אני קורא לכם שם אחר וישתנה המזל\". ביחד ע\"ז מסתבר לומר, שלידת יצחק שייכת ל­תוכן ב' השמות החדשים: \"אברהם\" ו\"שרה\".\nולכאורה תמוה: תוכן השמות \"אב­רהם\" ו\"שרה\" (ביחס ל\"אברם\" ו\"שרי\") מורה על השליטה על כל העולם — \"אב המון גוים נתתיך\"<sup data-n=\"868\">22</sup>, לא רק \"אברם\" — \"אב לארם\" אלא \"אב לכל העולם\"<sup data-n=\"868\">22</sup>, ו\"שרה\" פירושו (כפרש\"י<sup data-n=\"870\">23</sup>) \"[לא] שרי (דמשמע) לי ולא לאחרים כי שרה סתם שמה שתהא שרה על כל\"; ומהי ה­שייכות בין שינוי השמות האלה ללידת יצחק, שהוא התחלת עם ישראל, \"כי ביצחק יקרא לך זרע\"<sup data-n=\"871\">24</sup>?\nומשמע מזה, שענין עיקרי בלידת יצחק (ועם ישראל) הוא הפעולה (וה­שליטה) על אומות העולם.\nועפ\"ז יש לומר, שזהו תוכן ענין הנסים שבאו בהמשך ללידת יצחק שגר­מו שיהי' \"רב שחוק. . בעולם\", שעי\"ז הודגש ענין השררה שלהם על העולם כולו, שהם הגורמים שתהי' ישועה בעולם; ובזה גופא היו שני סוגים — הנסים השייכים לשרה והנסים דאברהם (הולדת בני קטורה) — בהתאם להחילוק בין ענינו של אברהם וענינה של שרה, כדלקמן.\nד. ויובן זה בהקדם דברי הרמב\"ם<sup data-n=\"872\">25</sup> אודות חיוב ז' מצות בני נח: \"צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח\", \"כל המקבל שבע מצות ונזהר לעשותן הרי זה מחסידי אומות העולם ויש לו חלק לעולם הבא והוא שיקבל אותן ויעשה אותן מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו כו' אבל אם עשאן מפני הכרע הדעת. . אינו מחסידי אומות העולם\".\nוצ\"ע, הרי \"משה רבינו לא הנחיל התורה והמצות אלא לישראל\"<sup data-n=\"873\">26</sup>, ומהי השייכות דב\"נ למ\"ת ולבנ\"י ועד שבנ\"י צריכים לכוף את כל באי העולם לקבל מצות שנצטוו בני נח, והם יעשו אותן מפני שצוה הקב\"ה כן בתורה?\nונתבאר בזה כמ\"פ<sup data-n=\"874\">27</sup> ע\"פ מחז\"ל<sup data-n=\"875\">28</sup> שכל הבריאה היא בשביל ישראל שנק' ראשית ובשביל התורה שנקראת ראשית,",[["867","21","לך טו, ה."],["868","22","שם יז, ה ובפרש\"י."],["868","22","שם יז, ה ובפרש\"י."],["870","23","שם יז, טו."],["871","24","וירא כא, יב."],["872","25","הל' מלכים פ\"ח ה\"י וי\"א."],["873","26","רמב\"ם שם ריש הלכה יו\"ד."],["874","27","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201140\" data-slug=\"likkutei-sichot\" data-id=\"1300201140\">לקו\"ש ח\"כ ע' 140</a> ואילך. וש\"נ."],["875","28","פרש\"י ר\"פ בראשית. וראה תנחומא בא­בער שם יו\"ד. אותיות דרע\"ק אות ב'."]]],[1301670159,"היינו שאין זה דבר נוסף על מציאות הבריאה, אלא זה קשור עם עצם מצי­אותה<sup data-n=\"876\">29</sup>. ולכן, לאחרי לידת עם ישראל ונתינת התורה, אי אפשר שיהי' איזה ציווי ה' לעולם מבלי אמצעות התורה וישראל — ולכן תלוי קיום שבע מצות ב\"נ בתורה ובישראל.\nויש לדייק ברמב\"ם הנ\"ל, אשר שני הפרטים הנ\"ל (א) \"צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח\", (ב) שצריך לעשות אותן \"מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו\" — כתבם הרמב\"ם בשתי הלכות נפרדות.\nולכאורה, מזה שלא הזכיר הרמב\"ם בהמשך להחיוב \"לכוף את כל באי העולם לקבל מצות שנצטוו\" שחיוב זה כולל שקבלת המצוות שלהם תהי' מפני שצוה בהן הקב\"ה בתורה, וכתב תנאי זה (\"והוא שיקבל כו'\") בהלכה בפני עצמה בהגדרת \"חסידי אומות העולם\", מובן, שדין זה (\"והוא שיקבל אותן. . מפני ש­צוה בהן הקב\"ה בתורה\") הוא דין בפ\"ע [וצ\"ע אם יש חיוב על בנ\"י לכוף את כל באי העולם שיהיו חסידי אוה\"ע].\nאבל מזה שהביא הרמב\"ם גם תנאי זה בהמשך לחיוב דישראל לכוף כו', מש­מע, שאף שאין זה חלק מהחיוב הא', מ\"מ, שלימות הקבלה של הבן נח (שתח­לתה באה ע\"י כפיית ישראל), שמקבל המצוות מחמת ציווי הקב\"ה בתורה, יש ג\"כ לה קשר עם בני ישראל<sup data-n=\"877\">30</sup>.\nואולי י\"ל, שיש ב' אופנים בפעולות בנ\"י על אוה\"ע: א) השפעה ע\"י כפי' (אם כפשוטה<sup data-n=\"878\">31</sup> או ע\"י כפיית דברים<sup data-n=\"879\">32</sup>) — לקבל מצות שנצטוו ב\"נ, ב) פעולה ב­עקיפין, שבהמשך לכפי' זו באים אוה\"ע לידי הכרה שצריכים לקבל המצוות \"מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו כו'\"<sup data-n=\"880\">33</sup>.\nה. ויש לומר, ששני אופנים אלו מרומזים גם בסיום ב' הפרקים האח­רונים<sup data-n=\"881\">34</sup> של ספר הרמב\"ם<sup data-n=\"882\">35</sup>, בסוף הל' מלכים (ומלחמותיהם<sup data-n=\"883\">36</sup>):",[["876","29","וראה גם פרש\"י שם א, לא (משבת פח, א. ע\"ז ג, א)."],["877","30","ראה בארוכה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261132\" data-slug=\"likkutei-sichot\" data-id=\"1300261132\">לקו\"ש חכ\"ו ע' 132</a> ואילך."],["878","31","כשיד ישראל תקיפה."],["879","32","תוי\"ט אבות פ\"ג מי\"ד. וראה בארוכה לקו\"ש שם."],["880","33","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380323\" data-slug=\"likkutei-torah\" data-id=\"4001380323\">וכן ישנם ב</a>' אופנים אלה בפעולת בנ\"י על אוה\"ע במשך הדורות: א) ע\"י מלחמה לכבוש ארצם, שאז דינם ש\"יהיו לך למס ועבדוך\" (שופטים כ, יא), שיקבלו עליהם שבע מצות שנצטוו בני נח והרי הם למס (רמב\"ם הל' מלכים רפ\"ו), ב) כמו שהי' בימי שלמה ד\"וישב שלמה על כסא ה'\" (דה\"א כט, כג), ולא הוצרך למלחמה אלא מלכת שבא הביאה כו' ל­שלמה (מ\"א י, א ואילך. דה\"ב ט, א ואילך) [ובסגנון תורת החסידות, בירור בדרך מלחמה או בירור ב­דרך מנוחה — ראה לקו\"ת במדבר ג, ד ואילך. וראה סה\"מ תרנ\"ט ע' קסב ואילך. סה\"מ תש\"ד ע' 106 ואילך. ועוד]."],["881","34","ובהכותרת לפרקים אלו פרק יא וי\"ב בד­פוס וינציאה (רפד. שי) הוא \"הלכות מלכים ומל­חמות ומלך המשיח\"."],["882","35","בשבוע זה<sup data-n=\"e28\">*</sup> ביום כ\"ד מרחשון הוא סיום המחזור הששי של לימוד הרמב\"ם ג\"פ ליום (וכן סיום המחזור השני של לימוד הרמב\"ם פרק אחד ליום), וביום כ\"ה מר­חשון היא התחלת לימוד הרמב\"ם מחדש — מחזור השביעי (דג\"פ ליום), וכל השביעין חביבין (ומחזור השלישי — דבתלתא זימני הוי חזקה — דפרק א' ליום)."],["883","36","זהו השם המלא כבהקדמת הרמב\"ם (ב\"מנין המצות על סדר הלכות הרמב\"ם\") ובהכותרת בספר שופטים והל' מלכים."],["e28","*","בשנת תש\"נ — כשי\"ל הליקוט בפעם הא'. המו\"ל."]]],[1301670160,"בסוף פרק יא מסיים הרמב\"ם \"וקבץ נדחי ישראל. . ויתקן את העולם כולו לעבוד את ה' ביחד שנאמר<sup data-n=\"884\">37</sup> כי אז אה­פוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד\", ובסוף פרק יב מסיים \"ובאותו הזמן לא יהי' שם לא רעב כו' שהטובה תהי' מושפעת הרבה כו' ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר<sup data-n=\"885\">38</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\".\nכלומר: בסוף פרק יא מדובר אודות פעולת משיח ובנ\"י באוה\"ע, \"ויתקן<sup data-n=\"886\">39</sup> את העולם כולו כו'\", ואילו בסוף פי\"ב מד­בר אודות הנפעל באוה\"ע בדרך ממילא, דפשטות הלשון \"ולא יהי' עסק כל ה­עולם אלא לדעת את ה' בלבד\" (שכוונתו לכללות המין האנושי, גם אוה\"ע<sup data-n=\"887\">40</sup>) אינו באופן שבנ\"י יתעסקו עמהם. אבל מ\"מ ה\"ז שייך לבנ\"י, היינו שזהו תוצאה מע­בודת בנ\"י, וכדמוכח מזה שכולל באותה הלכה הן מעלת ידיעת ה' דבנ\"י והן זה שעסק כל העולם כולו יהי' לדעת את ה', והיינו שזה ש\"לא יהי' עסק כל העו­לם אלא לדעת את ה' בלבד\" יהי' קשור ותוצאה ממצב בנ\"י באותו הזמן.\nובזה יובן הדיוק בדברי הרמב\"ם ב­הלכה שלפנ\"ז<sup data-n=\"888\">41</sup> \"לא נתאוו החכמים וה­נביאים ימות המשיח לא כדי שישלטו על כל העולם ולא כדי שירדו בעכו\"ם ולא כדי שינשאו אותם העמים ולא כדי לאכול ולשתות ולשמוח, אלא כדי שיהיו פנויין בתורה וחכמתה\". דלכאורה תמוה, איך יעלה על הדעת לפרש ש\"נתאוו החכמים והנביאים ימות המשיח. . כדי שישלטו על כל העולם. . ירדו בעכו\"ם. . כדי שינשאו אותם העמים\", והרי אפילו בנוגע לחכמי אוה\"ע מצינו שעיקר עיסקם ומשאת נפשם הוא במושכלות<sup data-n=\"889\">42</sup> ואין להם תשוקה לשלוט ולרדות, וכ\"ש וק\"ו שכ\"ה בנוגע לחכמי ונביאי ישראל?\nאלא כוונת הרמב\"ם היא, דסלקא דעתך אמינא שתכלית המעלה שאלי' נתאוו החכמים וכו' היא לתקן את ה­עולם, היינו ללמד את העולם דעת את הוי' באופן של פעולה והשפעה (כמ\"ש בפרק יא), שזהו ענין של שליטה ורדי' אמיתית (ברוחניות). וקמ\"ל הרמב\"ם כאן שזה אינו שלימות הענין, ולא בשביל זה נתאוו החכמים והנביאים לימות המשיח, אלא כדי שיהיו פנויין בתורה וחכמתה ויהיו חכמים גדולים ויודעים דברים ה­סתומים.\nאבל אעפ\"כ ממשיך, כנ\"ל, שגם דרגא נעלית זו דבנ\"י פועלת בעולם, שבדרך ממילא יהי' מצב כל העולם באופן נעלה ביותר, ש\"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד כו' שנאמר כי מלאה הארץ דעה את ה' כמים לים מכסים\".\nו. ע\"פ כל הנ\"ל יובן גם תוכן הענין שקודם לידת יצחק הי' צ\"ל שינוי השם דאברהם ושרה, \"אב המון גוים\" ו\"שרה על כל\" — כי בראשית יצירת עם ישראל בהולדת יצחק ע\"י אברהם ושרה הי' צ\"ל מודגש שמציאותם של ישראל (אינה ענין ופרט בהבריאה, אלא) היא עיקר ומטרת כללות הבריאה כולה.\nוזהו גם הטעם שלידתו של יצחק ב­",[["884","37","צפני' ג, ט (ושם: לעבדו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231103\" data-slug=\"likkutei-sichot\" data-id=\"1300231103\">לקו\"ש חכ\"ג ע' 103</a> בהערה)."],["885","38","ישעי' יא, ט."],["886","39","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251127\" data-slug=\"likkutei-sichot\" data-id=\"1300251127\">לקו\"ש חכ\"ה ע' 127</a> הערה 47."],["887","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271260\" data-slug=\"likkutei-sichot\" data-id=\"1300271260\">לקו\"ש חכ\"ז ע' 246</a> ואילך."],["888","41","בפי\"ב ה\"ד."],["889","42","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370091\" data-slug=\"torah-or\" data-id=\"3901370091\">תו\"א תולדות יט, רע\"ג</a>."]]],[1301670161,"דרך נס היתה באופן כזה שפעל באוה\"ע כנ\"ל, \"הרבה עקרות נפקדו עמה הרבה חולים נתרפאו בו ביום הרבה תפלות נענו עמה ורב שחוק הי' בעולם\", ותוס' השפעה שבשרה באופן ד\"היניקה בנים שרה\", ועד\"ז באברהם, שהפלא והחסד דאברהם בהולדת יצחק, פעל גם ש­הוליד עוד (ששה) בנים מקטורה — כי כדי שבנ\"י יוכלו לפעול על אוה\"ע, היתה פעולה מיוחדת ע\"י הקב\"ה שגם אוה\"ע ירגישו דבר זה גופא, שעיקר מציאותו של העולם, כולל מציאותם דב\"נ, הוא ישראל.\n[וע\"ד שמצינו בנוגע לתורה — ש­ארז\"ל<sup data-n=\"890\">43</sup> \"שכשניתנה תורה לישראל הי' קולו הולך מסוף העולם ועד סופו וכל מלכי עובדי כוכבים אחזתן רעדה ב­היכליהן כו' נתקבצו כולם אצל בלעם הרשע ואמרו לו מה קול ההמון אשר שמענו שמא מבול בא לעולם כו' א\"ל חמדה טובה יש לו בבית גנזיו כו' וביקש ליתנה לבניו שנאמר<sup data-n=\"891\">44</sup> ה' עוז לעמו יתן מיד פתחו כולם ואמרו<sup data-n=\"891\">44</sup> ה' יברך את עמו בשלום\"]<sup data-n=\"893\">45</sup>.\nועפ\"ז מתורצת בפשטות הקושיא: ידוע דקוב\"ה לא עביד ניסא למגנא, וזה מובן בפשטות, דכיון שהקב\"ה קבע את הבריאה באופן מסודר וטבעי, \"לא יש­בותו\"<sup data-n=\"894\">46</sup>, לא ישנה את סדרי הבריאה אלא לצורך מיוחד<sup data-n=\"895\">47</sup>.\nוא\"כ תמוה, מהו הצורך וההכרח שהנס דלידת יצחק יביא ויגרום לעוד נסים — \"היניקה בנים שרה\" וכו', כנ\"ל שייעשה נס גדול כזה, שהרבה עקרות נפקדו כו', היפך טבע הבריאה?\nאלא שלא הי' בזה נס נוסף<sup data-n=\"896\">48</sup>, כי אם המשך ותוצאה מכללות הנס של לידת יצחק, כי לידת יצחק לא היתה נס פרטי, רק לאברהם ושרה, אלא נס כללי מ­לכתחילה, כדי שתהי' לידת יצחק נעשו אברהם ושרה \"אב לכל העולם\" ו\"שרה על כל\" — ובדרך ממילא כשארע הנס נפעל ונמשך ב\"כל העולם\" וב\"כל\", ונשתנו סדרי בראשית (כולל אוה\"ע).\nז. והנה בפעולת הנס דלידת יצחק על אוה\"ע גופא, היו שני פרטים (מצד אברהם ומצד שרה, כנ\"ל) — שיש לומר, ששני ענינים אלו הם השרש לשני ה­אופנים הנ\"ל בפעולת ישראל על אוה\"ע — ובהתאם להחילוק בתוכן עבודת אב­רהם ושרה, המודגש גם בשמם החדש שניתן להם לפני הולדת יצחק:\nאברהם ע\"ש \"אב המון גוים\", \"אב לכל העולם\", מורה על שייכות ל\"המון גוים\", \"כל העולם\", ולכן גם ההשפעה הנסית שנעשתה על ידו ב\"המון גוים\" היתה ע\"י פעולה מיוחדת מצד אברהם (להוסיף בעולם) — \"ויוסף אברהם ויקח אשה גו' ותלד לו גו'\" (ומטעם זה באה (לא בקירוב זמן להולדת יצחק אלא) לאחר זמן, כי בזה מודגש שבאה בדרך פעולה חדשה).\nמשא\"כ שרה שהיא \"שרה על כל\", ה\"ז גדר של שררה ומלכות, שהמלך הוא",[["890","43","זבחים קטז, סע\"א. מכילתא ר\"פ יתרו. ובכ\"מ."],["891","44","תהלים כט, יא."],["891","44","תהלים כט, יא."],["893","45","וביותר מודגש ע\"פ מרז\"ל (ע\"ז ב, ב. וראה ספרי ורש\"י ברכה לג, ב) שהקב\"ה החזיר את התורה על כל אומה ולשון כו'. וראה פנים יפות ברכה שם. אוה\"ת עה\"פ. ועוד."],["894","46","נח ח, כב."],["895","47","ראה דרשות הר\"ן דרוש ח' הקדמה הא'. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061049\" data-slug=\"likkutei-sichot\" data-id=\"1300061049\">לקו\"ש ח\"ו ע' 49</a> הערה 16. וש\"נ."],["896","48","להעיר שבב\"מ (וראה גם שאר המקומות) שבהערה 19, מדגיש \"ונעשה נס בשרה אמנו ונפתחו דדי' כשני מעיינות והניקה את כולן\". משא\"כ בפרש\"י עה\"ת שאינו מדגיש שהי' בזה (עוד) \"נס\"."]]],[1301670162,"מובדל מעמו, ולכן פעולת שרה על אוה\"ע שבאה יחד עם לידת יצחק היתה באופן של בדרך ממילא, ריבוי ברכות באוה\"ע.\nושלימות ענין זה תהי' בסוף זמן הגלות בביאת משיח צדקנו, בקיום היעוד<sup data-n=\"897\">49</sup> \"והי' באחרית הימים נכון יהי' הר בית ה' בראש ההרים גו' ונהרו אליו כל הגוים והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב ויורנו מדרכיו ונלכה באורחותיו גו'\"<sup data-n=\"898\">50</sup> — שמצד זה שהגילוי לבנ\"י יהי' בתכלית השלימות ה\"ז ישפיע בדרך ממילא על גוים ועמים רבים<sup data-n=\"899\">51</sup>, עד להמצב ד\"מלאה הארץ דעה את ה' כמים לים מכסים\".\n<span data-k=\"q\">(משיחות ש\"פ חיי שרה וש\"פ תולדות תשמ\"ה; י\"ט כסלו תשמ\"ג)</span>",[["897","49","ישעי' ב, ב ואילך."],["898","50","ראה פרש\"י ישעי' שם, ה."],["899","51","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא ספל\"ו</a>, \"שאז יזדכך גשמיות הגוף והעולם ויוכלו לקבל גילוי אור ה' שיאיר לישראל כו' ומיתרון ההארה לישראל יגי' חשך האומות גם כן כדכתיב (ישעי' ס, ג) והלכו גוים לאורך וגו' וכתיב (שם ב, ה) בית יעקב וכו'\". ואף שפשטות תוכן הלשון הוא שהגהת חושך האומות היא מיתרון ההארה לישראל, והיינו שבא בדרך ממילא, אולי י\"ל שמרמז בזה לב' האופנים הנ\"ל, שלכן מדייק להביא כמה פסוקים, ומודגש בהלשון שמביא בסופו (מתפלת עמידה דר\"ה) \"והופע בהדר גאון עוזך על כל יושבי תבל\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231170\" data-slug=\"likkutei-sichot\" data-id=\"1300231170\">לקו\"ש חכ\"ג ע' 170</a> ואילך."]]],[1301670163,"<h3>שיחה א</h3>\nא. כ' החיד\"א בס' מדבר קדמות<sup data-n=\"900\">1</sup> (בשם ר' יהודה החסיד) \"אבות העולם אברהם יצחק ויעקב ראו זה את זה וט\"ו שנים<sup data-n=\"901\">2</sup> למדו התורה [ביחד<sup data-n=\"902\">3</sup>] בכל יום ובכל לילה ט\"ו שעות, ובן<sup data-n=\"903\">4</sup> ט\"ו לתלמוד\" (ומונה כמה ענינים שבמספר ט\"ו).\nומבאר החיד\"א שם החשבון של \"ט\"ו שעות\" (דוקא), כי \"ט' שעות לישן ו­לאכול ולעשות צרכיו וט\"ו לתורה ו­תפלה\", ורמז לזה — \"כל הנשמה תהלל י\"ה<sup data-n=\"904\">5</sup>, שילמוד תורה ויתפלל. . תהלל י\"ה בי\"ה שעות\".\nוהנה בס' חסידים<sup data-n=\"905\">6</sup> איתא: \"ולמה אהב הקב\"ה את האבות מפני שכל היום וכל הלילה לא הי' לבם פונה מלהרהר אחר חפצי שמים. . וייקץ יעקב משנתו<sup data-n=\"906\">7</sup> ו­אמרו חז\"ל<sup data-n=\"907\">8</sup> ויקץ יעקב ממשנתו [דאפילו בשעת השינה הי' עוסק ושונה בתורה<sup data-n=\"908\">9</sup>], כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר. . כי היו כל כ\"ד שעות בסדר אחד שלא הי' להם פנאי מחפצי שמים אפילו בחלום\".\nומבאר החיד\"א בפירושו לספר חסי­דים שם, דלפי זה אי אפשר לומר דהא דנקט ר\"י החסיד ש\"למדו התורה. . (רק) ט\"ו שעות\" הוא לפי שבשאר ט' השעות היו עוסקים בצרכי הגוף (כמ\"ש במדבר קדמות שם), שהרי \"רבינו בעצמו כתב דכל כ\"ד שעות אפילו בחלום היו ב­חפצי שמים\", אלא \"ר\"ל כי ט\"ו שעות היו לומדים תורה וט' שעות מכוונים לבם למקום לחשוב ביראתו ורוממותו ואהבתו ודבוקו\" [היינו העסק בתפלה, וכמחז\"ל<sup data-n=\"909\">10</sup> דחסידים הראשונים היו עוס­קים בתפלה וכוונתה ט' שעות ביום].\nויש להוסיף, דפירוש זה (דמספר \"ט\"ו שעות\" קאי רק על לימוד התורה) מוכרח לכאורה בדברי ר\"י החסיד גופא (ש­הביא החיד\"א), שכ' \"וט\"ו שנים למדו התורה. . ט\"ו שעות ובן ט\"ו לתלמוד\", שמזה משמע, דאין שעות עבודת התפלה בכלל חשבון זה<sup data-n=\"910\">11</sup>.\nוצריך ביאור:\nמזה שהאבות \"ראו זה את זה\" רק ט\"ו שנים, כמ\"ש ר\"י החסיד ד\"ט\"ו שנים למדו כו' ט\"ו שעות\" [כי לידת יצחק היתה בהיות אברהם אבינו בן מאה שנה<sup data-n=\"911\">12</sup>, ויעקב נולד כשיצחק הי' בן",[["900","1","בתחלתו (מ\"קונטרס ישן כתיבת יד על קלף מתלמידי רבינו יהודה החסיד\"). וראה הנסמן בהערה הבאה."],["901","2","השנים שהיו האבות יחד ו\"ראו זה את זה\" (כדלקמן בפנים). ואולי יש כאן טה\"ד וצ\"ל \"ראו זה את זה ט\"ו שנים ולמדו. . \". — וראה גם מ\"ש החיד\"א בחומת אנך ס\"פ נשא ומגילת רות (אות יד). פני דוד פ' נח (אות ו). יוסף תהלות לתהלים מזמור קכ. ועוד."],["902","3","בחומת אנך רות שם \"ועבדו את ה' במיטב תלתא כחדא\"."],["903","4","אבות ספ\"ה."],["904","5","תהלים קנ בסופו."],["905","6","סי' קסה."],["906","7","ויצא כח, טז."],["907","8","ב\"ר פס\"ט, ז."],["908","9","ראה יפ\"ת השלם לב\"ר שם. עץ יוסף שם."],["909","10","ברכות לב, ב."],["910","11","ולהעיר די\"ה הם כנגד חו\"ב, מוחין (<a class=\"ft-cite\" href=\"#/read/tanya/3401310075\" data-slug=\"tanya\" data-id=\"3401310075\">תניא אגה\"ת פ\"ד (צד, ב</a>). לקו\"ת ר\"פ ראה. ובכ\"מ). — אבל ראה לקמן סעיף ה והנסמן בהערה 31."],["911","12","וירא כא, ה."]]],[1301670164,"ששים שנה<sup data-n=\"912\">13</sup>, שאז הי' אברהם בן מאה וששים שנה, ושני חיי אברהם היו קע\"ה<sup data-n=\"913\">14</sup>, הרי שרק ט\"ו<sup data-n=\"914\">15</sup> שנה (שבסוף חיי אברהם) היו כל ג' האבות יחד] — מובן, שיש עילוי מיוחד בט\"ו שעות אלו ש­למדו תורה ביחד (כנגד ט\"ו שנים שראו זה את זה) לגבי שאר שעות היום.\nוהנה לפי ביאורו של החיד\"א במדבר קדמות, שט\"ו שעות הן שעות של תורה ותפלה וט' השעות הנשארות היו לצרכי הגוף, מובן העילוי שבט\"ו שעות אלו. דאע\"פ שזה פשוט שגם צרכיהם הגש­מיים של האבות נעשו לשם שמים ב­תכלית השלימות [וכמ\"ש אדמו\"ר הזקן בס' התניא<sup data-n=\"915\">16</sup> \"שהאבות. . כל ימיהם לעולם לא הפסיקו אפילו שעה אחת מלקשר דעתם ונשמתם לרבון העולמים\", ובמ\"א<sup data-n=\"916\">17</sup> מפרט ומפרש שהיו \"בחי' מרכ­בה בכל מעשיהם אפילו בשינתם\"], מ\"מ, אין זה בערך להעילוי דעסק התורה והתפלה עצמו.\nאבל לביאורו בפירושו לס' חסידים, דט' השעות הנשארות הן זמן עסק התפלה, אינו מובן, למה ישתנו וכ\"כ ט\"ו השעות דלימוד התורה מט' השעות דעסק התפלה, עד שלכן \"ראו זה את זה\" רק ט\"ו שנים (כמספר ט\"ו שעות היום והלילה שלמדו תורה ביחד)?\nב. ויש לומר הביאור בזה ע\"ד ה­חסידות:\nידוע<sup data-n=\"917\">18</sup>, שג' האבות אברהם יצחק ו­יעקב הם כנגד ג' העמודים שעליהם העולם עומד<sup data-n=\"918\">19</sup>, תורה עבודה וגמילות חסדים: עיקר עבודת אברהם הי' גמילות חסדים, יצחק — עבודה (וכמחז\"ל<sup data-n=\"919\">20</sup> ש­יצחק הי' \"עולה תמימה\"), ויעקב ענינו תורה, כמ\"ש<sup data-n=\"920\">21</sup> \"ויעקב איש תם יושב אהלים\". וכך הם מחולקים בעבודת ה­מדות, דמדת אברהם היא מדת החסד וה­אהבה, מדתו של יצחק — גבורה ויראה, ושל יעקב — תפארת ורחמים.\nולפי זה, זה שהאבות \"ראו זה את זה\" והיו ביחד ט\"ו שנים, מורה על חיבור כולם יחד, דאע\"פ שכל אחד משלשת אופנים אלו בעבודה מחולק מחבירו, נתחברו ג' האבות יחד לעבוד את ה', שאין זו התחברות גשמית לבד, אלא התחברות אופני עבודת ה' יחד.\nולכן היתה התחברותם רק בנוגע ללימוד התורה, כי התחברות זו של ג' עבודות מחולקות יחד, היא רק בדרגא דלימוד התורה, כפי שהענינים והעבו­דות הם בדרגת התורה<sup data-n=\"921\">22</sup>, שבה \"אלו<sup data-n=\"922\">23</sup> ואלו דברי אלקים חיים\"; משא\"כ בעבו­דה בפועל, בעבודת המדות, וכ\"ש וק\"ו במעשה בפועל, אי אפשר שתהי' הש­תוות כל סוגי ואופני עבודה אלו.\nוזהו גם טעם החילוק, דזה שהאבות למדו תורה ביחד ט\"ו שעות ביום, בא",[["912","13","פרשתנו כה, כו."],["913","14","ח\"ש כה, ז."],["914","15","להעיר מהשקו\"ט ממחז\"ל (ב\"ר פס\"ג, י. פרש\"י פרשתנו כה, כז) דבן י\"ג שנה פירש עשו לע\"ז — ראה דעת זקנים מבעה\"ת וריב\"א עה\"ת שם. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011049\" data-slug=\"likkutei-sichot\" data-id=\"1300011049\">לקו\"ש ח\"א ע' 49</a>. ח\"ה ע' 369 ואילך. ואכ\"מ."],["915","16","רפל\"ד. וראה שם פכ\"ג (כח, ב)."],["916","17","מאמרי אדה\"ז הקצרים ע' תקמ."],["917","18","זהר (ס\"ת) ר\"פ ויצא. מגלה עמוקות אופן רנ (בסופו). מגלה עמוקות עה\"ת ר\"פ לך. ועוד."],["918","19","אבות פ\"א מ\"ב."],["919","20","ב\"ר פס\"ד, ג. רש\"י פרשתנו כה, כו. שם כו, ב."],["920","21","פרשתנו כה, כז. ב\"ר (פס\"ג, י) ופרש\"י עה\"פ."],["921","22","ובעבודת האדם — מצד דרגת המוחין (י\"ה), כדלקמן ס\"ג. — וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201126\" data-slug=\"likkutei-sichot\" data-id=\"1300201126\">לקו\"ש ח\"כ ע' 126</a>."],["922","23","עירובין יג, ב."]]],[1301670165,"לידי ביטוי בחיי האבות בגשמיות, שחיו יחד ט\"ו שנה, ואילו זה שעבדו את ה' כל כ\"ד שעות היום נרמז רק בכך שיש \"כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר\" — כי ענין התחברות (עבודת) ג' האבות יחד בהדרגא של לימוד תורה היתה בפועל; משא\"כ התחברותם יחד בעבודת ה' במשך כל כ\"ד שעות היום, היא רק כפי שהיא בתורה (\"כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר\"), אבל במעשה בפועל, זה שעבדו השם כ\"ד שעות היום, הרי אין עבודת אחד מהם דומה לחבירו כו'<sup data-n=\"923\">24</sup>.\nג. הסברת הענין:\nתורה, גם כשניתנה למטה, הרי היא חכמתו ית' כמו שהיא למעלה, וכשם שאצלו ית', הרי כל המדות ישכנו יחד באחדות גמורה, דכולם הם פרט בגילוי שלימותו ית', והוא \"כוללם יחד\", הנה עד\"ז בתורתו ית', שאין סתירה בין כל סוגי עבודה, דחכמתו ית' מחייבת את כולם (אלו ואלו דא\"ח); משא\"כ בעבודה בפועל, מצד האדם, דכל נברא הוא מצי­אות, הרי כל עבודה (ומדה) אחרת ה\"ה מנוגדת לחברתה, ולכן יש סתירה בין סוגי העבודה.\nוכן הוא גם מצד האדם גופא, דב­מוחין שבאדם אין התחלקות כ\"כ כמו במדות שבלב. וכפי שרואים, דקשה ל­אדם להרגיש קירוב (אהבה) וריחוק (יר­אה) לדבר אחד בבת אחת, משא\"כ מצד המוחין, אפשר שאדם אחד ישיג בבת אחת סברות הפוכות בענין אחד, הן ה­סברות לחיוב והן הסברות לזכות. וכן בעבודה, דכאשר האדם עסוק בהבנת חילוקי אופני העבודה, אפשר שיהי' \"מונח\" בשכלו הבנת עבודות מחולקות זמ\"ז בתכלית, אך כשבא לידי מעשה הרי הוא מוגבל בקו אחד דוקא.\nובדקות יותר:\nידוע שמוחין נקראים \"אין\" לגבי ה­מדות שהן \"יש\", והיינו לפי שענין השכל הוא — תפיסת והשגת המושכל כמו שהוא לאמיתתו, בלי תערובת מציאות ומצב האדם המשיג, משא\"כ תוכן ענין המדות הוא להיפך — התייחסותו אל הדבר שמחוץ הימנו, היינו פעולת הדבר על האדם המרגיש, אם להתקרב אליו (אהבה) או להתרחק ממנו (יראה).\nוכן הוא בעבודת השם: עבודת ה­מדות היא — רגש האדם, שהוא אוהב את השם לפי ש\"קרבת אלקים לי טוב\"<sup data-n=\"924\">25</sup>, ולכן רוצה להתקרב אליו ית' (ועד\"ז ב­יראה וכיו\"ב); משא\"כ עבודת המוחין היא מה ש\"יוצא\" מגדרי מציאות עצמו ותופס ומשיג חכמתו ית' כמו שהיא.\nולכן, במדות האדם הקשורות עם \"מציאותו\", ישנו ענין ההתחלקות בתוקף, משא\"כ במוחין, שבהם משיג האדם כפי אשר חייבה חכמתו ית', אפשר להיות התחברות כל סוגי עבודות יחד.\nד. ויש לומר, דזה שהתחברות העבו­דות דג' האבות יחד היא רק בלימוד התורה שלהם (מוחין), הוא לפי שהם היו קודם מ\"ת, לפני ביטול הגזירה בין \"עליונים\" ו\"תחתונים\", כמבואר במדרש<sup data-n=\"925\">26</sup> דקודם מ\"ת היתה גזירה ד\"השמים שמים לה' והארץ נתן לבני אדם\"<sup data-n=\"926\">27</sup>, דעליונים",[["923","24","להעיר מהמבואר במ\"א (לקו\"ש ח\"ה ע' 373 ואילך), שהנהגת יצחק ויעקב בחיי אברהם (בפעו­לתם בעולם) היתה בקו של עבודת אברהם. ע\"ש. ואכ\"מ."],["924","25","תהלים עג, כח."],["925","26","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["926","27","תהלים קטו, טז."]]],[1301670166,"לא ירדו לתחתונים ותחתונים לא יעלו לעליונים, ובעת מ\"ת נתבטלה הגזירה וניתנה האפשרות לחבר \"עליונים\" ו\"תח­תונים\", אלקות עם גשמיות העולם.\nוכשם שישנו ענין ביטול ה\"גזירה\" בכללות העולם, כך ישנו גם באדם גו­פא, ולא רק בין נפשו וגופו (רוחניות וגשמיות שבו), אלא גם בנפש האדם גופא:\nעבודת המוחין, הבנה והשגה, שבה מאירה האמת כפי שהיא מצד חכמתו ית', היא בחי' \"עליונים\" שבאדם; ועבו­דת המדות, רגש האדם, הקשורה עם מציאותו, היא בחי' \"תחתונים\" (בנפשו גופא).\nוזהו ענין \"ביטול הגזירה\" בנפש האדם: קודם מ\"ת לא הי' אפשר להיות החיבור האמיתי בין \"מוחין\" ו\"מדות\", שה\"ביטול\" שמצד עבודת המוחין יומשך ויורגש גם במדות האדם; ורק לאחרי ביטול הגזירה דמ\"ת ניתן הכח, שאותו הביטול שבמוחין, שמצד ביטול זה אפשר להיות התחברות והתכללות עבו­דות הפכיות (כנ\"ל), יומשך גם במדות, באופן שגם בעבודה בפועל יוכל לעבוד את ה' בכל סוגי העבודות (וכדאיתא בספרי עה\"פ<sup data-n=\"927\">28</sup> ואהבת את ה\"א, שנדרש מאדם הן אהבה והן יראה, אע\"פ \"שאין לך אהבה במקום יראה ויראה במקום אהבה אלא במדת הקב\"ה בלבד\", זאת אומרת, שניתן לאדם הכח לחבר ב' הפכים דאהבה ויראה יחד, \"אהבה ב­מקום יראה ויראה במקום אהבה\").\nה. ועפ\"ז יש לבאר בעומק יותר החי­לוק בין שני הביאורים שבחיד\"א — אם ט' השעות הן השעות של העסק בצרכי הגוף או שהן השעות דעבודת התפלה — שהם שני אופנים בעבודת האבות, אם כללות עבודתם (הן בנפש והן בגוף), או רק עבודה רוחנית שלהם (עבודת הנפש עצמה):\nהביאור הא' שהט' שעות הן השעות דצרכי הגוף, קאי בכללות עבודת ה­אבות, דזה שעבודת האבות (יחד) היתה רק ט\"ו שעות ביום, הוא לפי שלהיותם קודם מ\"ת, לכן היתה עיקר עבודתם רק ברוחניות ולא בגשמיות (כמבואר ב­כ\"מ<sup data-n=\"928\">29</sup>). דאע\"פ שזה פשוט (כנ\"ל) שגם צרכי הגוף שלהם נעשו בתכלית השלי­מות (עד לביטול ד\"מרכבה\"), מ\"מ, אין זה בערך כלל לדרגת עבודתם מצד הרוחניות שלהם, שדביקותם העצומה בה' מצד רוחניותם, לא היתה יכולה להיות נמשכת בגלוי ובפועל בגשמיות שלהם. וזהו ש\"למדו התורה בכל יום. . (רק) ט\"ו שעות\", שלביאור זה היינו תורה ותפלה (כנ\"ל ס\"א), שהיא העבודה ה­רוחנית דהאבות, \"דחילו ורחימו דבמוחא ולבא\"<sup data-n=\"929\">30</sup> (וכידוע<sup data-n=\"930\">31</sup> שהם בחי' י\"ה (ט\"ו) שבשם);\nמשא\"כ הביאור השני שט' השעות ה­נשארות הן השעות דעבודת התפלה, קאי בעבודה רוחנית עצמה דהאבות, שהחי­לוק בין עליון ותחתון הוא \"מוח\" ו\"לב\", תורה ותפילה, וההתחברות דכל האבות יחד היא רק בדרגא דמוחין ולא במדות שבלב, וכנ\"ל באורך.\nו. והנה פ' תולדות (שבה מסופר ע\"ד התחלת חיי יעקב, שהוא הזמן שבו",[["927","28","ואתחנן ו, ה."],["928","29","ראה ספר הערכים­חב\"ד מע' אבות סעיף ד. וש\"נ."],["929","30","הנק' \"הנסתרות\" (רע\"מ נשא קכג, ריש ע\"ב. ת\"ז ת\"י (כה, ב). ת\"ע (קכט, א). ועוד. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא</a> בהקדמה. שם ר\"פ מד)."],["930","31","ת\"ז ריש תכ\"ב. ת\"ע שם."]]],[1301670167,"האבות \"ראו זה את זה\"<sup data-n=\"931\">32</sup>) חלה בתחלת חודש כסלו או בשבת מברכים החודש כסלו — החודש השייך (במיוחד) לגילוי תורת החסידות, וכידוע<sup data-n=\"932\">33</sup> שחודש סיון, ירחא תליתאי<sup data-n=\"933\">34</sup> לחדשי הקיץ הוא זמן גילוי תורת הנגלה, וחודש כסלו, ירחא תליתאי לחדשי החורף שייך לגילוי תורת החסידות\n[עד שבחודש זה ישנם כמה ימים מיו­חדים בדברי ימי החסידות, כמו: הילולא דהרב המגיד (י\"ט כסלו); חג הגאולה של אדמו\"ר הזקן (י\"ט כסלו) ואדמו\"ר האמצעי (יו\"ד כסלו); יום הולדת ויום ההילולא של אדמו\"ר האמצעי (ט' כסלו) ועוד. וכן ימי חנוכה שבסיום החודש, שייכים ג\"כ לפנימיות התורה, שעיקר נס חנוכה הוא נס פך השמן, והרי \"שמן\" שבתורה הם רזי רזין דאורייתא<sup data-n=\"934\">35</sup>].\nוכאן רואים דבר פלא, דכשם שאבות העולם, אברהם יצחק ויעקב, היו יחד בעלמא דין ט\"ו שנה — כך הוא אצל \"אבות החסידות\", הבעש\"ט והמגיד ו­אדמו\"ר הזקן<sup data-n=\"935\">36</sup>, שהיו בעלמא דין יחד ט\"ו שנה (כי רבינו הזקן נולד בשנת תק\"ה (קה\"ת), והסתלקות הבעש\"ט היתה בשנת תק\"כ).\nויש להוסיף עוד פלא:\nנזכר לעיל שבאבות היו שני ענינים — הט\"ו שעות שלמדו תורה (הנרמז בט\"ו שנה שראו זה את זה), וזה שעבדו את ה' כל כ\"ד שעות היום (הנרמז ב\"כ\"ד פסו­קים (שנאמר) אברהם יצחק ויעקב ב­פסוק אחד על הסדר\"),\nודוגמתו מצינו ב\"אבות החסידות\" — שהאבות של חסידות הכללית היו ביחד בעולם הזה ט\"ו שנה (כנ\"ל); ואילו ה­\"אבות\" של תורת חסידות חב\"ד, אדמו\"ר הזקן<sup data-n=\"936\">37</sup> ואדמו\"ר האמצעי ואדמו\"ר הצ\"צ, היו ביחד בעולם הזה כ\"ד שנה (כי אדמו\"ר הצ\"צ נולד בשנת תקמ\"ט, ו­הסתלקות אדמו\"ר הזקן היתה בשנת תקע\"ג).\nוע\"פ משנת\"ל בענין עבודת האבות (קודם מ\"ת), יש לבאר גם תוכן הענין, ובהקדם דברי אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"937\">38</sup> בביאור סדר התגלות תורת החסידות, דכשם שקודם מ\"ת הי' צ\"ל ההקדמה דעבודת האבות, בעבודה רוחנית, אך \"מ\"מ אין זה המשכת התורה ממש. . ואח\"כ ניתנה התורה במ\"ת בהתלבשות שבזה נמשך בחי' העצמות. . התורה שנתלבשה בענינים שלמטה נמשך בזה העצמות\" — כך הוא בהתגלות תורת החסידות, דתחילה היתה \"התגלות ה­בעש\"ט [והרב המגיד]. . התגלות פני­מיות התורה. . שלא בבחי' התלבשות. . ולא הי' העולם יכול לקבל, והי'",[["931","32","אף שסיפור הסתלקות אברהם הוא בס\"פ ח\"ש (כה, ז ואילך)."],["932","33","ראה שיחת י\"ט כסלו (ליל ב') תרפ\"ט. לקוטי לוי\"צ — אגרות (ע' ריז). ועוד."],["933","34","שבת פח, א."],["934","35","אמרי בינה שער הק\"ש פנ\"ד ואילך. ועוד."],["935","36","ראה לקוטי דיבורים ח\"א (לו, א­ב), שה­בעש\"ט והמגיד ואדה\"ז הם כח\"ב (כתר חכמה בינה) דתורת החסידות. — וראה הערה הבאה והערה 40."],["936","37","דשני ענינים באדמו\"ר הזקן — א' מנשיאי תורת החסידות הכללית, ומייסד תורת חסידות חב\"ד. ויש לומר, שזהו החילוק בין שני האופנים בדרגות הנשיאים בספירות: (א) הבעש\"ט, הה\"מ ואדה\"ז — כח\"ב (כנ\"ל מלקו\"ד. וראה שם לז, א), (ב) הבעש\"ט והה\"מ — כתר (עתיק ואריך), אדה\"ז — חכמה, אדמו\"ר האמצעי — בינה, והצ\"צ — דעת (סה\"ש תש\"ב ע' 19. תש\"ה ע' 60)."],["937","38","י\"ט כסלו עטר\"ת (נדפס בסה\"מ עטר\"ת (קה\"ת, תשמ\"ח) ע' תרעג). הובא ונת' בד\"ה פדה ב­שלום תרפ\"ה (סה\"מ תרפ\"ה ע' עט)."]]],[1301670168,"עבודה נעלית וגבוה מאד אבל אין זה התגלות עצם פנימיות התורה, ובא ע\"י רבינו נ\"ע בהתלבשות בהשגה ובזה נמשך בחי' העצם כו'\".\nונת' הענין בכ\"מ<sup data-n=\"938\">39</sup>, שזהו עיקר החי­דוש דתורת חסידות חב\"ד, שע\"י שהעני­נים של תורת החסידות נתבארו בתורת חב\"ד באופן שהם מושגים בשכלו והב­נתו של האדם, עי\"ז נמשך אור החסידות בפנימיותו, בבירור וזיכוך נפשו הבהמית וחלקו בעולם, עד שחודר בכל עניניו, גם בעניניו הגשמיים [ע\"ד החידוש דמ\"ת, חיבור עליונים ותחתונים].\nוזה נרמז בכך, שהאבות של חסידות הכללית היו ביחד ט\"ו שנים, ואילו האבות של חסידות חב\"ד היו ביחד כ\"ד שנה:\nתורת החסידות הכללית, שהיא \"הת­גלות שלא בבחי' התלבשות\", בבחי' מקיף<sup data-n=\"939\">40</sup>, היא בעיקר עבודה רוחנית (ע\"ד עבודת האבות קודם מ\"ת), \"דחילו ו­רחימו דבמוחא ולבא\", בחי' י\"ה (ט\"ו) שבנפש;\nמשא\"כ על ידי חסידות חב\"ד נמשך אור החסידות בכל חלקי האדם (וכפתגם כ\"ק מו\"ח אדמו\"ר<sup data-n=\"940\">41</sup> שגם העקב שברגל יהי' \"אַ חסידישע פּיאַטע\"), ועד שחודר בכל עניניו, גם בעניניו הגשמיים (כנ\"ל) — ועי\"ז ניתן הכח לחיות חיי חסידות במשך כל כ\"ד שעות היממה, עד שאפילו בעת השינה<sup data-n=\"941\">42</sup> יהי' ניכר עליו \"אַז עס שלאָפט אַ חסיד\".\nוכן הוא בנוגע ל\"ציור קומה\" הכללי של כללות ישראל במשך כל הדורות, שע\"י תורת חסידות חב\"ד נמשך הכח שאור החסידות יחדור גם את החשך דדרא דעקבתא דמשיחא, בחי' רגלים ועקביים דוקא<sup data-n=\"942\">43</sup>,\nועי\"ז זוכים ל\"והי' עקב תשמעון גו' ושמר ה\"א לך את הברית גו'\"<sup data-n=\"943\">44</sup>, דכאשר גם בבחי' \"עקב\", דרא דעקבתא דמשי­חא<sup data-n=\"944\">45</sup>, ישנו ה\"תשמעון\" — מקיים הקב\"ה \"את הברית ואת החסד אשר נשבע לאבותיך\", גאולה האמיתית והשלימה ע\"י משיח צדקנו, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחת י\"ט כסלו תשכ\"ב)</span>",[["938","39","ראה סד\"ה פדה בשלום הנ\"ל. ובכ\"מ."],["939","40","להעיר מלקו\"ד שם, דזה שהבעש\"ט והמגיד ואדה\"ז הם כח\"ב דחסידות הוא ב\"כללות הגילוי מלמעלה. . סדר התגלות תורת החסידות בדרך מלמעלה למטה\". ע\"ש."],["940","41","ראה אגרות קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תקסח ואילך (\"התמים\" ח\"ו ע' נב­ג). וראה ס' השיחות תש\"ב ע' 43 ואילך. סה\"מ תש\"ח ע' 253 ואילך."],["941","42","ראה רד\"ה זה היום תרפ\"ו. ועוד. — ולהעיר מרמב\"ם הל' דעות ספ\"ג \"נמצאת שינה שלו עבודה למקום ב\"ה\", אף שלקמן שם (רפ\"ה), במנין עשרה הדברים שבהם צריך שיהי' החכם ניכר, לא מנה ענין השינה. ונת' במ\"א. ואכ\"מ."],["942","43","ראה אגרות קודש וסה\"ש שנסמנו בהערה 41."],["943","44","ל' הכתוב ר\"פ עקב."],["944","45","אוה\"ת ר\"פ עקב. ועוד."]]],[1301670169,"<h3>שיחה ב<sup data-n=\"945\">*</sup></h3>\nא. תנן בסוף קידושין<sup data-n=\"946\">1</sup>: \"מצינו שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה שנאמר<sup data-n=\"947\">2</sup> עקב אשר שמע אבר­הם בקולי וישמור משמרתי מצותי חוקותי ותורותי\".\nוביומא<sup data-n=\"948\">3</sup> גרסינן: אמר רב קיים אברהם אבינו כל התורה כולה שנאמר עקב אשר שמע אברהם בקולי וגו' (ופריך: ואימא שבע מצות, הא איכא נמי מילה וכו').\nוכבר הקשו<sup data-n=\"949\">4</sup>, דמאחר שהיא משנה שלימה בסוף קידושין שעשה אברהם כל התורה כולה, מאי אתא רב לאשמעינן ב­מאמרו במס' יומא<sup data-n=\"950\">5</sup>? (ועוד: אדפריך הכא אמילתא דרב \"ואימא ז' מצות\", לפרוך אמתני' דקידושין?)\nותי' במהרש\"א<sup data-n=\"949\">4</sup>, דבמשנה נקט \"שעשה<sup data-n=\"952\">6</sup> אברהם אבינו\", ד\"לא משמע אלא שעשה כל המצות, והיינו העשין, אבל לישנא דרב קיים כל התורה משמע נמי אלאוין של התורה\" (ולכן פריך ארב \"ואימא שבע מצות\").\nוצ\"ע, דאע\"פ שלשון המשנה היא \"עשה\n.. את כל התורה\", למה תיסק אדעתין שאברהם קיים רק העשין ולא נשמר מלעבור אלאווין? והרי בוודאי השתדל אברהם לקיים כל התורה כולה עד כמה שהי' אפשר לו<sup data-n=\"953\">7</sup> (ובפרט לפי גירסת ה­משנה שלפנינו<sup data-n=\"954\">8</sup> — \"עשה אברהם אבינו את כל התורה כולה\").\n[וזה שלא מקשה הש\"ס בסוף קידושין \"ואימא ז' מצות\" כמו שמקשה ביומא אדרב, י\"ל בפשטות, כי בקידושין אין זה עיקר מקומו של ענין זה (קיום התומ\"צ של אברהם), והובא במשנה רק כתוס' ראי' על פעולתה של התורה \"בעת זקנותו\" (לאחרי הראי' הא' \"(בנערותו מהו אומר<sup data-n=\"955\">9</sup> וקוי ה' יחליפו כח) בזקנותו מהו אומר<sup data-n=\"956\">10</sup> עוד ינו­בון בשיבה\". ולהעיר, דבברייתא שם<sup data-n=\"957\">11</sup>",[["945","*","וסיום מס' קידושין."],["946","1","פב, א."],["947","2","פרשתנו כו, ה."],["948","3","כח, ב."],["949","4","חדא\"ג יומא שם ד\"ה קיים. ובכ\"מ. וראה הנסמן על גליון המשניות."],["950","5","כמה ראשונים (תוס' ר\"י הזקן (הובא בפתח עינים להחיד\"א סוף קידושין). תוס' הרא\"ש. תוס' טוך) כתבו, דסיום המשנה \"מצינו שעשה כו'\" אינו מן המשנה אלא ברייתא היא, אלא דבפתח עינים (מתוס' ר\"י הזקן) ובתוס' טוך שהוא לא רק בנוגע לסיום המשנה, \"וכן כתוב בספרים ישנים דלעולם ילמד אדם אומנות נקי' ברייתא היא\". וראה שינויי נוסחאות למשניות ובהמובא בגליון הש\"ס מ\"פי' הקונט'\" סוף קנים. וישנו בכמה גירסאות וכן בגירסת המאירי. וראה בית דוד למשניות כאן."],["949","4","חדא\"ג יומא שם ד\"ה קיים. ובכ\"מ. וראה הנסמן על גליון המשניות."],["952","6","י\"ג גם במשנה קידושין \"קיים\", כהובא על הגליון בש\"ס ובמשניות. וכ\"ה במאירי, יש\"ש, ופתח עינים קידושין שם."],["953","7","בגו\"א על פרש\"י ויגש (מו, יוד קרוב לסופו) האריך בזה, דשאר האבות (והשבטים כו') קיימו רק מ\"ע ולא ל\"ת (ורק אברהם קיים כל המצות). וראה שם בארוכה הטעם שהיו מקיימין רק מצות עשה.\nאבל לכאורה מצינו בכ\"מ איפכא, ובל' התוס' (ב\"ב טז, ב ד\"ה בא) \"דאע\"פ שלא נצטוו מכל מקום מכוער הדבר\" (ושם כ' זה אפילו בנוגע לעשו). ועד\"ז הוא בכמה מקומות לגבי האבות שהיו נזהרים מלעבור אל\"ת."],["954","8","ראה שינויי נוסחאות למשניות."],["955","9","ישעי' מ, לא."],["956","10","תהלים צב, טו."],["957","11","בסיום המס' (פב, ב). אבל בירושלמי שם הובאה ראי' זו (בסגנון אחר קצת) גם בברייתא."]]],[1301670170,"הובאה רק הראי' הא' ולא הביא הראי' מאברהם)]<sup data-n=\"958\">12</sup>.\nבפשטות יש לומר, שהחידוש במאמר רב על המשנה הוא, שבמשנה קאי רק ב­לימוד התורה דאברהם, משא\"כ רב מחדש שהי' אצלו גם קיום כל המצוות.\nוכן מובן גם מהמשך הענינים, דבמשנה הובא זה בסיום מאמר ר' נהוראי<sup data-n=\"959\">13</sup> \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה, שאדם אוכל משכרה בעולם הזה והקרן קיימת לו לעולם הבא ושאר כל אומנות אינו כן כשאדם בא לידי חולי או לידי זקנה או לידי יסורין ואינו יכול לעסוק במלאכתו הרי הוא מת ברעב אבל התורה אינה כן כו' וכן הוא אומר באברהם אבינו ואברהם<sup data-n=\"960\">14</sup> זקן וה' ברך את אברהם בכל מצינו שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה כו'\" — והיינו שמדובר בענין לימוד התורה; משא\"כ מאמרו של רב ביומא בא בהמשך להמבואר שם לפנ\"ז דאברהם זקן ויושב בישיבה הי' (ומימיהן של אבותינו לא פרשה ישיבה מהם כו'), שע\"ז מביא הש\"ס מאמר רב, דנוסף לזה שאברהם למד תורה, הרי עוד זאת, קיים אברהם אבינו כל התורה כולה (וע\"ז מקשה הש\"ס מנין שקיים אברהם אבינו המצות כו').\nאבל אף שפירוש זה מתיישב היטב בלשון רב \"קיים אברהם אבינו\", מ\"מ קשה לפרש לשון המשנה (בקידושין) \"עשה אברהם אבינו את כל התורה כולה\" דקאי על לימוד התורה בלבד ולא על עשיית המצות בפועל. והרי מביא ראי' מהכתוב \"עקב אשר שמע אברהם בקולי וישמור משמרתי מצותי חוקותי ותורותי\", שמ­פורש בו<sup data-n=\"961\">15</sup> שמירת ועשיית המצוות<sup data-n=\"962\">16</sup>.\nב. יש מפרשים<sup data-n=\"963\">17</sup>, דמתני' משמע ש­עשה אברהם כן מדעתו (וכמודגש במשנה \"עשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\"), אבל רב נקט \"קיים\", דמשמע שנצטווה על כך וקיים הציווי, ודייק לה מדכתיב אשר שמע אברהם בקולי ומשמע שה' צוה לו כך.\nוכן משמע בפרש\"י ביומא שם<sup data-n=\"964\">18</sup>: על קושיית הש\"ס על מאמר רב \"ואימא שבע מצות\" פרש\"י \"ז' מצות שנצטוו לשאר כל בני נח, אבל תורה לא ניתנה לו\" — \"ש\"מ<sup data-n=\"963\">17</sup> דמפרש דברי רב שקיים אברהם את התו­רה לאחר שניתנה (ועלי' קאי קושיית רב שימי)\".\nאבל לכאורה חידוש גדול הוא לומר דרב ס\"ל שאברהם נצטווה על קיום כל התורה, וכמו שהקשה החיד\"א<sup data-n=\"966\">19</sup>, ד\"ליכא למ\"ד שאברהם אבינו ע\"ה נצטווה יותר מהמילה וז' מצות, אלא הוא מעצמו סביר וקביל\".\nג. ונ\"ל בזה, ובהקדם דבגדר תורה ומצות בימי האבות לפני שניתנה<sup data-n=\"967\">20</sup> יש",[["958","12","וראה מה שהקשה עוד על דברי המהרש\"א בשירי קרבן לירושלמי סוף קידושין."],["959","13","ואף את\"ל דלשון זו אינה מדברי ר\"נ עצמו (וראה לעיל הערה 5), ה\"ז בהמשך לדבריו."],["960","14","ח\"ש כד, א (בהשמטת תיבות)."],["961","15","ואולי זהו טעם הגירסא שהביא במלאכת שלמה סוף קידושין שהובא רק \"עקב אשר שמע אברהם בקולי\"."],["962","16","בירושלמי כאן \"ששימר את התורה\", ועד\"ז איתא בכמה דרז\"ל, ובכ\"מ \"קיים\", \"עשה אותה ושמר אותה\", \"עשה אותה ודקדק בה\", ועוד — ראה תו\"ש פרשתנו עה\"פ אות כח. וש\"נ."],["963","17","שירי קרבן לירושלמי סוף קידושין."],["964","18","ד\"ה שבע מצות."],["963","17","שירי קרבן לירושלמי סוף קידושין."],["966","19","פתח עינים שם. כסא רחמים לאבות דר\"נ (ב\"תוספות\") פל\"ג בתחלתו."],["967","20","בגדר האבות וקיום המצות שלהם כבר האריכו במפרשים. וראה פרשת דרכים דרך האתרים דרוש ג. בית האוצר להר\"י ענגיל בתחלתו. ועוד."]]],[1301670171,"לבאר בשני אופנים<sup data-n=\"968\">21</sup>: א) דישנה החפצא דתורה ומצוות (שהרי אלפיים שנה קדמה תורה לעולם<sup data-n=\"969\">22</sup>), אלא שעדיין לא הי' ציווי להגברא (כיון שעדיין לא ניתנה למטה), ולפ\"ז קיום המצות לפני מ\"ת הוי בגדר אינו מצווה ועושה (שמצינו לאחרי מ\"ת), דישנן לתורה ומצוות אלא שהגברא אינו מצווה עליהן; ב) לפני מ\"ת ליכא החפצא דתורה ומצות בעולם, דלא רק שלא הי' ציווי להגברא, אלא שהחפצא נתחדשה (בעולם) בשעת מ\"ת<sup data-n=\"970\">23</sup>.\nויש לומר, שזהו החידוש במאמר רב על מאמר המשנה:\nבמאמר המשנה, שמדייק \"שעשה אבר­הם אבינו את כל התורה כולה עד שלא ניתנה\", כוונתו שלפני מ\"ת לא חל על פעולת התומ\"צ דהאבות גדר של קיום מצוה, אלא מעשה סתם, כיון שכל החפצא נתחדשה בשעת מ\"ת<sup data-n=\"971\">24</sup>;\nואילו רב מחדש שקיים אברהם אבינו כל התורה כולה, דאף שהתורה לא ניתנה עדיין, מ\"מ ישנה להחפצא דתורה ומצות, אלא שלא נצטווה לקיימן, ושפיר יוכל לחול על מעשה אברהם שם \"קיום\" מצוה<sup data-n=\"972\">25</sup> [וע\"ד נשים בקיום מ\"ע שהזמן גרמא, שאף שאינן מצוות עליהן<sup data-n=\"973\">26</sup>, מ\"מ יכולין לקיי­מן<sup data-n=\"974\">27</sup> ונחשב לקיום מצוה, וקיי\"ל<sup data-n=\"975\">28</sup> כהדי­עות שנשים יכולות לברך על קיום מ\"ע שהזמ\"ג \"אשר קדשנו במצותיו וצונו\"].\nד. ועדיין צריך ביאור: מה נוגע לתו­כן דברי המשנה ההדגשה ש\"עשה אברהם אבינו את כל התורה כולה עד שלא נית­נה\", שלא הי' בזה אפילו החפצא דתורה, ואילו בסוגיא דיומא נוגע ההדגשה (שב­מאמר רב) שהי' אצל אברהם גם החפצא דתורה?\nויובן זה בהקדם ביאור ההוספה בה­ראי' מאברהם \"וכן הוא אומר באברהם אבינו\" על הראי' הא' מהכתוב \"עוד ינובון בשיבה\":\nהראי' מהכתוב \"עוד ינובון בשיבה\" יש מקום לפרשה שזה ש\"התורה אינה כן (כ­שאר אומנות) אלא משמרתו מכל רע בנערותו ונותנת לו אחרית ותקוה בזקנו­תו\", וכפרש\"י<sup data-n=\"976\">29</sup> \"אבל התורה אינה כן, שאף הבא לידי זקנה או ייסורין ואינו יכול לעסוק בה הוא אוכל ממתן שכרה דכתיב עוד ינובון בשיבה\", הוא בגדר שכר על לימוד התורה (וקיום המצות) בימי נערותו,",[["968","21","וע\"ד שיש לפרש ב' אופנים בהא דקטנים אינן בני מצוה, אם שאין תומ\"צ שייכים אליהם, או דלכל ישראל ניתנו (וגם להם) אלא דקטנים אינם בני חיוב ועונש כו' — ראה לקו\"ש ח\"ד ע' 1249. וש\"נ. וראה מנ\"ח מצוה רסג בסופה."],["969","22","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. וש\"נ. תנחומא וישב ד."],["970","23","ראה בארוכה (בסגנון אחר) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161212\" data-slug=\"likkutei-sichot\" data-id=\"1300161212\">לקו\"ש חט\"ז (ע' 212</a> ואילך; 218 ואילך). וש\"נ."],["971","24","להעיר מהקושיא בתוס' הרא\"ש סוף קידושין. וראה השינויים בזה ברז\"ל \"עד שלא ניתנה\" (כבמשנתנו), ובירושלמי סוף קידושין \"עד שלא באת לעולם\", ובתוספתא סוף קידושין \"עד שלא באת\" ומסיים \"מלמד שנתגלו לו טעמי תורה ודקדוקי'\". וראה ב\"ר פצ\"ה, ג \"עד עכשיו לא ניתנה תורה כו' (ומסיים) ומהיכן למד אברהם את התורה כו'\" (וראה שם הדיעות בזה)."],["972","25","וע\"ד ב' האופנים די\"ל במצות דקטן ש­מדרבנן (ראה לעיל הערה 21), אם חל ע\"ז שם מצוה דאז צריך לקיימן בכל הפרטים, או דהוי רק מעשה והכשר בעלמא, ואין העשי' צ\"ל בכל הפרטים כגדול — ראה לעיל ע' 62 ואילך. וש\"נ."],["973","26","משנה קידושין כט, א. רמב\"ם הל' ע\"ז פי\"ב ה\"ג. טושו\"ע (ודאדה\"ז) או\"ח סי' יז ס\"ב (א). ועוד."],["974","27","ראה רמב\"ם הל' ציצית פ\"ג ה\"ט. תוד\"ה דלמא (עירובין צו, א). ובכ\"מ."],["975","28","רמ\"א (ושו\"ע אדה\"ז) או\"ח שם ס\"ב (ג). טור (וראה חי' הגהות לסי\"ז שם) ורמ\"א (ושו\"ע אדה\"ז) סתקפ\"ט ס\"ו (ב). וראה שו\"ת הצ\"צ או\"ח סי' ג. — וראה לקו\"ש חלק לא ע' 96."],["976","29","ד\"ה אבל התורה."]]],[1301670172,"או עכ\"פ זכות התורה מצד עצמה, עצם החפצא דתורה דמגינא ומצלא<sup data-n=\"977\">30</sup> גם בזק­נותו; וע\"ז קמ\"ל ראי' הב', שזהו גם מצד (זכות) מעשה הגברא, וכפי שמצינו באב­רהם \"שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\", אף שלא הי' אז כל הגדר דתורה, וגם בו נאמר \"ואברהם זקן וה' ברך את אברהם בכל\".\nויש לומר, דכמו\"כ במאמר רב ביומא שם נוגע הדיוק \"קיים אברהם אבינו כל התורה כולה\", שהיתה כבר חפצא דמצוה, ובמילא שיש בעשיית אברהם הגדר ד­קיום מצוה:\nלעיל בגמ' שם איתא \"צלותא דאברהם מכי משחרי כותלי אמר רב יוסף אנן מ­אברהם ניקום וניגמר (ופי' הערוך<sup data-n=\"978\">31</sup> היאך נלמד מאברהם שקיים התורה עד שלא ניתנה ואין לנו ללמוד אלא ממנהג נביאים מפני שנהגו בהלמ\"מ), אמר רבא תנא גמר מאברהם ואנן לא גמרינן מיני' דתניא וביום<sup data-n=\"979\">32</sup> השמיני ימול בשר ערלתו מלמד שכל היום כשר למילה אלא שהזריזין מקדימין למצות שנאמר<sup data-n=\"980\">33</sup> וישכם אברהם בבוקר ויחבוש וגו' אלא אמר רבא רב יוסף הא קא קשיא לי' כו' א\"נ שאני אבר­הם דאיצטגנינות גדולה היתה בלבו א\"נ משום דזקן ויושב בישיבה הוה כו'\".\nוע\"פ פירוש הערוך הנ\"ל יש לומר, דזהו שהביא הש\"ס לאח\"ז מאמר רב \"קיים אברהם אבינו כל התורה כולה\", והיינו שאין זה רק אגב אורחא דהסוגיא דלימוד התורה וקיום המצות דאברהם, אלא דכיון שבמעשה אברהם הי' בזה גדר קיום מצוה שהרי היתה חפצא דתורה, לכן אפשר ללמוד (גם) מאברהם, אף שהי' לפני ה­ציווי על קיומן [ולפ\"ז מוסבר מה שאפשר ללמוד מאברהם לא רק ענין הזריזות ב­קיום המצות אלא גם בענין קיום המצות גופא].\nה. והנה ביאור הנ\"ל בל' המשנה \"עשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\" מתאים גם עם הפירוש ה­פנימי ב\"עשה\" — שהוא פעל וחידש בה (ע\"ד לשון הכתוב<sup data-n=\"981\">34</sup> \"ואת הנפש אשר עשו בחרן\", וכפשטות פירושו ברז\"ל<sup data-n=\"982\">35</sup> דקאי על \"עשיית\" גרים, ד\"אברהם מגייר את האנשים ושרה מגיירת הנשים\").\nוהיינו דאברהם בעשייתו ועבודתו \"עשה\" — פעל והמשיך התורה בשביל בני ישראל, וכמאמר חז\"ל בנוגע לכמה דב­רים \"מעשה אבות סימן לבנים\"<sup data-n=\"983\">36</sup>, ופירושו שהוא נתינת כח לבנים<sup data-n=\"984\">37</sup>, כן הוא בנוגע לכללות ענין התורה<sup data-n=\"985\">38</sup>, שע\"י עבודת אב­רהם במסירת נפש על התורה והמצוה \"עשה\"<sup data-n=\"986\">39</sup> והמשיך את התורה לבניו, כל בני ישראל אחריו.\n[וכמו שהוא בשייכות לנשמות ישראל, דכיון ש\"האבות הן הן המרכבה<sup data-n=\"987\">40</sup> (\"שכל אבריהם כולם היו קדושים ומובדלים מענייני עוה\"ז ולא נעשו מרכבה רק לרצון",[["977","30","ראה סוטה כא, א."],["978","31","ערך שחר (הא') — נעתק על הגליון ביומא שם. ועד\"ז בר\"ח יומא שם. ועוד."],["979","32","תזריע יב, ג."],["980","33","וירא כב, ג."],["981","34","לך לך יב, ה."],["982","35","כפרש\"י עה\"פ (מב\"ר פל\"ט, יד. ע\"ש)."],["983","36","ראה תנחומא לך לך ט. ב\"ר פ\"מ, ו."],["984","37","ראה רמב\"ן לך לך יב, ו. שם, יוד. יד, א. פרשתנו כו, א. ועוד."],["985","38","ראה בארוכה ע\"ד החסידות <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670251\" data-slug=\"torat-chaim\" data-id=\"2300670251\">תו\"ח לך לך (פג, סע\"ג</a> ואילך). שם ח\"ש (קלה, סע\"א ואילך). ובכ\"מ."],["986","39","להעיר מד\"ה אנכי מגן לך תרע\"ח (קה\"ת, תנש\"א) בנוגע למצות שקיימו האבות, ושם בסופו \"דמש\"א (שהש\"ר פ\"א, ג (א)) ריחות היו זהו בהמצות שעשו מצ\"ע. . אבל בחסד ה' ע\"י הנסיונות המשיכו ג\"כ מבחי' עצמות א\"ס\" (כמו המצות שלאחרי מ\"ת)."],["987","40","ב\"ר פמ\"ז, ו. פפ\"ב, ו. ועוד."]]],[1301670173,"העליון לבדו כל ימיהם\"<sup data-n=\"988\">41</sup>) ועל כן זכו להמשיך נר\"נ לבניהם אחריהם עד עולם מעשר ספירות דקדושה\"<sup data-n=\"989\">42</sup>].\nו. ויש לומר שגם בלימוד התורה דידן יש מעין חילוקי דרגות אלו: תורה כפי שהיא מצד הציווי; שאין עלי' ציווי אבל ישנה להחפצא; אופן שאינו שייך כלל לציווי וכאילו ליתא גם החפצא:\nא) הלימוד מצד החיוב הכללי השייך לכאו\"א, שכל אחד \"יוצא י\"ח בקביעות עתים לת\"ת. . ביום ובלילה בכדי ללמוד ולזכור היטב לימוד המביא לידי מעשה בלבד שהוא חובה על הכל דהיינו השלחן ערוך מהלכות הצריכות לכל אדם לידע אותן כו' ושאר כל היום יעסוק במשא ומתן כדי שיוכל להחזיק ידי ת\"ח\"<sup data-n=\"990\">43</sup>;\nב) קיום \"מצוה<sup data-n=\"991\">44</sup> זו (דת\"ת) כראוי (ע\"י ש)יעשה מלאכה בכל יום מעט כדי חייו בלבד ויסור התאוות ותענוגי הזמן מלבו כמו שאמרו חכמים<sup data-n=\"992\">45</sup> כך היא דרכה של תורה פת במלח תאכל כו'\", והיינו שעושה \"מלאכתו עראי\", וחיוב זה אינו מוטל על כל אחד מישראל ד\"אינו חייב לחיות חיי צער ולעשות מלאכתו עראי כדי להרבות בלימוד שאינו מבין על בוריו כו' אא\"כ עושה במדת חסידות ואהבת התורה\"<sup data-n=\"990\">43</sup>, אבל באם עושה כן הרי הוא זוכה ל\"כתר תורה\"<sup data-n=\"994\">46</sup>;\nג) לימוד התורה באופן שהאדם בוטח בה' לגמרי, ואינו עושה מלאכה כלל, וע\"ד אוכלי המן, וכדברי רשב\"י<sup data-n=\"995\">47</sup> \"אפשר אדם חורש כו' תורה מה תהא עלי' אלא בזמן שישראל עושין רצונו של מקום מלאכתן נעשית על ידי אחרים<sup data-n=\"996\">48</sup> כו'\".\nויש לומר, שב' אופנים האחרונים שאין עליהם ציווי לכאו\"א, הם ע\"ד ב' האופנים הנ\"ל בגדר התורה דאברהם — אם ישנה לחפצא דתורה אלא שלא נצטווה כדוגמת אופן הב', דישנו גדר לימוד כזה שתורתו קבע ומלאכתו עראי לגמרי (\"בכל יום מעט כדי חייו. . תספיק לו מלאכת עראי בישועת ה' והצלחתו בלי הזכרת מעשה נסים\"<sup data-n=\"991\">44</sup>), אלא שהאדם אינו חייב בזה רק מצד מדת חסידות ואהבת התורה; ול­מעלה מזה הוא האופן דבוטח בה' לגמרי שיספק לו כל צרכיו, ועוסק רק בתורה, וגדר לימוד כזה הוא ע\"ד תורה עד שלא ניתנה, שלא רק שאין על זה חיוב, אלא שע\"פ הלכה לא מצינו מציאות כזו לסמוך על הנס<sup data-n=\"998\">49</sup>.\nוזהו מה שמדייק ר\"נ \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה\", שלא בא לחלוק אדברי ר\"מ<sup data-n=\"999\">50</sup> שלפנ\"ז \"לעולם ילמוד אדם את בנו אומ­נות\", כי אם מעשה רב דעצמו אתי ל­אשמעינן, \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה\" (כמבואר במפרשים<sup data-n=\"1000\">51</sup>), שהוא דוקא, מצד גודל",[["988","41","<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ\"ג</a>."],["989","42","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["990","43","הל' ת\"ת לאדה\"ז פ\"ג ס\"ד."],["991","44","הל' ת\"ת שם ס\"ג. וש\"נ."],["992","45","אבות פ\"ו, ד."],["990","43","הל' ת\"ת לאדה\"ז פ\"ג ס\"ד."],["994","46","ראה קו\"א להל' ת\"ת שם סק\"א [תתמד, ב ואילך]."],["995","47","ברכות לה, ב."],["996","48","ראה קו\"א שם."],["991","44","הל' ת\"ת שם ס\"ג. וש\"נ."],["998","49","ראה הל' ת\"ת שם ס\"ג (נעתק לעיל בפנים) ובהנסמן שם. וראה רמב\"ם הל' שמיטה ויובל בסופן."],["999","50","ובפרט דר\"מ הוא ר' נהוראי (עירובין יג, ב. רמב\"ם בהקדמתו לפיה\"מ בסופה (פ\"ו)). ולהעיר דזוהי אחת מהראיות בס' היוחסין (הובא בסה\"ד חלק תנאים ואמוראים ערך ר' נהוראי) דר\"נ אינו ר\"מ, כי \"בסוף קידושין חולק ר\"נ עם ר\"מ\". וראה מלאכת שלמה שבהערה הבאה."],["1000","51","מלאכת שלמה למשניות קידושין שם. המק­נה סוף קידושין. ועוד. וראה גם כסא רחמים למס' סופרים רפט\"ז (ב\"פירוש\"): לפי רוב הענוה אשר במאמרו לא דיבר דרך הוכחה ולא אזהרה כו'."]]],[1301670174,"בטחונו בה', אינו מלמד את בנו אלא תו­רה<sup data-n=\"1001\">52</sup>, אבל אין זו הדרך הנתבעת מכל אדם, דאצל כל אדם צ\"ל תורתו קבע ומלאכתו עראי כנ\"ל, כדברי ר\"מ<sup data-n=\"1002\">53</sup>.\nומדויק גם בדברי רשב\"י \"בזמן ש­ישראל עושין רצונו של מקום מלאכתן נעשית ע\"י אחרים\", היינו שבנ\"י \"עושין\" ומחדשים<sup data-n=\"1003\">54</sup> רצונו של מקום, כי מצד ציווי ה' אין מקום להנהגה זו, אלא יחידי סגולה מצד גודל בטחונם בה' עושין ומחדשים רצונו של מקום, ואז בדרך ממילא מלאכתן נעשית ע\"י אחרים, שהקב\"ה ממלא כל הצטרכותם בדרך נס<sup data-n=\"1004\">55</sup>, למעלה מהטבע לגמרי.\n<span data-k=\"q\">(משיחת ו' תשרי תשמ\"ה)</span>",[["1001","52","וראה גם מאירי במשנה קידושין בדברי ר\"נ \"מניח אני כל אומנות שבעולם\" — \"אפילו אומנות נקי' וקלה\". וכ\"כ בשושנים לדוד למשניות סוף קידושין, דלר\"נ לא ילמוד אומנות כלל."],["1002","53","אבל בחדא\"ג כאן, כסא רחמים (להחיד\"א) למס' סופרים שם (ב\"תוספות\") — פי' דגם לר\"נ צ\"ל מלאכתו עראי עכ\"פ."],["1003","54","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380484\" data-slug=\"likkutei-torah\" data-id=\"4001380484\">לקו\"ת שלח מג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">ברכה צט, ג</a>."],["1004","55","וראה בארוכה הדרן על מס' קידושין — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161546\" data-slug=\"likkutei-sichot\" data-id=\"1300161546\">לקו\"ש חט\"ז ע' 533</a> ואילך. וראה שם ביאור החילוק בין המשנה והברייתא דסוף קידושין."]]],[1301670175,"<h3>שיחה ג</h3>\nא. בסיום פרשתנו נאמר \"וירא עשו כי רעות בנות כנען בעיני יצחק גו' וילך עשו אל ישמעאל ויקח את מחלת בת ישמעאל גו' על נשיו לו לאשה\".\nובמדרש רבה<sup data-n=\"1005\">1</sup> הובאו ב' דעות בפי­רוש כתוב זה: \"ר' יהושע בן לוי אמר נתן דעתו להתגייר (לעשות תשובה<sup data-n=\"1006\">2</sup>), מחלת שמחל לו הקב\"ה על כל עונותיו כו' אמר ר\"א אילו הוציא את הראשונות יפה הי', אלא על נשיו, כאב על כאב (ראשונות היו רעות והשניות כמו כן. רש\"י לב\"ר), ד\"א כוב על כוב (קוצים על קוצים), תוספת על בית מלא (בית היתה מלאה נשים נכריות (ארורות. מתנות כהונה) והוא הוסיף לקחת עליהן. רש\"י).\nועפ\"ז יש לעיין בשיטת רש\"י בפי­רושו על התורה, שפירש \"על נשיו\" — \"הוסיף רשעה על רשעתו שלא גרש את הראשונות\", כדעת ר\"א במדרש, ואילו לקמן בפ' וישלח עה\"פ<sup data-n=\"1007\">3</sup> \"בשמת בת יש­מעאל\" פרש\"י \"ולהלן קורא לה מחלת. . ג' מוחלין להן עונותיהם. . והנושא א­שה. . לכך נקראת מחלת שנמחלו עונותיו\" — הרי שנקט כדעת ריב\"ל (שנמחלו עונותיו)?\nוהנה בנוגע להנהגת עשו יש לתווך, דגם בפירושו בפ' וישלח אין כוונת רש\"י (כדברי ריב\"ל במדרש) \"שנמחלו עונותיו\" מפני \"שנתן דעתו להתגייר\", אלא שעצם הענין ד\"נושא אשה\" יש בו סגולה שמביא למחילת עונות (ע\"ד \"העולה לגדולה\" שהובא ברש\"י שם), ולכן נמחלו עונותיו של עשו אף שלא נתן דעתו להתגייר (ואדרבה, \"הוסיף רשעה על רשעתו\")<sup data-n=\"1008\">4</sup>.\nוצריך ביאור בנוגע ל\"מחלת\" עצמה:\nמפשטות דברי המדרש מובן, ששתי הדיעות בכוונתו של עשו (אם \"נתן דעתו להתגייר\" או להיפך) חלוקות גם בטיבה ומהותה של \"מחלת בת ישמעאל\", אם אשה כשרה היתה: לפי ריב\"ל היתה אשה כשירה (ולכך נקראת \"מחלת\" — שם הרומז על מחילת עונות), ולפי ר\"א היתה מרשעת, כנשי עשו הראשונות (וזהו פירוש \"על נשיו\", שהיתה דומה לנשיו הראשונות).\nוא\"כ סתרי דברי רש\"י אהדדי, דכאן (בסוף פרשתנו) נקט שהיתה מרשעת, ואילו לקמן פי' השם ד\"מחלת\" ע\"ש מחילת עונות, שמזה משמע שאשה כשרה היתה.\n[שהרי גם את\"ל שעצם הענין ד\"נושא אשה\" מביא למחילת עונות (גם בלי שינוי מעשים לטוב) — מ\"מ, מזה גופא",[["1005","1","סוף פרשתנו."],["1006","2","נזר הקודש (השלם) ועץ יוסף לב\"ר שם. וראה חי' הרד\"ל שם."],["1007","3","לו, ג."],["1008","4","ראה נחלת יעקב כאן. וראה גם יפה תואר (השלם) לב\"ר שם, יפה מראה ועץ יוסף לירושלמי בכורים (פ\"ג ה\"ג) — דהא דירושלמי שם (ומדרש שמואל פי\"ז), \"חכם חתן כו' מכפרת\", פליג אתנא דב\"ר.\nוגם לפמשנ\"ת במ\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410226\" data-slug=\"likkutei-sichot\" data-id=\"1301410226\">לקו\"ש ח\"ה ע' 170</a>. ח\"ל ע' 162 ואילך), שלשיטת רש\"י בפירושו עה\"ת, מחי­לת עונות דחתן תלוי' בשינוי מעשיו לטוב, הרי עשו לא שינה מעשיו, כמפורש ברש\"י כאן ש(אדרבא) \"הוסיף רשעה על רשעתו\", וצ\"ל שנמחלו עונותיו מצד מחלת. ולהעיר מהגירסא בפרש\"י \"שנמחלו עונותי'\" — ראה לקמן בפנים."]]],[1301670176,"שרק היא נקראת בשם \"מחלת\" (הרומז על מחילת עונות), ולא נשיו הראשונות, משמע, שהיא היתה ראוי' לכך (גם) מצד מעשי' וכו'.\nובפרט לפי הגירסא בפרש\"י<sup data-n=\"1009\">5</sup> בכמה כתבי יד — \"שנמחלו עונותי'\" (ולא \"עונותיו\"), שמשמע מזה שרק עונותי' נמחלו ולא של עשו, והיינו לפי שהיא היתה כשרה, משא\"כ עשו שנשאר רשע].\nב. אבל כד דייקת נראה שקושיא מעיקרא ליתא, כי כוונת רש\"י בפירושו כאן אינה כפירוש ר\"א במדרש אלא הוא פירוש חדש בדברי הכתובים:\nלשון המדרש היא \"אילו הוציא את הראשונות יפה הי', אלא על נשיו כאב על כאב כו'\"; אבל רש\"י שינה וכתב \"הוסיף רשעה על רשעתו שלא גירש את הראשונות\". ושני שינויים (עיקריים) כאן:\n(א) \"כאב על כאב\" (כוב על כוב) פי­רושו שהוסיף אשה מרשעת על נשיו הרשעות שהיו לו לפני זה, אבל ל' רש\"י \"הוסיף רשעה על רשעתו\" פירושו שמ­עשה נישואי מחלת עצמו הוא מעשה של רשעות מצד עשו.\n[בדפוסי רש\"י הנפוצים ישנה הוספה­הגהה בסוגריים \"ר\"ל מרשעת על מר­שעיות שהיו לו כבר\".\nאמנם עכצ\"ל שאין כוונת המגי' ש­\"רשעה על רשעתו\" פירושו \"מרשעת על מרשעיותיו\" (\"רשעה\" בניקוד שבא, ש­אשתו היא רשעה, כמו \"מלכות יון הרש­עה\") — דא\"כ הו\"ל לרש\"י לכתוב \"רשעה על רשעותיו\"<sup data-n=\"1010\">6</sup>: ומדכתב רש\"י \"על רשע­תו\" משמע, שהרי\"ש בתיבת \"רשעה\" היא בניקוד חיריק (וכמו \"והרשעה כולה ב­עשן תכלה\"), וקאי על רשעתו של עשו<sup data-n=\"1011\">7</sup>.\nויותר מסתבר לומר, שכוונת המגי' היא רק לפרש ולבאר, שרשעתו של עשו (שהוסיף על רשעתו שלפנ\"ז) היא — שנשא מרשעת על מרשעיותיו שהיו לו כבר.\nאבל גם לפ\"ז צע\"ג איך אפשר לפרש כן בפרש\"י<sup data-n=\"1012\">8</sup>, שהרי רש\"י לא הזכיר כלל שמחלת היתה מרשעת, ואם זוהי כוונת רש\"י הי' כותב כן בלשון ברורה: \"הוסיף מרשעת\" (וכיו\"ב)].\n(ב) הלשון \"אילו הוציא את הראשונות יפה הי'\" במדרש באה בתחילת הענין, ואילו רש\"י מהפך הסדר וכתב לשון זו (\"שלא גרש את הראשונות\") בסיום הענין.\nג. ויש לומר ששני השינויים תלויים זב\"ז:\nלפי המדרש, הרשעות של עשו היתה בזה שנשא עוד מרשעת, \"כאב על כאב\", ומ\"ש \"אילו הוציא את הראשונות יפה הי'\" היא רק הקדמה להוציא מדעת ריב\"ל (שלפנ\"ז) ש\"נתן דעתו להתגייר\", שא\"א לומר כן, כי אם כן הי' לו לגרש את הראשונות;\nמשא\"כ לדעת רש\"י לא היתה מחלת מרשעת, וזהו שכתב רש\"י \"הוסיף רשעה על רשעתו שלא<sup data-n=\"1013\">9</sup> גירש את הראשונות\",",[["1009","5","וישלח שם."],["1010","6","או \"רשעיותיו\", \"רשעניותיו\" (ע\"ד סנהדרין קיב, א וברש\"י שם).\nובדפוס א' דפרש\"י (וכן בא' מכת\"י רש\"י ש­תח\"י) \"רשעה על רשעה\", ובזה אפשר לפרש מלשון \"מרשעת\". וראה הערה 9."],["1011","7","ובכמה כת\"י רש\"י שתח\"י \"רשע (רשעה) על רשע (רשעו)\"."],["1012","8","וכן צ\"ע לפירושו, סיום ל' רש\"י \"שלא גירש את הראשונות\" — ראה הערה 10."],["1013","9","בדפוס ראשון דפרש\"י \"ולא גירש כו'\". ולהעיר, שלגירסתו \"הוסיף רשעה על רשעה\", יש לפרש שהיו ב' חטאים: א) נשא אשה מרשעת (ראה הערה 6), ב) ולא גירש את הראשונות."]]],[1301670177,"כלומר, שזו עצמה היא הרשעות שהוסיף עשו עתה<sup data-n=\"1014\">10</sup>, שלא גירש את הראשונות, כדלקמן סעיף ד.\nומוכרח מתוכן הפרשה שמחלת לא היתה מרשעת, שהרי<sup data-n=\"1015\">11</sup> כל הטעם שנשא עשו את בת ישמעאל הוא לפי שראה \"כי רעות בנות כנען בעיני יצחק אביו\", ורצה לעשות נח\"ר לאביו ולישא אשה שתהי' ישרה בעיניו, ולכן הלך ליש­מעאל<sup data-n=\"1016\">12</sup> לישא אשה מיוחסת דוקא [שזהו דיוק לשון הכתוב \"(וילך עשו אל יש­מעאל) ויקח את מחלת בת ישמעאל בן אברהם\" — שלכאורה \"בן אברהם\" מיו­תר, ומאי קמ\"ל<sup data-n=\"1017\">13</sup>? אלא שבזה מדגיש הכתוב שעשו נשא אשה מיוחסת דוקא, בת \"בן אברהם\"] — וא\"כ מסתבר לומר שלקח אשה כשירה<sup data-n=\"1018\">14</sup>, ולא אשה כנשיו הראשונות שהיו \"מורת רוח ליצחק ול­רבקה\"<sup data-n=\"1019\">15</sup>.\nד. ועדיין הדברים טעונים ביאור — דאיך אפשר לומר שרשעתו היא בכך \"שלא גירש את הראשונות\", דמה זה שייך ל\"ויקח את מחלת גו'\"? הרי ה­רשעות \"שלא גירש את הראשונות\" היתה אצלו ענין מכו\"כ זמן (מאז נשא אותן), ומהו הענין שאז \"הוסיף רשעה על רש­עתו (בכך) שלא גירש את הראשונות\"?\nויש לומר הביאור בזה — בפשטות:\nהרשעות של עשו בלקיחת נשיו הרא­שונות לא היתה רק שנשא נשים כאלו שהיו \"מורת רוח ליצחק ולרבקה\", אלא גם מפני הצביעות והרמאות בנישואין אלה, וכפרש\"י עה\"פ<sup data-n=\"1020\">16</sup> \"ויהי עשו בן אר­בעים שנה\" — \"עשו הי' נמשל לחזיר כו' החזיר הזה כשהוא שוכב פושט טלפיו לומר ראו שאני טהור, כך אלו גוזלים וחומסים ומראים עצמם כשרים, כל מ' שנה הי' עשו צד נשים כו' כשהי' בן מ' אמר אבא בן מ' שנה נשא אשה אף אני כן\".\nוזהו גם שאומר (הכתוב ו)רש\"י בסוף פרשתנו — \"ויקח את מחלת גו' על נשיו\", \"הוסיף רשעה על רשעתו שלא גירש את הראשונות\" — דכשם שנישואיו הרא­שונים היו מעשה צביעות (שיאמרו שמת­",[["1014","10","אבל אין לומר שב\"לא גירש את הרא­שונות\" בא רש\"י לבאר תוכן רשעתו הקודמת של עשו (שעלי' הוסיף עתה עוד רשעות — \"(רשעה) על רשעתו\") — שלא גירש את הראשונות [ולכאורה כן מפרש בעל המגי' בפרש\"י] — כי (א) א\"כ לא נזכר ברש\"י כלל מהי רשעתו של עשו עתה. (ב) ועיקר: רשעתו הקודמת של עשו היא מה שנשא נשים אלו, ומהיכי תיתי לומר שגירש את הראשונות, שבשביל זה צריך רש\"י להדגיש (ש\"על נשיו\" פירושו) \"שלא גירש את הראשונות\"."],["1015","11","ראה יפה תואר לב\"ר שם."],["1016","12","להעיר מרש\"י חיי שרה כד, מט."],["1017","13","ועכ\"פ הו\"ל לאמרו בתחילת הכתוב, \"וילך עשו אל ישמעאל בן אברהם\" (יפ\"ת שם)."],["1018","14","ראה גם גו\"א סוף פרשתנו (ד\"ה אחות נביות).\nועפ\"ז מתורץ גם זה שנמחלו עונותיו של עשו (להגירסא \"שנמחלו עונותיו\"), גם להסברא שצ\"ל שינוי מעשיו לטוב (ראה הערה 4) — כיון שלקח אשה כשירה. ואע\"פ שהיתה בזה רשעות (\"הוסיף רשעה כו'\"), מצד הצביעות שבזה (כדלקמן סעיף ד) — מ\"מ, כיון שבפועל לקח אשה כשירה, יש בנישואין אלה כדי לפעול מחילת עונות. וק\"ל.\n[וי\"ל, שזהו הטעם שענין זה (דנושא אשה מוחלין לו כו') נרמז אצל נישואי עשו ומחלת דוקא, ללמ­דנו, שגם שינוי מעשה כזה מספיק לפעול מחילת עונות. וראה יפ\"ת ונזר הקודש לב\"ר שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410072\" data-slug=\"likkutei-sichot\" data-id=\"1301410072\">לקו\"ש ח\"ל ע' 7</a>­166]."],["1019","15","פרשתנו כו, לה ובפרש\"י. שם כז, מו."],["1020","16","כו, לד."]]],[1301670178,"נהג כיצחק אביו), כך גם בנישואי מחלת הוסיף רשעות מעין רשעתו הקודמת, שלקח אשה כשירה רק כדי<sup data-n=\"1021\">17</sup> שיאמר יצחק שחוזר בתשובה, בה בשעה שזה לא הי' אלא צביעות<sup data-n=\"1022\">18</sup>, שהרי \"לא גירש את הראשונות\"<sup data-n=\"1023\">19</sup>. כלומר: נישואי אשה כשרה בה בשעה ששאר נשיו אינן כש­רות מורה שנישואין אלו הן צביעות ורשעות.\n[ולפי\"ז, התיבות \"על נשיו\" שבכתוב, לא באו ללמד את הצד השווה של נשי עשו (ע\"ד הנ\"ל במדרש — \"כאב על כאב\"), אלא לתאר את רשעתו של עשו, דאע\"פ שלקח עתה אשה כשרה, מ\"מ הי' זה \"על נשיו\" — \"שלא גירש את הרא­שונות\"].\nה. מ\"יינה של תורה\" שבפירוש רש\"י:\nסיפורי התורה בכלל, אינם סיפור בעלמא ח\"ו, אלא בגלל ההוראות ב­עבודת השם<sup data-n=\"1024\">20</sup> הטמונים בהם (תורה מל­שון הוראה). וכ\"ש וק\"ו סיפורי תולדות עשו ש\"לא היו ספונים וחשובים ל­פרש\"<sup data-n=\"1025\">21</sup> אותם בתורה, שכל הפרטים בהם שבאו בתורה, יש בהם הוראה בעבודת בני ישראל.\nומזה מובן גם בעניננו, שהסיפור שבסוף פרשתנו אודות נישואי עשו עם מחלת בת ישמעאל, נוגע לעבודת בני ישראל. ובזה גופא יש לימוד מיוחד ע\"פ פירוש רש\"י ש\"רשעתו\" של עשו היא \"צביעותו\". כלומר: החסרון שבצביעות אינו רק משום שהיא מטעה ומרמה, אלא שה\"צביעות\" עצמה היא (עיקר) \"רשעתו\" של עשו.\nויובן זה בהקדים החילוק הכללי בין תולדות עשו שבפ' תולדות לאלו שבפ' וישלח — שבפרשתנו מסופר (בעיקר) או­דות עניני עשו השייכים ליצחק (\"ואלה תולדות יצחק\"), משא\"כ בפ' וישלח באו קורות עשו בשייכות ליעקב.\nוהבדל עיקרי ביניהם: בנוגע ליצחק השתדל עשו לרמות אותו שיחשוב ש­צדיק הוא, וכפרש\"י עה\"פ<sup data-n=\"1026\">22</sup> \"כי ציד בפיו\", ואילו כלפי יעקב אחיו הלך ב­מלחמה גלוי'.\nוב' ענינים אלה של עשו הם הוראה בעבודת כאו\"א מישראל, שיש שני סוגי רע — רע גלוי, ורע נעלם המכוסה וטמון בטוב. וכשם שצריך לעמוד בכל התוקף נגד רע הגלוי (שאי אפשר לטעות בו) — כך, ויתר על כן, צריך להזהר מפני תערובת טוב ורע, רע נעלם, ואדרבה — המלחמה נגד רע זה היא קשה יותר.\nוע\"ד שמצינו אצל יעקב עצמו, ששהה בבית לבן עשרים שנה, ואילו היותו עם עשו לא נמשכה אלא יום א' בלבד (כמו שנאמר<sup data-n=\"1027\">23</sup> \"וישב ביום ההוא עשו לדרכו",[["1021","17","ועפ\"ז יש לבאר מה שהתיבות \"בת ישמעאל בן אברהם\" הם ב\"קדמא ואזלא\", שזה מורה שעשו פרסם שהוא נושא את נכדתו של אברהם. וראה כת\"י רמזי התורה לר' יואל (הובא בתו\"ש פרשתנו ע' תתשיז): בת ישמעאל בן אברהם מוכתר בתגין, כלומר מיוחסת לקח כו'."],["1022","18","ראה גם פירושי התורה לבעלי התוספות (ירושלים, תשד\"מ) וישלח שם: וכל זה עשה עשו לרמות אביו."],["1023","19","ברמב\"ן כאן (כח, ה), שבלקיחת מחלת \"ש­מע לעשות רצון אביו\", וזה ש\"לקח אותן על נשיו ולא גרש את הרעות, כי הלך על תאוות נפשו יותר מרצון אביו\". אבל מלשון רש\"י \"הוסיף רשעה כו'\" מובן, שיש כאן הוספת רשעות חדשה, והיינו לפי שעשה כן רק לרמות את אביו, כבפנים."],["1024","20","ראה זח\"ג קנב, א. ע\"ש."],["1025","21","ל' רש\"י ר\"פ וישב."],["1026","22","פרשתנו כה, כח."],["1027","23","וישלח לג, טז."]]],[1301670179,"שעירה\"), ומבואר בזה<sup data-n=\"1028\">24</sup>, כי \"לבן ה­ארמי\" ענינו גניבת דעת ורמאות, וכדי להתגבר על רמאות ולבטלה דרוש זמן רב, משא\"כ עשו שהלך במלחמה גלוי' נגד יעקב, רומז על (זהו) רע גלוי, שעל זה התגבר יעקב במהירות.\nויש לומר, שהרמאות והצביעות של עשו כלפי יצחק היא פחותה וגרועה יותר מה\"רמאות\" של לבן כלפי יעקב. דהנה בהעלמת רע בטוב, יש ב' אופנים: א) ע\"י העלמת הרע כפי האפשרי, ב) ע\"י הדגשת ופרסום הטוב. שזהו החילוק בין לבן לעשו, שלבן רק רימה את יעקב שלא יכיר מחשבתו הרעה, אבל עשו התנהג כחזיר הזה, ש\"פושט טלפיו לומר ראו שאני טהור\", שלא זו בלבד שמסתיר את הסימן הטמא שבו אלא שעושה מעשה לפרסם \"כשרותו\" — והעבודה לברר רמאות זו קשה הרבה יותר מ­ביטול רמאות סתם.\nוי\"ל שזהו גם הטעם שהתורה מספרת אודות נישואי עשו עם מחלת בת ישמעאל, שבזה מגלה לנו הכתוב עד כמה היא צביעותו של עשו, שהלך בזה באופן של \"הוסיף רשעה על רשעתו\", ש\"פשיטת טלפיו\" היתה עד כ\"כ, שבגלל זה לקח אשה כשירה באמת, בה בשעה שנשאר להיות עשו הרשע, שכל רשעתו הקודמת לא סרה ממנו כלל, \"לא גירש את הראשונות\".\nומזה הוראה לכל או\"א מישראל, עד כמה יש להזהר מענין הצביעות, כי אפשר שהיצר יסכים שהאדם יעשה מעשים טובים, ורשעתו עדיין לא סרה ממנו כלל!\nו. לפי ביאור זה בענינו של עשו הר­שע, יש להבין יותר גם דברי רבינו הזקן בטעם אריכות גלות זה האחרון, וז\"ל<sup data-n=\"1029\">25</sup>:\n\"ענין אריכות הגלות הזה מגלו' ה­קדמוני', צריך להבין מלחמות יעקב עם עשו שהי' בזמן קצר שנלחם עמו ונצחו, ובלבן נשתהה כ\"ב שנים. . עד שנאמר<sup data-n=\"1030\">26</sup> ויבא יעקב שלם<sup data-n=\"1031\">27</sup>. [והביאור] לפי ש­עשו. . מה שלבו חפץ כן ימהר לעשותו שהלך בשרירות לבו רק רע כל היום והכל בגלוי אומר מה שרוצה ואינו בר­מאות, ונקל להלחם עמו שלא לעשות כרצונו בכל הדברים אשר הוא חושק ומתאוה. . וכן בדורות הראשונים היו בגלוי מי שהי' רשע לא הי' בוש מלעשות רע. . ולפיכך ארז\"ל<sup data-n=\"1032\">28</sup> דורות ראשונים שנתגלה עונם נתגלה קצם, אבל דורות האחרונים שלא נתגלה עונם כו', לא נתגלה פי' שמכסים עונם ואינו ניכר הגניבת דעת הבריות שהוא יכול לעשות עבירה. . אך בסתר, ויבוש מלעבור ב­גלוי. . הרע נסתר ונטמן ומכסה עצמו בעבודת ה'. . וזה הי' מלחמת יעקב עם לבן שהי' רמאי ביותר והי' קשה ביותר כי הי' צריך ג\"כ להתנהג עמו ברמאות כי א\"א בלאו הכי, ולכן נמשך זמן רב משך מלחמתם וזהו אריכות הגלות הזה שהוא בחי' לבן\". עכ\"ל.\nולכאורה אינו מובן: ידוע שגלות זה האחרון הוא גלות אדום, ש\"עשו הוא",[["1028","24","ראה מאמרי אדה\"ז — הקצרים (ע' תנב­ג), נעתק (בקיצור) לקמן בפנים סעיף ו. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670071\" data-slug=\"or-hatorah-hb\" data-id=\"8158670071\">אוה\"ת ויצא רכב, א</a> (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670075\" data-slug=\"or-hatorah-hb\" data-id=\"8158670075\">ושם רכו, א</a> באו\"א קצת). סה\"מ תרע\"ח ע' פג."],["1029","25","נסמן בהערה הקודמת. — כאן נעתק נוסח השני הנדפס שם."],["1030","26","וישלח לג, יח."],["1031","27","ראה רש\"י (וישלח שם, יז. רש\"י ישן סוף פרשתנו. ועוד) — שעד אז שהה כ\"ב שנה. ובנוסח הראשון של המאמר \"עשרים שנה\" — הזמן ששהה בבית לבן עצמו (ויצא לא, מא). וראה סה\"מ תרע\"ח שם."],["1032","28","יומא ט, ב."]]],[1301670180,"אדום\"<sup data-n=\"1033\">29</sup>, וע\"פ הנ\"ל מבואר שגלות זה שייך ללבן דוקא, ולא לעשו שהלך בגלוי \"ואינו ברמאות\"?\nוע\"פ הנ\"ל מתורץ, כי בעשו גופא יש ב' אופנים: כלפי יעקב אחיו הלך עשו במלחמה גלוי', ולכן התגבר עליו יעקב בלא שהיית זמן ארוך (ומלחמתו של יעקב נגד מדת ה\"רמאות\" היתה בהיותו אצל לבן הארמי, ולפיכך הוצרך לשהות שם עשרים שנה); משא\"כ כלפי יצחק אביו, התנהג עשו ברמאות, ועוד יותר מרמאות של לבן כנ\"ל, ו\"בירור\" זה של עשו קשה עוד יותר מבירורו של לבן.\nוזהו הטעם שגלות זה האחרון (שעבו­דתו היא לבטל רמאות זו כנ\"ל) הוא גלות אדום דוקא, שנמשל לחזיר (כדאי­תא במדרש<sup data-n=\"1034\">30</sup> \"ואת החזיר זו אדום\"), ש\"פושט טלפיו לומר ראו שאני טהור\" — שזהו הטעם לאריכות הגלות הזה, לפי שעיקר הבירור שבו הוא לבטל רע נעלם כזה, שנוסף על שהוא מעורב בטוב (כמו אצל לבן), עוד זאת, ש\"פוש­טים\" (מדגישים) הטוב לחוץ ובחוץ לומר \"ראו שאני טהור\".\nז. ויש לומר הטעם שצביעות זו של עשו היתה רק כלפי יצחק — ע\"פ ה­ידוע<sup data-n=\"1035\">31</sup> בענין ברכות יצחק, שזה שרצה יצחק לברך את עשו דוקא, הוא לפי שיצחק \"הביט\" על עשו, ראה אותו כפי שהוא מצד שרשו, וראה את הטוב הגנוז בו (כנשמות הגרים שיצאו ממנו, \"כמו<sup data-n=\"1036\">32</sup> ר' מאיר, ואונקלוס, ושמעי' ואבטליון, ועובדי'\"), ואמר שע\"י הברכות יצא טוב זה מן ההעלם אל הגילוי (גם אצל עשו עצמו), באופן שיבטל לגמרי את הרע שבו.\nוכן בעניננו: ה\"טוב\" שבעשו — שהוא הנותן מקום לרמאות שלו, לערב טוב עם רע ועד לפשוט את טלפיו ולומר אני טהור כו' — הוא מצד הטוב הגנוז שב­שרשו, ולכן הבירור של רע זה שבעשו שייך ליצחק דוקא.\nוזהו ג\"כ תוכן עבודתם של ישראל בגלות זה האחרון, גלות אדום, לברר גם רע זה של עשו (אבי אדום), עד עת קץ שאז יתגלה הטוב הגנוז שבו (כפי שהי' נראה אצל יצחק<sup data-n=\"1037\">33</sup>),\nועי\"ז מהפכים גם את \"אדום\" לטוב — כמחז\"ל<sup data-n=\"1038\">34</sup> \"עתיד חזיר ליטהר\" (המרמז גם על אדום, \"את החזיר זו אדום\") — בקיום היעוד<sup data-n=\"1039\">35</sup> \"ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה\", במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ תולדות וש\"פ וישלח, תשכ\"ז; ש\"פ ויצא תש\"מ)</span>",[["1033","29","וישלח לו, א."],["1034","30","ויק\"ר ספי\"ג."],["1035","31","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א פרשתנו כ, ג</a>. ובכ\"מ."],["1036","32","ל' אדה\"ז בתו\"א שם."],["1037","33","ולהעיר שלעת\"ל יאמרו ליצחק דוקא \"כי אתה אבינו\" (ישעי' סג, טז. שבת פט, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370105\" data-slug=\"torah-or\" data-id=\"3901370105\">כב, ג</a>. ובכ\"מ)."],["1038","34","מרז\"ל בלשון זה הובא בשל\"ה פ' חיי שרה, ובכ\"מ (נסמנו ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121183\" data-slug=\"likkutei-sichot\" data-id=\"1300121183\">לקו\"ש חי\"ב ע' 175</a>. וע\"ש באורך)."],["1039","35","עובדי' בסופו. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201153\" data-slug=\"likkutei-sichot\" data-id=\"1300201153\">לקו\"ש ח\"כ (ע' 153</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251165\" data-slug=\"likkutei-sichot\" data-id=\"1300251165\">ע' 165</a> הערה 69). חכ\"ה (ע' 175 הערה 71)."]]],[1301670181,"<h3>שיחה א</h3>\nא. בריש פרשתנו, בתחילת סיפור הליכת יעקב לחרן, נאמר \"ויצא יעקב מבאר שבע גו'\". ובביאור הלשון ויצא (ולא וילך — כבס\"פ לפני זה (פעמיים)) פירש רש\"י<sup data-n=\"1040\">1</sup> \"(לא הי' צריך לכתוב אלא וילך יעקב חרנה ולמה הזכיר יציאתו אלא) מגיד שיציאת צדיק מן המקום עושה רושם, שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה פנה זיוה פנה הדרה, וכן ותצא מן המקום האמור בנעמי ורות\"<sup data-n=\"1041\">2</sup>.\nומקורו של פירוש זה הוא בבראשית רבה עה\"פ<sup data-n=\"1042\">3</sup>, וז\"ל: \"בזמן שהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה, ודכוותה ותצא מן המקום אשר היתה שמה וגו', ותצא וכי לא יצא מן המקום אלא היא. . כשהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה, ניחא דתמן לא היתה שם אלא אותה הצדקת בלבד אלא הכא דהוי יצחק ורבקה, רבי עזרי' בשם רבי סימון אמר לא דומה זכותו של צדיק אחד לזכותו של שני צדיקים\".\nוצ\"ע, למה לא נחית רש\"י לשאול ולתרץ הא דאיתא במדרש על זה, ש­אע\"פ שאין הנידון דומה לראי', שכאן נשארו יצחק ורבקה במקום שיצא יעקב ממנו, משא\"כ גבי נעמי שלא נשאר שם אף צדיק אחד — שאינה דומה זכות ג'<sup data-n=\"1043\">4</sup> צדיקים לזכותם של שני צדיקים. — דהשאלה והתירוץ הם גם ע\"ד הפשט.\n[ודוחק גדול לפרש דס\"ל לרש\"י ש­מקום מושב יצחק ורבקה בזמן ההוא הי' בעיר חברון (וע\"ד מ\"ש במדרש שם<sup data-n=\"1044\">5</sup> לפנ\"ז \"כבר כתיב<sup data-n=\"1045\">6</sup> וישמע (יעקב) אל אביו ואל אמו, ומה ת\"ל ויצא יעקב מבאר שבע, אלא אמר, אבא בשעה שבקש לצאת לחוץ לארץ היכן הורשה לא מבאר שבע אף אני הריני הולך לבאר שבע אם נותן לי רשות הרי אני יוצא ואם לאו איני יוצא לפיכך צריך הכתוב לומר ויצא יעקב מבאר שבע\"). ולכן לא נחית רש\"י לבאר שאינה דומה זכותו של צדיק אחד כו', כי כיון שיצחק ורבקה התגוררו אז בחברון, ואילו יצי­את יעקב היתה \"מבאר שבע\", הרי לא נשאר אף צדיק אחד בעיר (בדיוק כמו גבי נעמי ורות), והמדרש דלעיל (מקורו של פרש\"י זה) ס\"ל שיצחק הי' גר אז בבאר שבע ולכן צריך לתרץ שאינה דומה כו'<sup data-n=\"1046\">7</sup> —\nכי<sup data-n=\"1047\">8</sup> בפשוטו של מקרא מפורש רק",[["1040","1","ריש פרשתנו."],["1041","2","רות א, ז."],["1042","3","פס\"ח, ו."],["1043","4","צע\"ק שבמדרש כאן אומר: אחד. . שני צדיקים."],["1044","5","ב\"ר שם ה בסופו."],["1045","6","תולדות כח, ז."],["1046","7","ראה נזר הקודש (השלם שם, ז סד\"ה והלא כמה) מפי' \"אב\"א\" (ר' אברהם ב\"ר אשר. נדפס בס' \"אור השכל\" על בראשית רבה — וויניציאה, שכ\"ח). מלאכת הקודש על פרש\"י כאן בסופו."],["1047","8","נוסף על מ\"ש במפרשים (ראה פי' אב\"א ופי' מהרז\"ו לב\"ר שם) שגם לדיעה זו, עיקר יציאתו (שעשתה רושם) היתה ממקום שדר בה בקביעות עם אבותיו, דהיינו בחברון, ולא בבאר שבע שלא הלך שם רק לשעה (וראה מפרשים שצויינו לקמן הערה 10). וראה חזקוני כאן \"באר שבע מקום קרוב לחב­רון הי'\". ולהעיר מהלשון במדרש הגדול כאן \"כ\"ז שהצדיק במדינה\"."]]],[1301670182,"ש\"ויעל [יצחק] משם באר שבע\"<sup data-n=\"1048\">9</sup> ולא נזכר שיצחק הלך מבאר שבע לחברון<sup data-n=\"1049\">10</sup>].\nב. לכאורה י\"ל שלפי פירוש רש\"י אין מקום לשאלה זו, שהרי רש\"י מוסיף על לשון המדרש בתחילת פירושו, וכותב \"מגיד שיציאת צדיק מן המקום עושה רושם\", דיש לפרש כוונתו בזה, שהגם שבדרך כלל יציאת הצדיק מן העיר גורמת לסילוק ההוד והזיו וההדר של העיר (שאין זה ענין של עשיית \"רושם\" בלבד), מ\"מ, בנדו\"ד, ביציאת יעקב מבאר שבע, עשתה יציאה זו (רק) רושם, כיון שהיו שם יצחק ורבקה.\nאבל לא גלאַטיק (חלק) לבאר כן כוונת רש\"י, שהרי כותב \"מגיד שיציאת צדיק מן המקום עושה רושם (וממשיך בחדא מחתא) שבזמן שהצדיק בעיר כו'\", ולפי הנ\"ל הי' יותר מתאים לומר \"מגיד שיציאת יעקב עשה רושם\", ואח\"כ להמ­שיך בלשון סתמי (בנוגע לצדיקים בכלל) \"שבזמן שהצדיק בעיר כו'\".\nומשמע, שגם מ\"ש רש\"י \"שיציאת צדיק מן המקום עושה רושם\" לא נאמר רק ביעקב אלא הוא גם כשלא נשאר בעיר צדיק אחר (כבנעמי) [והטעם ש­כותב הלשון \"עושה רושם\" — יש לבאר, כי הודה זיוה והדרה הם רק ענין של \"רושם\" לגבי עצם מציאות העיר].\nג. והנה תוכן פירוש זה הביא רש\"י גם בפירושו לרות שם, וז\"ל \"מגיד ש­יציאת צדיק מן המקום ניכרת ועושה רושם פנה זיוה פנה הדרה פנה שבחה של עיר וכן ויצא יעקב מבאר שבע\".\nוצ\"ע למה כאן בפי' עה\"ת הוצרך רש\"י לכפול \"בזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה כו'\", ולא כתב בקיצור (כבפי' לרות) שע\"י יציאת צדיק מן המקום פנה זיוה כו'<sup data-n=\"1050\">11</sup>.\nונראה לבאר שיש שינוי תוכני בין פירוש רש\"י בפרשתנו לפירושו ברות, דהכא (בפרשתנו) שרש\"י מקדים \"שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה\" (ואח\"כ ממשיך \"יצא משם פנה הודה כו'\") משמעו שהחידוש הוא בה­חיוב, שהצדיק הוא כל הודה וזיוה וה­דרה של העיר (ובדרך ממילא שע\"י יציאתו משם \"פנה הודה וכו'\"); משא\"כ ברות ששם כתב רק השלילה, שע\"י \"יציאת צדיק. . פנה זיוה פנה הדרה\", הרי לא מודגש שהיות הצדיק בעיר פועלת שינוי יסודי בעיר עד שזהו ההוד וכו' של העיר, ורק שהיציאה גורמת חסרון בעיר.\nומטעם זה כותב שם רש\"י \"ניכרת ועושה רושם\", משא\"כ בפרשתנו כתב רק \"עושה רושם\" — כי שם אין ההדגשה שהצדיק הוא זיוה והדרה של העיר אלא שיציאתו רק ניכרת ועושה רושם, משא\"כ בפרשתנו כוונתו להדגיש שזה שהצדיק נמצא בעיר הוא ההוד של המקום וכו'. ולפי זה י\"ל שכוונתו בלשון \"עושה רושם\" היא שזהו יותר מ\"ניכרת\", אלא שנשתנו לגמרי פני העיר (משא\"כ הלשון \"עושה רושם\" ברש\"י רות שם, שבא בהמשך להלשון \"ניכרת\", היא (ע\"ד הנ\"ל ס\"ב) רק למעט מתוקף הדבר).\nודורש ביאור — מהו טעם השינוי בין פירושו כאן לפירושו ברות.",[["1048","9","תולדות כו, כג."],["1049","10","ראה בכל הנ\"ל מלאכת הקודש ובאר בשדה על פרש\"י כאן."],["1050","11","והרי גם ברות רבה שם (פ\"ב, יב [ז]) איתא מאמר ר' עזרי' המובא בב\"ר כאן: גדול שבעיר הוא זיוה כו' וכן אתה מוצא ביעקב אבינו כו'."]]],[1301670183,"ד. ויובן כ\"ז בהקדם ביאור הגדרת השפעת הצדיק על העיר בפרש\"י, שגם בזה שינה מלשון המדרש, שבמדרש איתא \"שבזמן שהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה\"<sup data-n=\"1051\">12</sup>, וברש\"י מוסיף גם \"הוא הודה\", ולא עוד אלא שמקדים \"הודה\"<sup data-n=\"1052\">13</sup> לפני \"זיוה\" ו\"הדרה\"<sup data-n=\"1053\">14</sup> (וכן ברש\"י רות לפנינו ליתא לתיבת \"פנה הודה\"<sup data-n=\"1054\">15</sup>).\nוהנה בפי' תיבות אלו רבו הפירו­שים<sup data-n=\"1055\">16</sup>, אבל כיון שרש\"י, פי' לתלמיד בן חמש למקרא, לא ביאר ופירט פירוש תיבות אלו, עכצ\"ל שס\"ל שמובן מלשו­נות הכתובים בתורה גופא — ועל הסדר, מן המאוחר אל המוקדם:\nהדרה: הלשון \"הדר\" מפורש בקרא — \"והדרת פני זקן\"<sup data-n=\"1056\">17</sup>, שפירושו — בפשטות — לשון כבוד<sup data-n=\"1057\">18</sup>. ועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר. . הוא הדרה\", כי כבודה של העיר הוא שיש בה דברים חשובים ויקרים, וכשצדיק נמצא בעיר נעשית עי\"ז עיר מכובדת, עיר שדר בה צדיק.\nזיוה: \"זיו\" הוא כמו \"זיו השמש\", שפירושו — מלשון אור, אלא שאין זה האור עצמו, אלא רק זיו והארה שמת­פשט ממנו להאיר לעולם. ועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר. . הוא זיוה\", כי ע\"י הנהגתו הטובה ומעשיו הטובים, ה\"ה מקרין אור וזיו על כל אנשי העיר, ו­לומדים ממעשיו כו'.\nהודה: גם \"הוד\" הוא מלשון אור (כמו זיו), כפי שמצינו בנוגע ל\"קרני הודו של משה\"<sup data-n=\"1058\">19</sup>, ובלשון הכתוב<sup data-n=\"1059\">20</sup> \"ונתת מהודך עליו\", \"זה קירון עור פנים\"<sup data-n=\"1060\">21</sup> (\"פני משה כחמה, פני יהושע כלבנה\"<sup data-n=\"1060\">21</sup>), אלא שב­\"הוד\" יש ענין נוסף לגבי \"זיו\" — ש\"קרן עור פניו\" פעל ש\"וייראו מגשת אליו\"<sup data-n=\"1062\">22</sup>, שמזה מובן, ש\"הוד\" אינו \"זיו\" סתם, אלא אור הגורם ליראה ופחד.\n[וכמובן גם בפשטות: זיו החמה וזיו הלבנה אינם פועלים רגש של יראה ופחד, ואדרבה — נהנים מאורם, ואילו קרני הוד של משה — פעל שייראו מ­גשת אליו].\nועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר הוא הודה\" — שנוסף על ה\"זיו\" שמקרין על אנשי המקום להשפיע על הנהגתם, ישנו גם ענין של \"הוד\", שמקרין אור כזה שפועל על אנשי העיר רגש של ביטול ויראה<sup data-n=\"1063\">23</sup>.\nאמנם כ\"ז הוא לפרש\"י, שמפרש לפי פשטות הענין, ש\"הוא הודה. . זיוה. .",[["1051","12","בילקוט לפנינו \"הוא זיוה הוא שבחה הוא הדרה\" [וראה ב\"ר הוצאת תיאודור­אלבק שם ב­חילופי נוסחאות — שרק לפי גירסא אחת ישנו ה­לשון \"הודה\", וגם שם הוא לא בהחיוב, \"הוא הודה\", אלא לגבי יציאת הצדיק, \"פנה הודה\"]."],["1052","13","וכ\"ה בדפוס ראשון, דפוס שני<sup data-n=\"e29\">*</sup> וכמה כת\"י רש\"י (שתח\"י). ובכמה כת\"י רש\"י (שתח\"י) מתחיל ב\"הוא זיוה\". ועד\"ז בדפוס רומא."],["1053","14","ובמדרש לקח טוב כאן \"הוא זיוה הוא שבחה הוא הודה\"."],["1054","15","ברות רבה איתא גם \"הוא הודה\", אבל מתחיל \"הוא זיוה\", ואח\"כ \"הוא הודה\", וכן אח\"כ \"פנה משם פנה זיוה פנה הודה\"."],["1055","16","ראה במפרשי המדרש ומפרשי רש\"י."],["1056","17","קדושים יט, לב."],["1057","18","וראה גם משפטים כג, ג ובפרש\"י. וראה פרש\"י ח\"ש כד, סד."],["1058","19","פרש\"י תשא לד, ל."],["1059","20","פינחס כז, כ."],["1060","21","פרש\"י שם."],["1060","21","פרש\"י שם."],["1062","22","תשא שם."],["1063","23","ראה רא\"ם וגו\"א בפרש\"י. יפה תואר (ובהשלם) לב\"ר שם."],["e29","*","ובהמשך לשון רש\"י \"פנה משם\" איתא \"פנה זיוה (ואח\"כ) פנה הודה כו'\"."]]],[1301670184,"הדרה\" של העיר היינו השפעתו ופעולתו על יושבי העיר (ולכן מתחיל רש\"י ב­\"הוד\" כנ\"ל);\nאבל לפי המדרש, זה שהצדיק פועל בעיר \"זיו והדר\" (\"הוא זיוה הוא הדרה\") לא קאי על הפעולה והשינוי בהנהגת אנשי העיר, אלא על זכות הצדיק — כפי שמסיים שם \"לא דומה זכותו של צדיק כו'\" — והיינו מה שהצדיק מגין על העיר<sup data-n=\"1064\">24</sup>, וכן שבזכותו של הצדיק ישנן השפעות טובות וברכה וכיו\"ב<sup data-n=\"1065\">25</sup>.\nה. ועפ\"ז מתורץ החילוק בין דברי המדרש ודברי רש\"י: לפי פרש\"י ה­מדובר הוא ע\"ד השפעת ופעולת הצדיק על הנהגת אנשי העיר ומעשיהם, ולכן אין צורך לתרץ זה שנשארו יצחק ורבקה — שהרי מפורש בפרש\"י בהמשך הכתובים כאן בנוגע ליצחק \"שכהו עיניו וכלוא בבית והרי הוא כמת\"<sup data-n=\"1066\">26</sup>, וכיון שיצחק הי' \"כלוא בבית\", לא בא במגע עם אנשי העיר לפעול שינוי בהנהגתם, להקרין עליהם מאורו וזיוו וכיו\"ב (אף שמובן שזכותו מגינה על העיר).\n[ובנוגע לרבקה, הרי נוסף לכללות הענין ד\"כל כבודה בת מלך פנימה\"<sup data-n=\"1067\">27</sup>, י\"ל שהיתה צריכה להמצא במחיצתו של יצחק, במשך כל הזמן, כיון ש\"כהו עיניו\", כדי לשמשו ולסייעו כו' (דבפשטות עש­תה זאת רבקה<sup data-n=\"1068\">28</sup>)].\nמשא\"כ כשמדובר בהגנה על העיר או השפעות הטוב והברכה, הרי כשנמצא יצחק בתוך העיר, אפילו במצב ד\"כלוא בבית\", ה\"ה משפיע בעיר, ואדרבא, להיותו נמצא במצב של \"כהו עיניו וכלוא בבית והרי הוא כמת ויצר הרע פסק ממנו\" — \"ייחד הקב\"ה שמו על יצחק\"<sup data-n=\"1069\">29</sup> (\"אע\"פ שלא מצינו במקרא שייחד שמו על צדיקים בחייהם לכתוב אלקי פלוני\"<sup data-n=\"1069\">29</sup>) — הרי פשיטא שגדלה זכותו של יצחק ביותר להביא הגנה וכל השפעת טוב להעיר שדר בה.\nו. ע\"פ כל הנ\"ל יש לבאר החילוק בין פרש\"י בפרשתנו ופרש\"י ברות:\nבפירושו ברות \"מגיד שיציאת צדיק מן המקום ניכרת ועושה רושם, פנה זיוה פנה הדרה פנה שבחה של עיר\", הכוונה בעיקר על ההגנה וההשפעה שבעיר (ע\"ד פירוש המדרש כאן), ולכן לא הקדים רש\"י שם \"פנה הודה\", ולאידך גיסא מוסיף \"(פנה) שבחה של עיר\", שבזה מדגיש שאין המדובר (כ\"כ) בפעולה והשפעה על הנהגת אנשי העיר, אלא ב\"שבחה\" של העיר, שע\"י יציאת צדיק פנה שבחה של העיר.\nמשא\"כ בפרשתנו כוונת רש\"י (כנ\"ל) להשפעת הצדיק על הנהגת ומעשי אנשי העיר, וזהו שמסיים כאן \"וכן ותצא מן המקום האמור בנעמי ורות\", וכוונתו כאן הוא לזה, שיציאה של נעמי ביחד עם",[["1064","24","ויש לומר, שלפרש\"י דבר זה שזכות הצדיק מגינה על עירו וכו' כבר ידעינן ממעשה סדום (וירא יח, כו ואילך). ובמילא לא מתאים כ\"כ לומר בשיי­כות לזכות הצדיק שעל העיר \"מגיד שיציאת צדיק מן המקום עושה רושם\" (אע\"פ ששם מדובר בעשרה צדיקים ויותר, וכאן — אפילו בנוגע לצדיק אחד)."],["1065","25","ראה פי' אב\"א הנ\"ל (הערה 7) על ב\"ר שם (הובא גם באמרי שפר על פרש\"י כאן). נזר הקודש השלם לב\"ר שם."],["1066","26","כח, יג."],["1067","27","תהלים מה, יד."],["1068","28","שאף שהיו לו רועים לצאנו ועבדים לטפל ברכושו וכו', לא מצינו שיהי' ליצחק עבד ע\"ד אליעזר עבד אברהם, ובפשטות תפקיד חשוב כזה, לטפל ביצחק באופן אישי, לא הי' ניתן לסתם עבד."],["1069","29","פרש\"י פרשתנו שם."],["1069","29","פרש\"י פרשתנו שם."]]],[1301670185,"רות פעלה ש\"פנה הודה. . זיוה. . הד­רה\", שהרי רות דבקה בחמותה (למרות שהיתה בתו של מלך<sup data-n=\"1071\">30</sup>) והלכה ל­התגייר<sup data-n=\"1072\">31</sup>, ודבר זה השפיע על אנשי המקום, ולכן ע\"י יציאתה של נעמי עם רות<sup data-n=\"1072\">31</sup> \"פנה הודה וזיוה והדרה\".\n[אבל בפירושו ברות, שפשטות הכ­תוב \"ותצא מן המקום\" קאי על נעמי, אין לומר בנוגע אלי' \"הוא הודה כו'\" (באופן הפועל יראה וביטול על אנשי המקום)<sup data-n=\"1074\">32</sup>, שהרי יציאתה מא\"י ביחד עם בעלה לא הי' דבר רצוי, והיתה הנהגה היפך יראת השם. אלא שמ\"מ שייך לומר שזכות מעשי' הטובים הגינה וגרמה להשפעת ברכה במקום, באופן שביציאתה פנה זיוה הדרה ושבחה של העיר].\nז. מיינה של תורה<sup data-n=\"1075\">33</sup> שבפירוש רש\"י:\nידוע מ\"ש באור החיים<sup data-n=\"1076\">34</sup> שהכתוב \"ויצא יעקב מבאר שבע וילך חרנה\" הוא רמז על ירידת הנשמה בגוף<sup data-n=\"1077\">35</sup>, ד\"באר שבע\" קאי על שורש הנשמה למעלה, ו\"חרן\" קאי על עולם הזה (\"חרן\" ע\"ש \"חרון אף של מקום (בעולם)\"<sup data-n=\"1078\">36</sup>). ודוקא ע\"י ירידת הנשמה בגוף, \"וילך חרנה\", הרי היא מתעלית למעלה יותר מכפי שהיתה לפני ירידתה<sup data-n=\"1079\">37</sup>, כהכלל \"ירידה צורך עלי'\".\nומרמז רש\"י בפירושו על \"ויצא יעקב מבאר שבע\"<sup data-n=\"1080\">38</sup> ענין נוסף בזה — \"לא הי' צריך לכתוב אלא וילך יעקב חרנה ולמה הזכיר יציאתו (מבאר שבע)\"<sup data-n=\"1080\">38</sup>, כלומר: עיקר החידוש בירידת הנשמה הוא בזה ש\"וילך חרנה\", הליכת הנשמה למקום של \"חרון אף של מקום\", שיש שם העלמות והסתרים על קיום התורה והמצות, ואעפ\"כ מתגברת היא על כל העלמות והסתרים אלו ועוסקת בתורה ובמצות, ויתירה מזו, שהיא פועלת בירור נה\"ב והגוף וחלקו בעולם ועושה דירה לו ית' בתחתונים<sup data-n=\"1079\">37</sup> — וא\"כ יש מקום להקשות למה מזכיר הכתוב כאן גם יציאתו מבאר שבע (שלא זהו עיקר הנסיון של הנשמה, ובמילא מובן שלא בגלל זה היא העלי' שלה)<sup data-n=\"1083\">39</sup>.\nוע\"ז מתרץ רש\"י — \"מגיד שיציאת צדיק מן המקום עושה רושם\", די\"ל הרמז בזה לענין ירידת הנשמה למטה, שעצם ה\"יציאה\" ממצב של דביקות בה­קב\"ה (שבו הייתה קודם ירידתה למטה) \"עושה רושם\" למעליותא ופעולה גדולה.",[["1071","30","פרש\"י רות שם, ב."],["1072","31","ראה פרש\"י שם, יט ותלכנה שתיהם \"כיון שנתנה דעתה להתגייר השוה אותה הכתוב לנעמי\"."],["1072","31","ראה פרש\"י שם, יט ותלכנה שתיהם \"כיון שנתנה דעתה להתגייר השוה אותה הכתוב לנעמי\"."],["1074","32","ובפרט שבאשה (נעמי) לא מתאים כ\"כ ענין ההשפעה מצד הנהגתה כו' בכללות העיר, דכל כבודה בת מלך פנימה (כנ\"ל בפנים), משא\"כ בנוגע לרות, שגיור בתו של מלך הוא דבר מפורסם כו'."],["1075","33","היום יום טז שבט."],["1076","34","פרשתנו כח, יד. הובא ונתבאר בקיצורים והערות לתניא ע' נז. ד\"ה ויצא תר\"ל (סה\"מ תר\"ל ע' כט)."],["1077","35","ועד\"ז על ירידת בנ\"י בגלות — ראה זהר ריש פרשתנו קמז, א. שם כג, ב (הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480046\" data-slug=\"or-hatorah-hb\" data-id=\"8316480046\">אוה\"ת</a> פרשתנו (כרך ה) תתנד, א). ב\"ר פס\"ח, יג. של\"ה פרשתנו רצב, ב."],["1078","36","פרש\"י ס\"פ נח."],["1079","37","נתבאר בארוכה בד\"ה ושבתי בשלום תש­ל\"ח (סה\"מ — מלוקט ח\"ב ע' קסב ואילך). וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151258\" data-slug=\"likkutei-sichot\" data-id=\"1300151258\">לקו\"ש חט\"ו ע' 245</a> ואילך."],["1080","38","להעיר שבדפוס ראשון דפרש\"י (ובכמה כת\"י רש\"י שתח\"י) הד\"ה הוא \"ויצא יעקב מבאר שבע\", ובהתחלת פירושו \"למה הזכיר יציאתו מן המקום\"."],["1080","38","להעיר שבדפוס ראשון דפרש\"י (ובכמה כת\"י רש\"י שתח\"י) הד\"ה הוא \"ויצא יעקב מבאר שבע\", ובהתחלת פירושו \"למה הזכיר יציאתו מן המקום\"."],["1079","37","נתבאר בארוכה בד\"ה ושבתי בשלום תש­ל\"ח (סה\"מ — מלוקט ח\"ב ע' קסב ואילך). וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151258\" data-slug=\"likkutei-sichot\" data-id=\"1300151258\">לקו\"ש חט\"ו ע' 245</a> ואילך."],["1083","39","באוה\"ח הנ\"ל \"ואומרו מבאר שבע ממקום שממנו יצאו הנשמות יקרא באר מים חיים ושבע ירמוז אל שבועת ה' אשר תשבע הנפש ביציאתה שלא לעבור על דברי תורה\". אבל לפ\"ז אינו חלק מגוף הירידה אלא רק הנתינת כח על העבודה או על העלי' (ראה במקומות שבהערה 34). משא\"כ לפי המבואר בפנים."]]],[1301670186,"דכיון שכאשר הצדיק הוא בעיר — \"עיר אלקינו\" — \"הוא הודה הוא זיוה הוא הדרה\", שכל מציאות הנשמה היא מה שהיא נהנית מזיו השכינה<sup data-n=\"1084\">40</sup> ויש לה אהבה ויראה מאלקות, וע\"י יציאתה מ\"עיר אלקינו\", \"פנה הודה פנה זיוה פנה הדרה\"<sup data-n=\"1085\">41</sup> — הרי שעצם יציאת הנשמה משרשה ומקורה (\"באר שבע\") היא מסירת נפש ולכן \"עושה רושם\"<sup data-n=\"1086\">42</sup>.\nוכיון שכן, ברור שבזכות היציאה עצמה, ראוי כאו\"א מישראל לכך ש­הקב\"ה יחזירו למקומו האמיתי, \"ושבתי בשלום אל בית אבי והי' הוי' לי לאלקים וגו'\"<sup data-n=\"1087\">43</sup>, בגאולה האמיתית וה­שלימה על ידי משיח צדקנו, תיכף ומיד ממש.\n<span data-k=\"q\">(משיחות ש\"פ ויצא תשכ\"ה, תשמ\"ח)</span>",[["1084","40","רמב\"ם הל' תשובה פ\"ח ה\"ב. מברכות יז, א."],["1085","41","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, סע\"א</a>)."],["1086","42","ויש לומר שזהו שרש\"י מסתייע \"וכן ותצא מן המקום האמור בנעמי ורות\", דשם אין המדובר ביציאה מא\"י לחו\"ל (כבפרשתנו בנוגע ליעקב) — שהיא ע\"ד יציאת הנשמה משרשה ומקורה וירידתה למטה בגוף — אלא להיפך, יציאה מחו\"ל לא\"י. וגם שם מדגיש הכתוב \"ותצא מן המקום\", כי עיקר החידוש הוא עצם היציאה ממקומו של האדם, וגבי רות הי' זה בעקירתה ויציאתה ממקומה ע\"מ להתגייר."],["1087","43","פרשתנו כח, כא. וראה בארוכה ד\"ה ושבתי בשלום הנ\"ל."]]],[1301670187,"<h3>שיחה ב</h3>\nא. תנן<sup data-n=\"1088\">1</sup>: \"תפלת השחר עד חצות. . תפלת המנחה עד הערב. . תפלת הערב אין לה קבע\". וכבר עמדו במפרשים<sup data-n=\"1089\">2</sup> על טעם השינוי, שגבי ק\"ש התחיל התנא<sup data-n=\"1090\">3</sup> ב­ק\"ש של ערבית (\"מאימתי קורין את שמע בערבין\"), ואילו כאן גבי תפלה נשנו ה­תפלות בסדר דשחרית מנחה וערבית.\nוביותר יוקשה להמ\"ד בגמ'<sup data-n=\"1090\">3</sup>, שהטעם שהתחיל בק\"ש של ערבית הוא כ\"ברייתו של עולם דכתיב<sup data-n=\"1092\">4</sup> ויהי ערב ויהי בקר יום אחד\" [ולא משום דסמיך אקרא \"בשכבך ובקומך\", ש\"א\"כ אינו מקפיד קרא אלא אק\"ש\"<sup data-n=\"1093\">*4</sup>], וא\"כ גם בסדר התפלות הו\"ל ל­מיתני הכי.\nוביארו, דשאני תפלה מק\"ש, דמצד עצם התקנה דתפלה הרי סדר התפלות הוא — שחרית מנחה ערבית: הן למ\"ד<sup data-n=\"1094\">5</sup> \"תפלות אבות תקנום\" — הרי אברהם תיקן תפלת שחרית יצחק תפלת מנחה ויעקב תפלת ערבית<sup data-n=\"1095\">6</sup>, והן למ\"ד<sup data-n=\"1095\">6</sup> \"תפלות כנגד תמידין תקנום\", הרי שחרית ומנחה הן כנגד שני התמידים, וערבית היא כנגד \"אברים ופדרים שלא נתעכלו מבערב קרבים והולכים כל הלילה\"<sup data-n=\"1097\">7</sup>, ונמצא ש­תפלת ערבית היא התפלה האחרונה, כמו שהקרבת אברים ופדרים בלילה היא השלמה לקרבנות שנקרבו ביום.\nולכאורה צ\"ע מהא דאיתא בגמ'<sup data-n=\"1098\">8</sup>: \"טעה ולא התפלל ערבית מתפלל בשח­רית שתים, שחרית מתפלל במנחה שתים. . איבעיא להו טעה ולא התפלל מנחה מהו שיתפלל ערבית ב', את\"ל טעה ולא התפלל ערבית מתפלל שחרית ב' משום דחד יומא הוא דכתיב<sup data-n=\"1092\">4</sup> ויהי ערב ויהי בוקר יום אחד אבל הכא תפלה במקום קרבן היא וכיון דעבר יומו בטל קרבנו, או דילמא כיון דצלותא רחמי היא כל אימת דבעי מצלי ואזיל\".\nהרי מפורש, דסדרן של ג' תפלות הוא — ערבית שחרית מנחה, כפי סדר \"ברייתו של עולם\" (כמו ק\"ש), \"חד יומא. . ויהי ערב ויהי בוקר יום אחד\", ולכן סלקא דעתך אמינא שאי אפשר להשלים תפלת מנחה בתפילת ערבית שלאחרי', כיון שכ­בר עבר יומו<sup data-n=\"1100\">9</sup> (וגם לפי המסקנא דלא אמ­רינן \"עבר יומו בטל קרבנו\", ה\"ז רק לפי<sup data-n=\"1101\">10</sup>",[["1088","1","ברכות רפ\"ד."],["1089","2","פני יהושע וצל\"ח ברכות רפ\"ד. סמיכת חכמים שם (לתוד\"ה תפלת). ועוד. ולהעיר מלבוש שבהערה *16."],["1090","3","ריש ברכות."],["1090","3","ריש ברכות."],["1092","4","בראשית א, ה."],["1093","*4","תוד\"ה אי הכי ברכות שם."],["1094","5","ברכות כו, ב. ועד\"ז בירושלמי שם פ\"ד ה\"א (ושם הלשון \"תפילות מאבות לימדום\"). ב\"ר פרש­תנו (פס\"ח, ט)."],["1095","6","ברכות שם. ועד\"ז בירושלמי וב\"ר שם."],["1095","6","ברכות שם. ועד\"ז בירושלמי וב\"ר שם."],["1097","7","ברכות שם (וראה רש\"י שם ד\"ה ופדרים \"וכנגדן תקנו תפלת ערבית\". ועד\"ז ברמב\"ם הל' תפלה פ\"א ה\"ו. ועוד). ירושלמי וב\"ר שם (וראה מפרשים שם)."],["1098","8","ברכות כו, א."],["1092","4","בראשית א, ה."],["1100","9","וראה השקו\"ט בפני יהושע ברכות שם, ד­לכאורה הא ד\"תפלה במקום קרבן\" הוא טעם להיפך, שיכולים להשלים מנחה בערבית, כמו הקטרת איברי התמיד בלילה, ולאידך — שא\"א להשלים ערבית בשחרית ושחרית במנחה שלאחרי', ע\"ש באורך (וראה גם צל\"ח לתוס' שם ד\"ה איבעי' להו). — וראה מאירי שבהערה הבאה."],["1101","10","אבל במאירי ברכות שם, דזה שאין אומרים עבר יומו בטל קרבנו הוא לפי ש\"אף איברים ופדרים שמתעכלין כל הלילה מקרבן היום שעבר הם\"."]]],[1301670188,"ש\"צלותא רחמי היא כל אימת דבעי מצלי ואזיל\").\nוכן מצינו בגמ'<sup data-n=\"1102\">11</sup>: \"יכול יתפלל אדם כל היום כולו כבר מפורש על ידי דני­אל<sup data-n=\"1103\">12</sup> זמנין תלתא וגו'. . יכול יהא כוללן בבת אחת, כבר מפורש על ידי דוד ד­כתיב<sup data-n=\"1104\">13</sup> ערב ובקר וצהרים וגו'\" — הרי ש­סדר התפלות הוא \"ערב ובקר וצהרים\"<sup data-n=\"1105\">14</sup>.\nב. ויש לומר הביאור בזה:\nידוע הכלל בהלכה<sup data-n=\"1106\">15</sup>, ד\"במעשה ברא­שית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\".\nועפ\"ז יש לומר, ששני הסדרים בג' התפלות, אם תפילת ערבית היא סיום ג' התפלות (לילה הולך אחר היום), או שהיא התחלת ג' התפלות (היום הולך אחר הלי­לה), תלוי אם תפלה היא בגדר \"קדשים\" או בגדר \"מעשה בראשית\".\nויש לומר דתרווייהו איתנהו בה, שיש בענין התפלה גדר של \"קדשים\", שמצד זה \"לילה הולך אחר היום\"<sup data-n=\"1107\">16</sup> וסדר התפלות הוא שחרית מנחה ערבית; וגם גדר של \"מעשה בראשית\" שבזה \"היום הולך אחר הלילה\", ולפ\"ז סדר התפלות הוא — ער­בית שחרית מנחה<sup data-n=\"1108\">*16</sup>.\nדהנה, במהותה של תפלה מצינו שני ענינים:\nמחד גיסא התפלה היא \"עבודה שב­לב\", וכמרז\"ל<sup data-n=\"1109\">17</sup> שחובת התפלה נלמדת ממ\"ש<sup data-n=\"1110\">18</sup> \"ולעבדו בכל לבבכם\" — \"איזו היא עבודה שהיא בלב הוי אומר זו תפ­לה\"; ולאידך, הפירוש הפשוט של \"תפלה\" הוא מלשון בקשה, והיינו מה שהאדם מבקש את צרכיו מאת הקב\"ה.\nדשני ענינים אלה — עבודה שבלב ובקשת צרכיו — שונים זמ\"ז בתכלית, שהרי \"עבודה שבלב\" פירושה (כפשטות הלשון) — לעבוד את ה', שענינה קבלת עול מלכות שמים ודביקות בה'<sup data-n=\"1111\">19</sup>, וכד­איתא במשנה<sup data-n=\"1112\">20</sup> ש\"חסידים הראשונים היו שוהין שעה אחת ומתפללין כדי שיכוונו לבם לאביהם שבשמים\", ומבואר בטור<sup data-n=\"1113\">21</sup>, \"",[["1102","11","ברכות לא, א. וכן בירושלמי ברכות שם. וראה ברכות כ, ב (אבל ראה רש\"י שם ד\"ה ה\"ג והגהת הב\"ח שם. וראה תוד\"ה בתפלה שם)."],["1103","12","דניאל ו, יא, שם, יד."],["1104","13","תהלים נה, יח. — הובא גם ברמב\"ם הל' תפלה שם. וראה שם ה\"ח. ובשאילתות פ' לך (שאילתא ח) נלמד עצם החיוב \"לצלויי תלתא זימני ביומא\" מכתוב זה."],["1105","14","להעיר מהדיעה בירושלמי וב\"ר שם, שג' תפלות הם כנגד \"ג' פעמים שהיום משתנה\". ע\"ש. ולהעיר, שבב\"ר שם נקט בדיעה זו כהסדר ערבית שחרית מנחה, וראה יפה תואר (השלם) שם, ש\"נקט. . כסדר היום שהיום הולך אחר הלילה\"."],["1106","15","חולין פג, סע\"א."],["1107","16","וראה צל\"ח הנ\"ל הערה 2."],["1108","*16","ולהעיר מלבוש או\"ח ר\"ס פט: ג' תפלות כו' ערב ובקר וצהרים כו' ותקנו אותן כו' כנגד התמידין כו' נתקנו מימות האבות כו' לפיכך נפרש אותן ג\"כ על הסדר שנתקנו, זמן תפלת השחר כו'."],["1109","17","תענית בתחילתה. ירושלמי ברכות שם. וכן בספרי עקב (יא, יג). הובא ברמב\"ם ריש הל' תפלה (כדלקמן סעיף ג)."],["1110","18","עקב שם."],["1111","19","וכהפירוש ב\"תפלה\" מלשון התחברות (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370355\" data-slug=\"torah-or\" data-id=\"3901370355\">תו\"א ר\"פ תרומה (עט, סע\"ד</a>). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480074\" data-slug=\"or-hatorah-hb\" data-id=\"8316480074\">אוה\"ת</a> פרשתנו (כרך ה תתסח, א), שם ויחי שפ, א (ע\"פ פרש\"י פרשתנו ל, ח). ובכ\"מ)."],["1112","20","ברכות ל, ב. ובגמ' שם (לב, ב. הובא בהל' ת\"ת לאדה\"ז שבהערה הבאה) \"ששוהין ט' שעות ביום בתפלה\"."],["1113","21","או\"ח סצ\"ח. נעתק בשו\"ע (ודאדה\"ז) שם. וראה גם הל' ת\"ת לאדה\"ז (פ\"ד ס\"ה), ושם (מס' חרדים והשל\"ה): \"ולא היו חוששין לביטול תורה אף שת\"ת כנגד כולם\" לפי ש\"מצות הדביקות האמיתית ביראה ואהבה היא גדולה ממצות ת\"ת וקודמת אלי'\"."]]],[1301670189,"שהיו מתבודדים ומכוונין בתפלתן עד שהיו מגיעים להתפשטות הגשמיות ולהת­גברות רוח השכלית עד שהיו מגיעים קרוב למעלת הנבואה\", ומובן בפשטות, שבהיותם במצב זה של התקשרות \"לאדון הכל ב\"ה ביראה ואהבה עזה ודביקות אמיתית\"<sup data-n=\"1114\">22</sup>, אין חושבים ע\"ד צרכי עצ­מם<sup data-n=\"1115\">23</sup>.\nאלא שהם הם שני הגדרים שבתפלה: \"עבודה שבלב\", שהיא הדביקות בה', ה\"ז כמו גדר \"קדשים\"<sup data-n=\"1116\">24</sup> [דכמו ענין הקרבנות כפשוטו, שהוא הקרבה לה' ובבית ה', כך הוא ענין התפלה, מה שהאדם עומד לפני ה'<sup data-n=\"1117\">25</sup>, וגם תוכן העבודה הוא הדביקות בה' (ע\"ד הקרבה לה')]; ובקשת הצרכים שב­תפלה ה\"ז ע\"ד וענין \"מעשה בראשית\", שהאדם חושב ע\"ד צרכי עצמו.\nג. והנה, להלכה למעשה נקטינן (כנ\"ל) שסדר התפלות הוא ערבית שחרית ומנחה, שלכן ליכא אפילו קס\"ד בגמ'<sup data-n=\"1101\">10</sup> שזה ש­יכולים להשלים תפלת מנחה בתפילת ערבית הוא להיותה הסיום של ג' התפלות, ומוכח שסדר התפלות להלכה הוא ערבית שחרית מנחה.\nויש לומר טעם הדבר, כי ע\"פ הלכה, החיוב והדין דמצות התפלה הוא בקשת צרכיו (שהוא גדר \"מעשה בראשית\" שב­תפלה כנ\"ל), שזהו עצם החפצא דתפלה; משא\"כ \"עבודה שבלב\" הוא רק תיאור מצב הגברא המתפלל, דכדי שתהי' החפ­צא דבקשת צרכיו כדבעי צריך הגברא להיות במצב של \"עבודה שבלב\", ובלעדה חסר בעצם הבקשה, אבל מ\"מ אין זו מהות התפלה.\nועפ\"ז יש לבאר דברי הרמב\"ם בריש הל' תפלה: \"מצות עשה להתפלל בכל יום שנאמר<sup data-n=\"1119\">26</sup> ועבדתם את ה' אלקיכם, מפי השמועה למדו שעבודה זו היא תפלה שנאמר<sup data-n=\"1110\">18</sup> ולעבדו בכל לבבכם אמרו חכ­מים<sup data-n=\"1121\">27</sup> אי זו היא עבודה שבלב זו תפלה\".\nוכבר הקשו במפרשים<sup data-n=\"1122\">28</sup>, אמאי הביא הרמב\"ם הכתוב \"ועבדתם את ה' אלקיכם\", הרי בלאה\"כ צריך להביא הכתוב \"ולעב­דו בכל לבבכם\" שרק ממנו למדים דקאי על תפלה, \"אי זו היא עבודה שבלב זו תפלה\" (משא\"כ בכתוב \"ועבדתם את ה' אלקיכם\" שלא נתפרש בו \"לב\", אין הכרח דקאי על תפלה דוקא) — וא\"כ הו\"ל ל­הביא רק הכתוב ד\"ולעבדו בכל לבב­כם\"<sup data-n=\"1123\">29</sup>.\nויש לומר ע\"פ מ\"ש בקרית ספר<sup data-n=\"1124\">30</sup>, דמ­הכתוב \"ועבדתם גו'\" למדים ש\"מצות עשה להתפלל בכל יום\", כי \"סמיך אסופי' ד­",[["1114","22","ל' אדה\"ז בהל' ת\"ת שם."],["1115","23","ראה תקו\"ז ת\"ו (כב, א) \"צווחין בצלותין כו' ככלבים הב הב לנו מזונא כו'\". או\"ת להה\"מ ר\"פ ויגש ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231217\" data-slug=\"likkutei-sichot\" data-id=\"1300231217\">לקו\"ש חכ\"ג ע' 217</a> ואילך. וש\"נ."],["1116","24","וכנרמז גם בטור שם, שבהמשך הסימן מאריך ע\"ד זה ש\"התפלה היא במקום הקרבן. . ולכן צריך ליזהר שתהא דוגמת הקרבן בכוונה כו'\". ע\"ש באורך (ונעתק בשו\"ע (ודאדה\"ז) שם). וראה לקו\"ש חלק ל\"ב ע' 39.\nולהעיר ממרז\"ל (הובא בסהמ\"צ להרמב\"ם מ\"ע ה'. כס\"מ הל' תפלה פ\"א ה\"ג) עבדהו במקדשו."],["1117","25","טושו\"ע (ודאדה\"ז) שם. וראה שבת י, א \"כעבדא קמי' מרי'\" (וכן בטושו\"ע (ודאדה\"ז) או\"ח סו\"ס צה). ברכות לג, א: עומד לפני ממה\"מ כו'. שו\"ע אדה\"ז או\"ח סי' קד ס\"ב. ועוד."],["1101","10","אבל במאירי ברכות שם, דזה שאין אומרים עבר יומו בטל קרבנו הוא לפי ש\"אף איברים ופדרים שמתעכלין כל הלילה מקרבן היום שעבר הם\"."],["1119","26","משפטים כג, כה."],["1110","18","עקב שם."],["1121","27","נסמן בהערה 17."],["1122","28","כס\"מ ועוד."],["1123","29","ובמנין המצות בריש ס' היד (מ\"ע ה) הובא רק הכתוב ד\"ועבדתם\". וגם בסהמ\"צ שם: א) לא הביא בתחילת המצוה הכתוב ד\"ולעבדו\". ב) גם בהמשך הענין מעתיק רק ל' הספרי \"ולעבדו זו תפלה\", ולא כל הדרשה \"אי זו היא עבודה שבלב כו'\" [ואדרבה, ממשיך \"ואמרו גם כן ולעבדו זו תלמוד\". ונת' בשיחת ש\"פ בחוקותי תשד\"מ]."],["1124","30","להמבי\"ט לרמב\"ם שם. נעתק בלח\"מ שם."]]],[1301670190,"קרא דכתיב וברך את לחמך ואת מימיך וגו' דהוא צורך כל יום הכי נמי תפלה ב­כל יום\" (\"למה<sup data-n=\"1125\">31</sup> שאתה שואל צרכיך בה\").\nועפ\"ז י\"ל, שהחילוק בין שני הכתובים ד\"ועבדתם גו'\" ו\"ולעבדו בכל לבבכם\" הוא: עיקר ההדגשה בכתוב \"ועבדתם גו'\" היא על בקשת הצרכים (כמ\"ש לאח\"ז \"וברך את לחמך גו'\"), ואילו בכתוב \"ול­עבדו בכל לבבכם\" נאמר רק הענין דעבו­דה שבלב. וזהו שמשמיענו הרמב\"ם<sup data-n=\"1126\">32</sup> בזה שהקדים הכתוב ד\"ועבדתם גו'\", כי מהות מצות התפלה היא בקשת צרכיו, וזה שתפלה היא \"עבודה שבלב\" הוא רק כדי שבקשה זו תהי' כדבעי, \"בבקשה ובתחי­נה\" (כלשון הרמב\"ם<sup data-n=\"1127\">33</sup>), שזהו רק כשדיבור התפלה הוא מתוך רגש הלב, ולכן צריך האדם לעורר את לבו כדבעי, שאז בקשת צרכיו היא כמתאים להמבקש צרכיו מאת המלך.\n[ע\"ד שמצינו בתפלה גופא, שסדר ה­תפלה הוא, שבתחילה \"מגיד שבחו של הקדוש ברוך הוא ואחר כך שואל צרכיו שהוא צריך להם בבקשה ובתחינה ואחר כך נותן שבח והודי' לה' על הטובה שהש­פיע לו\"<sup data-n=\"1128\">34</sup>, זאת אומרת, שכדי שבקשת צרכיו תהי' באופן המתאים, צריך להק­דים לפני' סידור שבחו של מקום (וכן ל­סיים בשבח כו')].\nד. ביאור שני הסדרים הנ\"ל בג' תפ­לות בעבודת השם, יובן בהקדם הביאור הפנימי בכלל הנ\"ל ד\"במעשה בראשית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\", שהם שני סדרים בעבו­דת ה' [שהרי הכלל ד\"במעשה בראשית היום הולך אחר הלילה\" קאי גם בעניני מצוה ועבודת השם הקשורים בזמן, שהיום הולך אחר הלילה].\nהסברת הענין<sup data-n=\"1129\">35</sup>:\n\"מעשה בראשית\" מורה על העבודה להמשיך קדושה בעניני העולם, ו\"קדשים\" היא העבודה בענינים שהקדושה היא ב­התגלות בהם. וכך הוא בעבודת כאו\"א בפרט, שהאדם כלול מנשמה וגוף: \"קד­שים\" מורה על העבודה המביאה לידי גילוי קדושת הנשמה, שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"1130\">36</sup>; ו\"מעשה בראשית\" היא עבודת זיכוך הגוף (וכן עניני העולם).\nוזהו גם טעם ההבדל, ש\"במעשה ברא­שית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\":\nב\"קדשים\" (גם) ההתחלה היא ב\"יום\" ואור, כיון שכל עיסוקו הוא בדברים ש­הקדושה בהם היא בהתגלות (אור וגי­לוי); ואח\"כ עולה מחיל אל חיל, להוסיף ולעלות באור הקדושה (כהכלל<sup data-n=\"1131\">37</sup> מעלין בקודש), שמזה מובן, שלא זו בלבד שה­\"לילה\" הבא לאחרי ה\"יום\" (בקדשים) הוא ג\"כ ענין של אור וקדושה, אלא עוד זאת, ש\"לילה\" זה הוא למעלה מאור היום ש­",[["1125","31","ל' הלח\"מ."],["1126","32","להעיר מהשינויים בל' הרמב\"ם: בסהמ\"צ \"שצונו לעבדו\" (ורק בהמשך הענין \"שהוא ציווי לתפלה\"); במנין המצות בריש ס' היד \"להתפלל אליו\"; במנין המצות על סדר ההלכות (ובכותרת להל' תפלה) \"לעבוד. . בתפלה\"; בריש הל' תפלה \"מ\"ע להתפלל\"."],["1127","33","שם ה\"ב. — וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221116\" data-slug=\"likkutei-sichot\" data-id=\"1300221116\">לקו\"ש חכ\"ב ע' 116</a> ואילך."],["1128","34","רמב\"ם שם."],["1129","35","להעיר מהמבואר בכ\"מ בתיווך שני הענ­ינים, אם חשך קדם לאור או להיפך (וכן אם לילה קדם ליום או להיפך) ע\"ד החסידות — ראה ס' ה­ערכים חב\"ד ערך אור ביחס לחשך סעיף ב ואילך. וש\"נ."],["1130","36","ל' התניא רפ\"ב."],["1131","37","ברכות כח, א. וש\"נ."]]],[1301670191,"לפניו\n— כי ב\"אור\" גופא יש שני אופנים: אור היום, דהיינו התגלות אלקית שיכולה ל­התקבל אצל האדם באופן שנשאר במצי­אות; ואור עליון יותר, אור סתום, הנקרא בשם \"חושך\"<sup data-n=\"1132\">38</sup> כי הוא למעלה מתפיסת האדם, וכאשר מדריגה זו מתגלה ה\"ה פועלת על האדם שיתבטל ממציאותו<sup data-n=\"1133\">39</sup>;\nוזהו ש\"בקדשים לילה הולך אחר ה­יום\", שההתחלה היא בענין האור הגלוי, ואח\"כ מגיעים לאור נעלה יותר, אור סתום, שלמעלה מגדר נבראים.\nמשא\"כ ב\"מעשה בראשית היום הולך אחר הלילה\", וכסדר \"ברייתו של עולם. . ויהי ערב (ואח\"כ) ויהי בוקר\", \"ברישא חשוכא והדר נהורא\"<sup data-n=\"1134\">40</sup> — כי מטרת עבודה זו היא הפעולה בעולם, ולכן התחלת ה­עבודה היא מ\"לילה\", כי בתחילת העבודה העולם הוא במצב של \"חושך\", עולם מ­לשון העלם<sup data-n=\"1135\">41</sup>, שאין הקדושה נראית ונג­לית בו; וע\"י עבודת האדם באים מ\"לילה\" ל\"יום\", שמאירים את החושך, עד שמהפ­כים את החושך עצמו לאור.\nה. ומזה יובן גם בנוגע לענין התפלה, שיש בו שני סדרים אלו:\nבעבודת התפלה ישנם<sup data-n=\"1136\">42</sup>: היגיעה לג­לות אור נשמתו, ע\"י התעוררות אהבת ה' ויראתו בלבו (וזוהי ה\"עבודה שבלב\" שב­תפלה); ואח\"כ ישנו הדיבור דתפלה, שאין כוונת הלב מספיקה, אלא צריך לבטא את תיבות התפלה בשפתים הגשמיים<sup data-n=\"1137\">43</sup>, וכמ­בואר בארוכה בספר התניא<sup data-n=\"1138\">44</sup>, שזהו לפי שתכלית התפלה היא לזכך את הגוף וה­נפש הבהמית שבאדם, שלזה צריכים (גם) הדיבור דתפלה.\nוהם שני הסדרים שבג' התפלות:\nבענין דביקות הנשמה באלקות, הרי התחלת עבודת היום היא בתפילת שחרית, יום ואור; והסיום ושלימות דדביקות זו הם בתפילת ערבית, שאז מגיע האדם ל­אור הסתום שלמעלה מגדר הנבראים, הפועל בו מצב של ביטול מוחלט ל­הקב\"ה.\n[ונמצא, שמצד גדר זה שבתפילה, תפי­לת ערבית היא למעלה מתפילת שחרית ומנחה<sup data-n=\"1139\">45</sup>; וזה מתאים עם הא דדוקא יעקב אבינו תיקן תפילת ערבית, כי יעקב הוא בחיר שבאבות<sup data-n=\"1140\">46</sup>].\nאבל להלכה נקטינן (כנ\"ל), שסדר ג' התפלות הוא ערבית שחרית ומנחה, כי תכלית הכוונה של בריאת העולם וירידת הנשמה למטה היא לעשות לו ית' דירה בתחתונים דוקא, כמבואר בארוכה בספר התניא<sup data-n=\"1141\">47</sup>, דהיינו בעוה\"ז הגשמי שהוא \"תחתון. . שאין תחתון למטה ממנו בענין הסתר אורו ית' וחושך כפול ומכופל\",",[["1132","38","בחי' \"ישת חשך סתרו\" (ראה — לענין תפי­לת ערבית — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ס\"ע א'שצז</a>. ובביאוה\"ז להצ\"צ (ע' צא) \"כחשיכה כאורה\")."],["1133","39","וגם מטעם זה נקרא \"חושך\", מצד הביטול והעדר המציאות הנפעל עי\"ז בהאדם."],["1134","40","שבת עז, ב."],["1135","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">לקו\"ת שלח לז, ד</a>. ובכ\"מ."],["1136","42","ראה בארוכה בזה קונטרס העבודה פ\"א. ד\"ה אין עומדין תרע\"ח. לקוטי דיבורים ח\"ד בהוס­פות (תשעו, א ואילך). ועוד."],["1137","43","שו\"ע או\"ח סק\"א ס\"ב ובמג\"א שם סק\"ב. שו\"ע אדה\"ז שם (ס\"ב וס\"ד)."],["1138","44","רפל\"ז (מז, א ואילך). שם רפל\"ח. ועוד."],["1139","45","ראה זח\"א קלג, א. נת' בביאורי הזהר לאדמו\"ר האמצעי (יג, ד ואילך) ולהצ\"צ (ע' פה ואילך). ושם, שזהו הטעם ש\"תפלת ערבית רשות\" (ברכות כז, ב), כי היא למעלה מחובה. ע\"ש. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251156\" data-slug=\"likkutei-sichot\" data-id=\"1300251156\">לקו\"ש חכ\"ה ע' 156</a> ואילך. וש\"נ. וראה שם בביאור ב' הענינים שבתפילת ערבית (סיום עבודת היום או התחלתה) ע\"ד החסידות."],["1140","46","ראה ב\"ר ר\"פ עו. זהר שבהערה הקודמת. ועוד."],["1141","47","פל\"ו."]]],[1301670192,"וזהו ע\"י שמהפכים את חושך העולם ל­אור;\nוכן הוא בענין התפלה, שעיקר ענין התפלה הוא הדיבור שבתפלה, שעל ידו נעשה זיכוך הגוף והנפש הבהמית, ה­עבודה במקום החושך דוקא, ולכן סדר ה­תפלות הוא ערבית שחרית מנחה, שה­עבודה היא במקום החושך, ובזה עולים מדרגא לדרגא, בהמשכת קדושה בחושך, עד שמהפכים את החושך לאור.\nולפי סדר זה, תפלת ערבית היא התח­לת העבודה, והסיום ושלימות דג' תפילות הוא בתפלת מנחה. וזה מתאים עם המבואר בכ\"מ<sup data-n=\"1142\">48</sup> שעיקר המעלה דתפלת מנחה היא בזה שזמנה הוא באמצע היום, כשאדם עסוק בפרנסתו כו' ומ\"מ מפסיק ועומד להתפלל, והיינו מעלת העבודה כפי שהיא קשורה עם עניני העולם דוקא.\n[ושני סדרים אלו נרמזים גם בנוסח ברכות ק\"ש של ערבית — \"גולל אור מפני חושך וחושך מפני אור\"<sup data-n=\"1143\">49</sup>: \"גולל אור מפני חושך\" מדגיש שהחושך (לילה) בא לאחרי האור (יום), שזהו לפי הסדר דת­פלת ערבית היא סיום עבודת היום; \"וחו­שך מפני אור\" היינו מה שחושך הלילה הוא הקדמה לאור היום שלאחריו, כהסדר ערבית שחרית ומנחה].\nויש לומר, שזהו גם הטעם שתפלת מנחה קשורה עם אליהו הנביא, מבשר הגאולה<sup data-n=\"1144\">50</sup>, \"לעולם יהא אדם זהיר בתפלת המנחה שהרי אליהו לא נענה אלא בתפלת המנחה\"<sup data-n=\"1145\">51</sup> — כי זהו העילוי דימות המשיח, שאז \"יזדכך גשמיות הגוף והעולם ויוכלו לקבל גילוי אור ה' שיאיר לישראל\"<sup data-n=\"1146\">52</sup>, ובאופן ש\"יגיה חשך האומות גם כן\"<sup data-n=\"1146\">52</sup>, שהעולם כולו ייעשה דירה לו ית'.\n<span data-k=\"q\">(משיחת ליל ו' תשרי תשמ\"ה)</span>",[["1142","48","סדר היום תפלת מנחה (הובא באוה\"ת לנ\"ך ע' עב). סד\"ה לעולם יהא אדם תרע\"ז, תרצ\"א (בסה\"מ קונטרסים ח\"א). ובכ\"מ.\nוראה אוה\"ת שם (ע' עא ואילך) בביאור מעלת תפלת מנחה (בין הערביים), שהיא ביטול היש לאין, בירור ההסתר וחושך הנמשך משם אלקים, ולכן שייכת ליצחק, \"צחוק עשה לי אלקים\". ע\"ש באורך."],["1143","49","ברכות יא, ב."],["1144","50","רש\"י עירובין מג, ריש ע\"ב. רש\"י עה\"ת בחוקותי כו, מב. וראה פסיקתא רבתי ספל\"ו (לה). ועוד."],["1145","51","ברכות ו, ב."],["1146","52","ל' התניא ספל\"ו."],["1146","52","ל' התניא ספל\"ו."]]],[1301670193,"<h3>שיחה ג</h3>\nא. \"ויהי<sup data-n=\"1148\">1</sup> בעת יחם הצאן ואשא עיני וארא בחלום והנה העתודים העולים על הצאן עקודים נקודים וברודים\", וב­פרש\"י \"וברודים, תרגומו<sup data-n=\"1149\">2</sup> ופציחין [היינו פתוחים]. . חוט של לבן מקיף את גופו סביב וחברבורות<sup data-n=\"1150\">3</sup> שלו פתוחה ומפולשת מזו אל זו<sup data-n=\"1151\">4</sup> ואין לי להביא עד מן המקרא\".\nוהנה הראב\"ע כותב בפירושו<sup data-n=\"1152\">5</sup> ש­\"טלואים הם הברודים\"<sup data-n=\"1153\">6</sup>, וברד\"ק כאן<sup data-n=\"1154\">7</sup> פי' \"וברודים, זכרו במקום טלואים ואמר ברודים כי לבנותם הי' כמו הברד\"<sup data-n=\"1155\">8</sup>.\nוצריך ביאור, מדוע העדיף רש\"י את פירוש התרגום, ולא פי' כהראב\"ע (וה­רד\"ק) שברודים היינו טלואים (שנזכר לעיל בקרא<sup data-n=\"1156\">9</sup>). דלפי' הראב\"ע מובן שאין כאן צורה חדשה על הצאן שלא נזכרה עד עתה, אבל לפרש\"י ש\"ברודים\" היינו \"חוט של לבן מקיף את גופו סביב כו' פתוחה ומפולשת כו'\", צריך ביאור, הרי לעיל בכתוב נזכרו רק \"עקודים נקודים וטלואים\"<sup data-n=\"1157\">10</sup> ולא ברודים, ונמצא שבחלום יעקב נתחדשה צורה חדשה בצאן שלא נזכרה עד עתה.\nב. לכאורה יש לומר שרש\"י אזיל כאן לשיטתי'. דהנה בתוכן פסוקים אלו<sup data-n=\"1158\">11</sup>, \"וארא בחלום והנה העתודים העולים על הצאן עקודים גו' ויאמר אלי מלאך האלקים בחלום גו' שא נא עיניך וראה כל העתודים העולים גו' כי ראיתי את כל אשר לבן עושה לך\", שקו\"ט במפר­שים, שהרי כבר מפורש לעיל שצאן יעקב הולידו עקודים נקודים כו' ע\"י המקלות<sup data-n=\"1159\">12</sup>, \"ויפצל בהן פצלות לבנות גו' ויצג את המקלות גו' ויחמו הצאן אל המקלות ותלדנה הצאן עקודים נקודים וטלואים\" — וא\"כ מה נתחדש בזה שראה בחלום \"העתודים העולים על הצאן עקודים נקודים וברודים\", והמלאך אמר לו \"שא נא עיניך וראה כל העתודים העולים על הצאן עקודים גו'\"?\nוביארו המפרשים בכמה אופנים, ו­מהם:\nא) שלידת עקודים נקודים כו' היתה על ידי פעולה הטבעית דהמקלות, וכ­ידוע<sup data-n=\"1160\">13</sup> שצורת התולדות תלוי' בצורה המצטיירת במחשבת האם, וחלומו של",[["1148","1","פרשתנו לא, י."],["1149","2","בדפוס ראשון ושני וכמה כת\"י רש\"י (ש­תח\"י) \"כתרגומו\"."],["1150","3","בדפוס ראשון ושני וכמה כת\"י רש\"י (ש­תח\"י) \"חברבורת (חברבורה)\", בלי וא\"ו — ל' יחיד (וכן ליתא וא\"ו בתחלתו). ולכאורה כצ\"ל, שהרי ממשיך (גם בדפוסים הנפוצים) בל' יחיד \"פתוחה ומפולשת\"."],["1151","4","בדפוסי רש\"י הנפוצים הובא ס\"א \"מזן אל זן\", וכ\"ה בדפוס ראשון ושני וכמה כת\"י רש\"י (שתח\"י)."],["1152","5","לעיל ל, לט. וראה גם שם, לה."],["1153","6","אלא שמסיים שם \"כי שם כלל הוא\", ד\"טלוא\" הוא שם כללי. וכ\"כ שם, לא (לט) ואילך."],["1154","7","וכ\"כ בס' השרשים שלו ערך ברד \"שיש להם כתמים לבנים כמו ברד וכן סוסים ברדים אמצים\" (זכרי' ו, ג)."],["1155","8","ולפ\"ז גם להרד\"ק הוא אותה הצורה ד­טלואים אלא דברוד מתאר לבנוניתו. וראה גם ראב\"ע לעיל ל, לא (לט). רלב\"ג כאן בביאור המלות."],["1156","9","ל, לב. לג. לה. לט."],["1157","10","ל, לט."],["1158","11","לא, י­יב."],["1159","12","ל, לז ואילך."],["1160","13","ראה גם ראב\"ע ל, לט. ועוד."]]],[1301670194,"מלאך ודברי המלאך היו נבואה מאת ה', שהבטיח לו הצלחה טבעית בהשתדלותו בפעולות טבעיות<sup data-n=\"1161\">14</sup> אלה.\nב) שהלידה דעקודים נקודים כו' היתה בדרך נס<sup data-n=\"1162\">15</sup>, וכבשורת המלאך, ו­פעולת יעקב עם המקלות היתה רק \"כדי<sup data-n=\"1163\">16</sup> להעלים הנס ולהסתירו במעשה הטבע, ע\"ד שמצינו באלישע שאמר לגחזי<sup data-n=\"1164\">17</sup> קח משענתי בידך גו' ושמת משענתי על פני הנער גו', וכמו שאמר הקב\"ה ליהושע<sup data-n=\"1165\">18</sup> במלחמת עי שים לך אורב לעיר כו' אף על פי שמלחמה זו על ידי נס היתה ופועל המקלות אחר דברי המלאך הי'\".\nג) שהיו כאן שני ענינים נפרדים, הן לידת עקודים וכו' שבאה באופן טבעי ע\"י המקלות דיעקב, והן לידה שהיתה בדרך נס בלי כל קשר לפעולת המקלות (ועל זה בא כאן סיפור החלום ודברי המלאך)<sup data-n=\"1166\">19</sup>.\nוהנה את\"ל (כב' האופנים הראשונים) שב' ענינים אלו שייכים זל\"ז והשגחת ה' המוזכרת בחלום יעקב קשורה עם פעו­לות יעקב בהמקלות<sup data-n=\"1167\">20</sup>, מובן בפשטות, שלא מסתבר כלל לומר שכאן אומר הפסוק דבר חדש במין וצורת הצאן שנולדו, אלא עקודים נקודים ברודים הן הן המינים שנפרטו לעיל, עקודים נקו­דים טלואים.\nאבל את\"ל (כאופן הג') שחלום יעקב ונבואת ה' הם ענין בפ\"ע מפעולת המק­לות, יש לומר בפשטות, שפעולות יעקב במקלות והנס שהובטח לו בחלום גרמו להולדת שני מיני צאן: פעולת יעקב במקלות גרמה שיוולדו \"עקודים נקודים וטלואים\", ואילו על ידי נס נולדו \"עקו­דים נקודים וברודים\".\nג. והנה רש\"י כאן בד\"ה \"והנה העתו­דים\" פי' \"אע\"פ שהבדילם לבן כולם שלא יתעברו הצאן דוגמתן, היו המלאכים מביאין אותן מעדר המסור ביד בני לבן לעדר שביד יעקב\" — הרי מפורש, שלדעת רש\"י, הבטחת השם בחלום יעקב היתה ענין בפני עצמו מהולדת הצאן על ידי המקלות, שנולדו עקודים נקודים כו' על ידי זכרים כאלו שהובאו בדרך נס<sup data-n=\"1168\">21</sup> על ידי המלאכים מעדרו של לבן<sup data-n=\"1169\">22</sup>.",[["1161","14","ראה רלב\"ג כאן. אברבנאל כאן. ולדברי­הם מה שלקח יעקב המקלות לא עשה זה מעצמו אלא על פי המלאך [וכן מפורש במדרש לקח טוב ל, לט. רבינו בחיי שם, לח (אבל ביאורו בזה הוא לכאורה דלא כדבריהם)].\nובטור הארוך (ל, מב בסופו), לאחרי שהביא יש מפרשים כי איננו טבע שיולידו נקודים כו' בכח המקלות אלא דרך נס, ומה שהוצרך מקלות לנס כי כן דרך כל הנסים למעט הנס כו', מסיים \"ואינו נראה כי ודאי טבע הוא וכן דעת רבותינו ז\"ל\"."],["1162","15","ראה כלי יקר לא, ח. אוה\"ח לא, י."],["1163","16","ל' הרא\"ם (ל, לט), והוא ע\"פ האמונה והבטחון להרמב\"ן (פט\"ו). רבינו בחיי שם. ועד\"ז הובא ביפה תואר השלם לב\"ר פע\"ג, ז ד\"ה מלאכי השרת. הואיל משה (באר התורה) כאן."],["1164","17","מלכים ב ד, כט."],["1165","18","יהושע ח, ב."],["1166","19","ראה ראב\"ע לא, ט. רמב\"ן שם, יוד. פי' הב' ברא\"ם הנ\"ל."],["1167","20","וראה גם רבינו בחיי שם ל, לז בסופו: והי' הענין הזה ליעקב דבר חכמה וסוד הטבע מעורב בנס כי הי' ענין טבעי מצד פצול המקלות ומצד אחר הי' נס גמור. ע\"ש. וראה גם מדרש לקח טוב שם. רבינו בחיי שם, לח בטעם הב'."],["1168","21","ודוחק גדול לומר לפרש\"י שרצה יעקב להעלים הנס בטבע בפעולת המקלות (כי מפשטות ל' הכתוב ורש\"י משמע שע\"י המקלות נולדו בפועל עקודים נקודים וטלאים). ובפרט דאז הו\"ל לרש\"י לכותבו בפירוש."],["1169","22","במשכיל לדוד, דאף שהמלאכים הביאו הצאן מעדר לבן, אפ\"ה יעקב לקח לו מקל לבנה כו', שלא רצה לסמוך על הנס כו', ועוד דחש יעקב ליהנות ממעשה נסים. ועד\"ז בבאר בשדה (ל, לט).\nומשמע קצת דמפרש שפעולת המלאכים (בדרך נס) היתה רק בתחלה.\nאבל מזה שרש\"י לא פירש כאן מתי היתה פעו­לת המלאכים ומתי המקלות וכיו\"ב (ראה רמב\"ן עה\"ת ובחיי הנ\"ל שקו\"ט בזה), משמע לכאורה, דפעולת המלאכים היתה בסוף הזמן, או במשך כל הזמן \"משעה ראשונה עד אחרונה\" (גו\"א כאן. וראה שם שעכצ\"ל שדבר המלאך הי' רק בסוף שני ה­עבודה דאל\"כ \"איך יעבור. . ארץ אבותיך\"). ולהעיר מנחלת יעקב לא, ז."]]],[1301670195,"ומש\"ה מפרש רש\"י, דזה שהכתוב שינה בלשונו מ\"טלואים\" ל\"ברודים\" הוא לפי שהם שתי צורות שונות, ד\"טלואים\" הם סתם \"חברבורות רחבות\"<sup data-n=\"1170\">23</sup> ואילו \"ברודים\" היינו \"פציחין\", ש\"חוט של לבן מקיף את גופו סביב וכו'\"<sup data-n=\"1171\">24</sup>.\nאלא שצריך ביאור (עכ\"פ בפנימיות הענינים), מאי טעמא לחילוק זה, שהצאן שנולדו על ידי פעולת המקלות היו \"עקודים נקודים וטלואים\", ואילו ע\"י המלאכים הובאו (בדרך נס) \"עקודים נקודים וברודים\" — ברודים במקום טלואים?\nד. ויש לומר, שהביאור בזה נרמז ב­פרטי לשונות רש\"י גופא בפי' \"ברודים\" — וכפי שהובא הרבה פעמים פתגם אדמו\"ר הזקן שפירוש רש\"י על התורה הוא \"יינה של תורה\"<sup data-n=\"1172\">25</sup>, היינו, שבלשון רש\"י נרמזים כמה ענינים שע\"ד הסוד (\"נכנס יין יצא סוד\"<sup data-n=\"1173\">26</sup>).\nוכמו\"כ בעניננו, דהנה ידוע ש\"עקו­דים נקודים ברודים\" מרמזים על ג' העולמות הכלליים (כמבואר בכתבי ה­אריז\"ל<sup data-n=\"1174\">27</sup>), וכל זה הוא \"אשר לבן עושה לך\"<sup data-n=\"1175\">28</sup>, כי \"לבן הוא סוד לובן העליון אשר הוא קודם כל האצילות הזה\"<sup data-n=\"1174\">27</sup>, היינו א\"ס ב\"ה שהוא פשוט בתכלית הפשיטות (בדוגמת מראה לבן, שאינו גוון המתהווה \"על ידי צבע\" אלא מורה על פשיטות)<sup data-n=\"1177\">29</sup>, וההתגלות של \"לובן העליון\" בג' העולמות דעקודים נקודים וברודים היא על ידי יעקב דוקא<sup data-n=\"1178\">30</sup>.\nועפ\"ז יש לבאר גם פרטי הלשונות והענינים בלשון רש\"י בפירוש \"ברודים\" — (א) חוט של לבן, חוט דוקא, (ב) \"מקיף את גופו סביב\", (ג) \"חברבורות שלו פתוחה ומפולשת מזו אל זו\" — שג' עני­נים אלו מכוונים לג' הענינים שבהמשכת \"לובן העליון\" בעולם הברודים, כדלקמן ס\"ו.\nוע\"פ הקדמה זו יתבאר ג\"כ מדוע חידוש זה שייך דוקא לפעולת המלאכים",[["1170","23","רש\"י לעיל ל, לב."],["1171","24","ואין להקשות (ראה אוה\"ח עה\"פ) שבתנאי שהתנה יעקב עם לבן לא נאמר אלא \"כל אשר איננו נקוד וטלוא בעזים וחום בכשבים\" (ל, לג) — שהרי זהו מה ש\"ותחלף את משכורתי\" — \"היית משנה תנאי שבינינו מנקוד לטלוא ומעקודים<sup data-n=\"e30\">*</sup> לברודים\" (לא, מא ובפרש\"י).\nוראה בארוכה גו\"א, דלפרש\"י (ל, לו) הסיר לבן גם מה שלא התנו ביניהם. ולכן לאחר שהסיר כל אשר לבן בו (לא כפי המדובר) הרי כל אשר לבן בו נשאר בשכרו של יעקב."],["1172","25","\"היום יום\" כט שבט."],["1173","26","עירובין סה, סע\"א. וראה בארוכה אמרי בינה לאדמו\"ר האמצעי (בעל יום ההולדת ויום ההילולא דט' כסלו, ובעל הגאולה דיו\"ד כסלו — כדלקמן בפנים) שער הק\"ש ספנ\"ג ואילך, ש\"יינה של תורה\" הוא רזין דאורייתא."],["1174","27","ע\"ח שער העקודים בתחלתו."],["1175","28","לא, יב."],["1174","27","ע\"ח שער העקודים בתחלתו."],["1177","29","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו\"א</a> סוף פרשתנו (כד, ב). תו\"ח שם (לז, ד ואילך). וראה בארוכה (ע\"ד מראה לבן) עטרת ראש שער יוהכ\"פ פ\"ה. מאמרי אדמו\"ר האמצעי ויקרא (כרך ב) ע' תפד ואילך."],["1178","30","ראה תו\"ח שם."],["e30","*","כ\"ה בדפוסי רש\"י לפנינו. ובדפוס ראשון \"לעקודים\", — שלפ\"ז הכל המשך אחד, מנקוד ל­טלוא לעקודים לברודים. ובדפוס שני \"בנקוד וטלוא עקודים וברודים\". וראה רא\"ם ומפרשי רש\"י. וא­כ\"מ."]]],[1301670196,"ולא לפעולת יעקב עם המקלות, כדלקמן שם.\n[ויש להוסיף ולהעיר על ההשגח\"פ, שהפרטים האמורים ב\"עולם הברודים\" המרומזים בלשון רש\"י בפרשתנו, נת­בארו בארוכה בדרושי כ\"ק אדמו\"ר ה­אמצעי<sup data-n=\"1179\">31</sup> — שיום ההילולא ויום ההולדת שלו (ט' כסלו), וכן חג הגאולה שלו (יו\"ד כסלו), חלים בכמה שנים בשבוע דפ' ויצא, או עכ\"פ \"מתברכים\" הם מש\"פ ויצא (ובשנה זו{*} חל יום ההולדת ויום ההילולא בש\"ק פ' ויצא עצמה)].\nה. וביאור הענין:\nידוע מה שאיתא בס' העקידה<sup data-n=\"1180\">32</sup> שע\"י שני אופנים יכולים אנו לידע גדולת הבורא, הא' מהנהגת הטבע, היינו מזה שהעולם מתנהג תמיד באותו טבע וסדר בלי שינוי ובלי הפסק, שבזה ניכר כח הא\"ס, והב' מההנהגה שלמעלה מהטבע, היינו מענין הנסים וביטול הטבע, שבזה ניכרת גדולת הבורא עוד יותר.\nוב' הנהגות אלו, שרשן מב' המשכות מהקב\"ה<sup data-n=\"1181\">33</sup>, ההמשכה שבבחי' בלי גבול וההמשכה שבבחי' גבול ומדה, דהנהגת הטבע היא מההמשכה שבבחי' גבול ו­מדה, שהוא בחי' האור והחיות הפנימי המתלבש בעולמות בפנימיותם להחיותם, שזהו מקור הנהגת כל העולמות וה­נבראים, וההנהגה שלמעלה מהטבע שרשה מההמשכה שבבחי' בלי גבול.\nועפ\"ז יש לבאר שתי הדיעות הנ\"ל (ס\"ב) אם עיקר הולדת הצאן עקודים נקודים כו' היתה על ידי פעולה טבעית (אלא שהיתה לו בזה נבואה מאת ה' שיצליח בזה בהשגחתו ית'), או שעיקר הולדת הצאן היתה בדרך נס — בפני­מיות הענינים:\nובהקדם המבואר דבחי' יעקב — אותיות \"יבקע\"<sup data-n=\"1182\">34</sup> (וכדאיתא בזהר<sup data-n=\"1183\">35</sup> לענין האושפיזין דסוכות, שיעקב אומר ה­כתוב<sup data-n=\"1184\">36</sup> \"אז יבקע כשחר אורך\") — מורה על המשכת ובקיעת אור ה\"קו\"<sup data-n=\"1185\">37</sup> לאחרי הצמצום, וזו היתה כל עבודת יעקב ב­צאן לבן, להמשיך בחי' \"לובן העליון\", אור א\"ס שלמעלה מהצמצום, בעולמות עקודים נקודים כו', שהמשכה זו היא על ידי אור הקו, שבוקע את חושך הצמצום.\nוהנה ידוע<sup data-n=\"1186\">38</sup>, שיש ב' שיטות בנוגע לאור הקו: א) הקו הוא ההמשכה שבבחי' מדה וגבול, והיינו דשרשו הוא מבחי' הגבול שבאין סוף (כי הא\"ס, כשם שיש לו כח בבלתי בעל גבול כן יש לו כח בגבול<sup data-n=\"1187\">39</sup>), ב) הקו הוא ההמשכה שבבחי' בלי גבול, והיינו דשרשו הוא מבחי' אור א\"ס הבלתי בעל גבול, אלא שזהו כמו",[["1179","31","בתו\"ח פרשתנו. וביאור בחי' עקודים נקודים וברודים בארוכה — בתו\"ח פ' נח (סה, ד ואילך)."],["1180","32","פ' בא עה\"פ החודש גו' (שער לח), הובא ונת' באוה\"ת בראשית יח, ב ואילך. ד\"ה החודש תרנ\"ד (סה\"מ תרנ\"ד ע' קלא ואילך), תרס\"ו (המשך תרס\"ו ע' קנו ואילך) ותרע\"ח (הב' — סה\"מ תרע\"ח ע' רכה ואילך). ועוד."],["1181","33","ראה סד\"ה החודש תרס\"ו (ע' קסג). ובכ\"מ."],["1182","34","עץ חיים שער הכללים פ\"י. שם שער לב (שער הארת המוחין) ספ\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380111\" data-slug=\"likkutei-torah\" data-id=\"4001380111\">לקו\"ת צו ח, סע\"ד</a> ואילך (ושם מע\"ח של\"א ספ\"א. והוא בשל\"ב הנ\"ל). סידור שער הסוכות רנז, סע\"ד ואילך. מאמרי אד­מו\"ר האמצעי לנ\"ך ריש ע' רלד."],["1183","35","ח\"ג קד, א (וראה ניצוצי אורות שם)."],["1184","36","ישעי' נח, ח."],["1185","37","ראה ספר הליקוטים דא\"ח דהצ\"צ מע' יעקב סעיף ד. וש\"נ."],["1186","38","ראה המשך תרס\"ו ע' קסב ואילך. ע' קצד ואילך. ועוד."],["1187","39","עבודת הקודש ח\"א רפ\"ח. דרך אמונה לב­על עבוה\"ק פ\"ב (בהוצאת קה\"ת, תשמ\"ח — ע' יג)."]]]]});
